REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(1313, 'zhCN', '哨兵岭的药水', '我知道民兵队靠我的药水维持，可那些该死的盗贼偷走了我一半存货——我怎么可能补得上？$B$B本周早些时候，迪菲亚偷走了三箱准备分发给人民民兵队的药物。我们的防卫者需要那些药水！把它们取回来，我也会给你一些，护你平安。', '从西部荒野的迪菲亚营地取回被盗的药水。', '', '将药水归还给伊多娜·威瑟', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17000, 'zhCN', '失窃的补给', '该死的迪菲亚闯进来洗劫了我们的补给！我们到底招他们惹他们了？除了在他们决定反叛之前喂饱他们之外。好吧，我可不容忍！$B$B你能在东边不远处、贾罗德登陆点找到他们的营地。给他们点颜色看看，然后把那些补给带回来，我会给你应得的补偿。', '将失窃的补给归还给马科伦老爹。', '', '前往马科伦葡萄园找马科伦老爹。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17001, 'zhCN', '奢靡的订单', '啊，英雄，能占用你一点时间吗？事情是这样，我碰上了一个绝佳的生意机会，正需要你的专长。我最近收到报告，贾斯佩洛德矿洞里出现了蜘蛛泛滥——恶心透顶的东西。对狗头人来说是坏消息，对我们却是大好机会！$B$B显然，这些蜘蛛会产出一种非常独特、也非常宝贵的丝——止水砍伐者！我推测这跟它们以矿洞内外的狗头人矿工为食有关，不过这只是个理论。总之，如果你能给我带 4 份止水砍伐者，我会重重酬谢你！', '将 4 份止水砍伐者归还给萨瑞恩·博丁。', '', '将 4 份止水砍伐者归还给萨瑞恩·博丁。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17002, 'zhCN', '主人的命令', '你好！我刚被指派协助一个研究项目，我想这或许是我向主人证明自己已能担当更多职责的大好机会。我们正在研究魔法枯竭，为此需要已耗尽的奥术物质样本。我想你可以从石冢湖附近的迪菲亚盗贼法师身上收集到。他们很危险，但我听说他们近来法术过度施放，恰好符合我们的需要。你愿意取回十枚他们的耗尽的法力宝石吗？我保证会给你报酬。如果一切顺利……说不定我就能试着施放比法师护甲更厉害的东西了！', '取回 10 枚耗尽的法力宝石并返回阿佐拉之塔。', '', '取回 10 枚耗尽的法力宝石并返回阿佐拉之塔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17003, 'zhCN', '黏滑的解决之道', '你好！如果这听起来有点古怪，请见谅，但你愿意协助一个研究任务吗？主人已经开始研究……嗯，唾液中的魔法残留。准确地说，是鱼人的唾液。他想观察残留的奥术能量在生物材料中如何反应。我知道，有点恶心，但很迷人，对吧？东谷营地附近，湖泊南北两侧都有鱼人潜伏者和觅食者。如果你能收集十份它们的唾沫样本并带回来，我会确保你得到应有的报酬。我还专门准备了收集用的小瓶。', '取回 10 份黏滑的鱼人唾沫样本并返回阿佐拉之塔。', '', '取回 10 份黏滑的鱼人唾沫样本并返回阿佐拉之塔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17004, 'zhCN', '解除豺狼人的武装', '鱼人泛滥已经够糟了，我们还有豺狼人在啃噬我们的边界。问题总是一个接一个！$B$B为了王国和艾尔文的人民，趁这威胁还没来得及变成真正的麻烦，就把它消弭于萌芽。给我从豺狼人小崽身上带 6 把豺狼人匕首，从它们的外围巡逻者身上带 10 把豺狼人斧头。$B$B你可以在石冢湖的北端和西北端找到它们的营地。如果你做到了，暴风城军队一定会相应地奖赏你。', '取回 6 把豺狼人匕首和 10 把豺狼人斧头，返回艾尔文东部大桥处的卫兵托马斯那里。', '', '取回 6 把豺狼人匕首和 10 把豺狼人斧头，返回艾尔文东部大桥处的卫兵托马斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17005, 'zhCN', '最后的纪念', '我最亲爱的伊迈尔达。即便你已迁往暴风城，我希望你知道，没有任何距离能将我们分开。我对你的爱，如同无尽燃烧的太阳。你将永远占据我心中一角。永不遗忘。$B$B—伊森$B$B我应该试着把这封便条还给伊迈尔达。她大概会想知道伊森的感受。', '将模糊的便条归还给暴风城的伊迈尔达。', '', '将模糊的便条归还给暴风城的伊迈尔达。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17006, 'zhCN', '国王的审判', '英雄，我有个麻烦。我们的侦察兵报告说，一批运往湖畔镇的货遭到迪菲亚拦截。我要你取回那批货，并给迪菲亚应得的教训。$B$B我不认为他们有时间把货运到某个安全屋。似乎一小股迪菲亚正在东边不远处看守着货物。$B$B很遗憾我抽不出人手，但如果你杀掉 8 名迪菲亚强盗、带着货物回来找我，我会确保你得到应有的补偿。', '击杀 8 名迪菲亚强盗，将食人魔法师之棍归还给岭角塔的卫兵雅各布。', '', '击杀 8 名迪菲亚强盗，将食人魔法师之棍归还给岭角塔的卫兵雅各布。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17007, 'zhCN', '送往湖畔镇', '呃，等一下，英雄。听着，我不愿再求你帮忙，但我实在抽不出任何人手。你能好心把这箱补给送到湖畔镇吗？$B$B我想所罗门镇长会想听听你为他子民所做的壮举，我也确信他会因你的善行而奖赏你。', '将食人魔法师之棍交给湖畔镇的所罗门镇长。', '', '将食人魔法师之棍交给湖畔镇的所罗门镇长。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17008, 'zhCN', '收复收成', '真遗憾，$N。迪菲亚占领了镜湖果园，正在劫掠收成。我还记得小时候，母亲为我做她拿手的镜湖苹果派。我真希望能和驻军里的兄弟们分享。$B$B我说，你看上去像是个见多识广的$R。你能去驻军东北边的镜湖果园，替我采足够的苹果来做些派吗？我还会顺手给你做几个！哦，顺便替我们对迪菲亚致意。', '取回 8 个镜湖苹果，将它们归还给韦斯特布鲁克驻军的德·维里斯中士。', '', '取回 8 个镜湖苹果，将它们归还给韦斯特布鲁克驻军的德·维里斯中士。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17009, 'zhCN', '沉没的宝藏', '这张地图被海草和泥土弄得模糊不清。所幸底部似乎有些潦草的文字，你勉强能辨认。$B$B「真不敢相信我们带着性命逃过了那些可怕的鱼形『东西』，可不知怎的，我们还带着它们的宝藏逃了出来！我在地图上做了标记，免得忘记把赃物藏在了哪里。一路走到这儿，要是最后忘了把箱子扔进了哪艘船，那才叫可惜。我定会把这张地图放在某个安全的地方，窥探的眼睛绝不会想到去翻。」下面似乎还有潦草的字迹，但你辨认不出了。$B$B线索不多，但这张地图所说的宝藏，似乎就藏在某艘沉船之下、海浪深处。', '在西部荒野海岸外找到浸水的箱子。', '', '在西部荒野海岸外找到浸水的箱子。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17011, 'zhCN', '河爪灭族', '该死，$N，看看我的农场！虽说如今也没什么可看的。本就没什么起色，但我有过抱负！现在……现在我一无所有，全怪那些该死的豺狼人！$B$B听我说，$N，我没什么，但请给一个可怜的农夫应得的东西——复仇！我要你出去，杀光你见到的每一只豺狼人。每一只。最后。一只。$B$B等你至少解决了 8 名河爪蛮兵、12 名河爪杂种狗和 10 名河爪草药师，再回到我这里领赏。你应该在西边找到这些豺狼人，北边还有更多，与海岸平行。还有，$N，要是你待会儿数糊涂了，我也不介意，你懂我意思。', '击杀 8 名河爪蛮兵、12 名河爪杂种狗和 10 名河爪草药师。', '', '击杀 8 名河爪蛮兵、12 名河爪杂种狗和 10 名河爪草药师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17012, 'zhCN', '河爪灭族', '你已经帮一个可怜的农夫大忙了，$N，但我的复仇尚未满足。只要还有豺狼人活着、还在呼吸。$B$B我知道东边还有另一处豺狼人营地。我要它们死！至少杀掉 12 名河爪强盗、10 名河爪监工和 8 名河爪秘术师，或许那时我才能终于安宁。至少，在希望与梦想赤裸裸摊在面前时，一个人所能得到的安宁。', '击杀 12 名河爪强盗、10 名河爪监工和 8 名河爪秘术师。', '', '击杀 12 名河爪强盗、10 名河爪监工和 8 名河爪秘术师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17014, 'zhCN', '屠宰场', '$N，见识了你的能耐之后，我想我又有笔买卖要做了。你看，收割看守者并非唯一占据这些昔日肥沃农田的东西。$B$B往东南走，就是如今所谓的枯死田。在那里你会发现收割者。它们和收割看守者一样，只是更凶，但我想这对你不是问题。$B$B等你杀掉 15 台回来找我，我保证不枉你时间。', '农夫萨丁要你击杀 15 台收割者。', '', '返回西部荒野萨丁农场的农夫萨丁。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17838, 'zhCN', '削弱血槌', '英雄，邪恶的血槌食人魔已席卷刀锋山南部！它们残暴的战士和凶猛的恐狼威胁着该地区的稳定。我谦卑地请求你出手，削减它们的数量。向南进发，击杀在这片土地上游荡的血槌蛮兵、苦工、酿酒大师和恐狼。如此便能削弱血槌的掌控，让这片土地对所有人都更安全。', '在刀锋山南部击杀血槌食人魔和狼。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(17926, 'zhCN', '肃清冬灵', '英雄，冬泉谷的安宁正受到威胁！冬灵部族一直在饮用一种神秘的火水，令他们陷入疯狂与好斗。他们的探路者和图腾师在这片雪原上制造混乱，破坏了自然的平衡，威胁着本地区的居民。我们不能任其继续。我呼唤你的力量与勇气，去终结他们鲁莽的行径。削减他们的数量，帮助冬泉谷恢复和平。', '在冬泉谷击败 6 名冬灵探路者和 6 名冬灵图腾师。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18017, 'zhCN', '清理费尔爪', '费伍德森林，这片曾生机勃勃的林地，如今已被恶魔腐蚀污染。枯木部族在这邪恶影响下肆意破坏，加深了森林的腐化。枯木萨满、复仇者，以及他们警惕的巢穴看守，正是这场混乱的推动力。英雄，需要你的利刃与决心来遏止这个黑暗部族的浪潮，将希望带回费伍德。', '在费伍德森林消灭 6 名枯木萨满、6 名枯木复仇者和 4 名枯木巢穴看守。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18018, 'zhCN', '木材与瘟疫', '费伍德森林的林地正受到威胁。铁木践踏者曾是林地的守护者，如今却践踏着它的本质，而剧毒恐惧者则在毒害这片区域的命脉。英雄，大地在呼求援助。挺身而出，对抗这些威胁，帮助恢复费伍德些许的自然之美。', '击杀 6 名铁木践踏者和 6 名剧毒恐惧者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18019, 'zhCN', '驱散恶魔：净化翡翠火', '邪恶的翡翠火萨特，作为被诅咒过往的残余，将他们的背叛与黑暗魔法散布到费伍德各处。地狱召唤者主导黑暗仪式，背叛者播下不和，欺诈者欺骗无辜，他们的统治威胁着将森林推入不可逆的黑暗。英雄，干预的重任落在你肩上。驱逐翡翠火的威胁，给这片被污染的林地带来喘息。', '在费伍德森林灭绝 6 名翡翠火地狱召唤者、6 名翡翠火背叛者和 6 名翡翠火欺诈者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18030, 'zhCN', '瘟疫的掠食害虫', '该地区目睹了本土生物中可怕的变异，将它们变成了昔日自我的怪物版本。狂乱瘟疫猎犬带着无法满足的饥饿游荡大地，腐肉吞噬者翻拣残骸、散布腐朽，天空中因带来空中恐怖的怪物瘟疫蝙蝠而暗淡。这些害虫加剧了现有的瘟疫，构成了迫在眉睫的威胁。英雄，削减这些生物、减轻瘟疫的掌控，重任在你。', '消灭 4 只狂乱瘟疫猎犬、6 只腐肉吞噬者和 6 只怪物瘟疫蝙蝠。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18034, 'zhCN', '血色清剿：魔法与力量', '血色十字军，曾是受人敬仰的圣骑士与牧师，如今迷失了方向，怀揣着威胁他们誓要守护之地的狂热理念。在他们的队伍中，血色看守者、附魔师和牧师掌握着显著的力量与影响，推进着他们狂热的事业。英雄，该由你直面这些关键人物，遏制血色十字军的实力。深入他们的领地，对抗他们的力量与魔法，确保他们威胁下的无辜者安全。', '消灭 6 名血色看守者、6 名血色附魔师和 6 名血色牧师。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18036, 'zhCN', '瓦解血色精英', '血色十字军的力量不仅在于数量，更在于其精英的能力。血色禁卫，他们事业令人生畏的守护者；血色教士，沉浸于狂热的属灵指引者；血色大法师，对奥术怀着狂热奉献的大师。这些人物代表着他们秩序的中坚。英雄，要让和平在这些动荡之地有一线机会，就必须直面这些精英，消除他们的威胁。深入他们领域的核心，打破他们统治的枷锁。', '击败 6 名血色禁卫、6 名血色教士和 6 名血色大法师。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18044, 'zhCN', '奎尔利西恩动乱', '奎尔利西恩旅店坐落在东瘟疫之地的北境，曾是精灵文明的灯塔。其主要居民樵夫、游侠和踏路者曾和谐共处，守护着精灵领地的边界。然而近来，一种奇异的敌意在他们心中生根。他们对外的敌意威胁着我们好不容易在瘟疫之地建立的脆弱和平。英雄，前往奎尔利西恩旅店，平息这些精灵的敌意，好让我们能查明他们骤然改变的根源。', '前往奎尔利西恩旅店，击杀 8 名樵夫、8 名游侠和 4 名踏路者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18045, 'zhCN', '地穴爬行者的末日', '东瘟疫之地遍布无数威胁，其中尤以从散布各地的墓穴与陵墓中涌出的邪恶生物为甚。地穴恶魔、行者和恐惧者是被视为冒险者与村民残骸的憎恶之物——那些不幸沦为天灾邪恶影响之受害者的可怜人。这些生物如今游荡大地，散布恐惧与黑暗。英雄，是时候直面这些亡灵威胁，终结他们的恐怖了。', '穿越东瘟疫之地，击杀 6 只地穴恶魔、6 只地穴行者和 4 只地穴恐惧者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18046, 'zhCN', '被诅咒者的饥饿', '瘟疫之地，曾是葱郁之地，如今却是噩梦与悲恸之土。在游荡这被诅咒之地的无数憎恶之中，有缝合恐惧者——黑暗死灵法术的造物，贪婪的食尸鬼，以及诅咒法师——挥舞着扭曲魔法的被诅咒之魂。他们对生者无尽的饥饿威胁着我们好不容易建立的少数避难所。英雄，我们必须确保这些庇护所的安全。深入瘟疫之地核心，平息这些被诅咒生物的饥饿。', '在东瘟疫之地寻出并击杀 6 只缝合恐惧者、6 只食尸鬼和 4 名诅咒法师。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18054, 'zhCN', '绝望的回响', '西瘟疫之地已成为那些在大战中丧生者不安灵魂的滋生地。萦绕幻象、哀嚎死亡者和饥饿幽魂游荡此地，他们哀伤的哭号，正是生前所受苦痛与死后所承折磨的明证。英雄，这些灵魂理应得到安息，但只要他们被瘟疫之地的黑暗魔法所束缚，就会继续播撒苦痛与绝望。挺身而出，终结这些饱受折磨的魂魄，给予他们长久以来被剥夺的释放。', '在西瘟疫之地击杀 6 名哀嚎死亡者、6 名饥饿幽魂和 6 名萦绕幻象。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18055, 'zhCN', '不死的威胁', '西瘟疫之地的土地，被巫妖王的恶意污染，已成为梦魇般亡灵的家园，它们继续在每一处角落游荡。腐烂尸体、瘟疫僵尸和骷髅恐怖者，曾生活于此的士兵与市民的亡灵残骸。这些可怜的灵魂，如今化为憎恶之物，在恒久的折磨中徘徊，对任何路过此地的生者都构成迫在眉睫的威胁。英雄，你的职责明确。深入这片被诅咒之地的核心，消灭这些生物。这是恢复些许和平、确保敢于踏足者安全的唯一途径。', '在西瘟疫之地击杀 6 具腐烂尸体、6 名瘟疫僵尸和 6 具骷髅恐怖者。\\n\\n', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18056, 'zhCN', '涂满黏液，备战', '哭泣洞穴，曾是静思与自然之美所在，如今却散发出绝望与腐朽的气息。这一转变，是占领它的软泥与黏液生物所为——它们是仍游荡于西瘟疫之地的瘟疫产物。其中，吞噬淤泥怪、腐烂的巨兽和可憎的软泥怪最为强大，所过之处留下腐蚀的痕迹，危及我们力图恢复脆弱的平衡。英雄，你的任务就是进入洞穴，清除这些可憎的存在。净化洞穴，让大自然的疗愈之触得以重新开始。', '在西部瘟疫之地的哭泣洞穴击杀 6 只吞噬淤泥怪、6 只腐烂的巨兽和 6 只可憎的软泥怪。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18065, 'zhCN', '大猩猩战', '菌岩的大猩猩愈发好斗，对试图理解安戈洛环形山奥秘的探索者与研究者构成威胁。它们突如其来的敌意不仅危及我们的行动，也扰乱了这片史前之地的微妙平衡。英雄，前往菌岩，削减它们的数量。我们必须确保进入环形山者的安全，恢复这神圣之地的均衡。', '在菌岩击杀安戈洛雷霆者、安戈洛大猩猩和安戈洛践踏者，削减大猩猩的数量。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18089, 'zhCN', '阿科罗克的信徒', '英雄，在艾萨拉湛蓝的水域深处，强大阿科罗克的追随者已开始聚集。这些被称为阿科兰的信徒曾一度沉睡，但近来奥术灵脉的扰动重新唤醒了他们对古老海巨人的忠诚。他们日益增长的存在与效忠，对艾萨拉的力量平衡构成重大威胁。需要你的力量与专长，在这些虔诚信徒完全贯彻其主人意志之前，直面并平息他们。', '在艾萨拉的水下区域击杀 6 名阿科兰咯咯者、6 名阿科兰泥居者和 6 名阿科兰预言者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18090, 'zhCN', '雷加什的暗影', '', '在艾萨拉的林区击杀 6 名雷加什萨特、6 名雷加什地狱召唤者和 6 名雷加什盗贼。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18091, 'zhCN', '精灵的入侵', '英雄，艾萨拉出现了新的威胁。血精灵勘测者与收复者被发现有意在抽取这片土地的奥术能量与古老遗物。他们对艾萨拉宝藏的干涉不仅破坏了平衡，更有可能唤醒沉睡的危险。我们不能袖手旁观，任由他们掠夺、榨干此地的魔法精华。挺身而出，阻止他们的推进，确保艾萨拉的奥术圣洁完好无缺。', '在艾萨拉击杀 6 名血精灵勘测者和 6 名血精灵收复者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18104, 'zhCN', '瓦解虫巢', '英雄，希利苏斯不断移动的沙丘之下，隐藏着佐拉虫巢虫族庞大的网络。来自巢穴的掠夺者、黄蜂和姐妹已开始大量涌出，它们咄咄逼人的扩张威胁着该地区。它们虫群意识意图的暗流仍不清晰，但可以确定的是它们构成的危险。深入它们的领地，直面这些虫族，阻止它们横穿沙漠的步伐。', '在希利苏斯虫族出没的区域击杀 4 名佐拉虫巢掠夺者、8 只佐拉虫巢黄蜂和 6 名佐拉虫巢姐妹。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18105, 'zhCN', '锤影', '英雄，暮光之锤邪教继续在希利苏斯进行其黑暗图谋，利用沙漠的潜在力量以实现其灾难性的幻象。他们队伍中的地质领主、复仇者和唤石者，在这些仪式中举足轻重，引出的能量足以毁灭世界本身。你必须介入，刺穿暮光营地的帷幕，在他们的可怕计划得逞之前终结其野心。', '在散布于希利苏斯各处的暮光营地击杀 6 名暮光地质领主、6 名暮光复仇者和 4 名暮光唤石者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18106, 'zhCN', '沙漠掠食者', '英雄，希利苏斯对许多人而言是贫瘠荒原，却充满了适应严酷环境的生命。但其中一些居民，如岩石潜行者、疏浚粉碎者和石鞭钳者，越发充满敌意，破坏了自然平衡，捕食较弱的生物。这绝不能任其发展。深入这片被烈日炙烤的旷野，遏制这些沙漠掠食者的威胁。', '在希利苏斯干旱的平原击杀 5 只岩石潜行者、5 只疏浚粉碎者和 5 只石鞭钳者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18109, 'zhCN', '让雷加尔虫巢噤声', '英雄，雷加尔虫巢虫族愈发好斗，它们的扩张威胁着希利苏斯的平衡。其中，喷火者、虫巢领主和奴隶制造者尤为棘手，它们领导并协调着族群的活动。我们必须打击这些关键目标，阻止虫族的推进，维护沙漠脆弱的均衡。', '击杀 6 只雷加尔虫巢喷火者、6 名雷加尔虫巢领主和 4 名雷加尔虫巢奴隶制造者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18110, 'zhCN', '希利苏斯的黄昏降临', '英雄，暮光之锤邪教继续在希利苏斯进行其黑暗图谋，利用沙漠的潜在力量以实现其灾难性的幻象。他们队伍中的地质领主、复仇者和唤石者，在这些仪式中举足轻重，引出的能量足以毁灭世界本身。你必须介入，刺穿暮光营地的帷幕，在他们的可怕计划得逞之前终结其野心。', '击杀 6 名暮光地质领主、6 名暮光复仇者和 4 名暮光唤石者。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(18111, 'zhCN', '从痛苦中解脱', '在希利苏斯的深处，一股难以言说的邪恶已控制了这片土地守护者的身心。哨兵与德鲁伊，曾是自然的守护者，如今在折磨中游荡。英雄，这是一项令人心碎的任务，但必须让他们从这扭曲的生存中解脱。让他们安息，或许这片土地能找到些许安宁。', '击杀 6 名受折磨的哨兵和 6 名受折磨的德鲁伊。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(26035, 'zhCN', '战地医护：灵纹布绷带', '英雄，我们需要你的帮助！\\n\\n我们的士兵在与军团的战斗中不断倒下，而我们的绷带补给正在告罄！\\n\\n收集 16 卷灵纹布绷带。自然，你会因你的协助而获得丰厚报酬，英雄。', '收集 16 卷灵纹布绷带', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(26053, 'zhCN', '加把火：魔铁锭', '英雄，我们需要你的帮助！$b$b我们的熔炉难以跟上刚接下的大订单！$b$b收集 15 块魔铁锭。自然，你会因你的协助而获得丰厚报酬，英雄。', '收集 15 块魔铁锭', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(26993, 'zhCN', '屠宰场', '看看这片土地成了什么样子！诅咒迪菲亚兄弟会，他们让地精造出机械恐怖，派到这些田里来！我们农夫可没想要这些。如果这些傀儡在这儿，我怎么养活我的家和可怜的老马布兰契？$B$B你能帮忙除掉附近的傀儡吗？你能在这一带找到它们，往西边、我的南瓜农场那边也有。请帮帮我们！暴风城已经放弃我们了。', '击杀 10 台锈蚀的收割傀儡，返回詹森农场的农夫法布隆。', '', '返回西部荒野的农夫法布隆。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(26994, 'zhCN', '屠宰场', '你把这附近的傀儡清理得不错，但我不是唯一一个面临这事的人。我的好朋友萨丁也告诉我，傀儡正在毁他的农场。你能帮他一把吗？他的农场就在南边不远。', '与萨丁农场的农夫萨丁交谈。', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(26995, 'zhCN', '屠宰场', '很高兴看到有人在这儿帮忙。这些傀儡把我们的人吓跑了，如果我们不尽快解决，我怕西部荒野会被迪菲亚兄弟会占领、被接管。总之，出去杀几台傀儡！你能在农场这儿找到一些，或往西的莫尔森农场也有。', '击杀 10 台收割傀儡，返回萨丁农场的农夫萨丁。', '', '返回西部荒野的农夫萨丁。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(26996, 'zhCN', '屠宰场', '你之前杀的那些傀儡并非唯一破坏我们土地的东西！我有个农夫说他看见更多在亚历克斯顿农场、金海岸采石场附近。如果你不介意再杀些傀儡，我们将万分感激你的协助。', '击杀 10 台收割看守者，返回萨丁农场的农夫萨丁。', '', '返回西部荒野的农夫萨丁。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(26997, 'zhCN', '屠宰场', '我们大多农场已经收复，但还有一座农场要争取。往南很远、越过哨兵岭，你会找到枯死田，那里游荡着最强大的傀儡，灼烧着土地。我试着带几个工人过去，但傀儡把我们赶了回来！希望你能胜任这任务$n，这些傀儡可不是闹着玩的！', '击杀 10 台收割者，返回萨丁农场的农夫萨丁。', '', '返回西部荒野的农夫萨丁。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49976, 'zhCN', '风暴秘典', '圣光在上！这卷书我捡起来的时候差点电着我，$N。它周围的空气噼啪作响着电能，我发誓能听到书页里传来远处的雷鸣。只有具备引导风暴原始力量之坚韧者，才该考虑翻开它。你准备好迎接这样的元素之怒了吗？', '阅读风暴秘典，前往北郡山谷寻找妮琪·特斯拉。', '', '前往北郡山谷寻找妮琪·特斯拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49977, 'zhCN', '守护者的誓言', '一项高尚的召唤在等着你，$N。这誓言铭刻在我所见过最精良的钢上，几乎散发着荣誉与职责之光。文字述说着守护、牺牲，以及在绝境中屹立不摇。很少有人有颗心能担起这样的重负。你拥有这样的勇气吗？', '阅读守护者的誓言，前往北郡山谷寻找古斯。', '', '前往北郡山谷寻找古斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49978, 'zhCN', '圣殿骑士的誓约', '圣光本身似乎已祝福了这份文件，$N。当我握住它，我感到一股暖意流入胸膛，神圣使命之感充盈我心。这誓约要求对圣光旨意绝对奉献，以及在黑暗面前毫不动摇的信仰。如此奉献绝非轻率给予。', '阅读圣殿骑士的誓约，前往北郡山谷寻找威廉修士。', '', '前往北郡山谷寻找威廉修士。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49979, 'zhCN', '鲜血魔典', '我得承认，这本魔典让我深感不安，$N。那皮制封面似乎是……嗯，我宁可不去猜测。它像心跳般有节奏地脉动，我发誓书页染成了深红。其中的魔法涉及生命之力本身——一种既可怕又诱人的力量。务必极其谨慎地对待它。', '阅读鲜血魔典，前往北郡山谷寻找沉默者惠丝普。', '', '前往北郡山谷寻找沉默者惠丝普。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49980, 'zhCN', '游侠的指南', '真奇怪的东西，$N。这本指南还粘着些森林碎屑——松针、苔藓，甚至一小截树枝。我刚翻开，就听到仿佛鸟鸣与树叶沙沙的声音。它述说着追踪、荒野求生，以及与自然本身合一。野性透过这些书页向你呼唤。', '阅读游侠的指南，前往北郡山谷寻找月溪镇欧文。', '', '前往北郡山谷寻找月溪镇欧文。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49981, 'zhCN', '时光手稿', '太奇特了，$N。我发誓这手稿片刻前还不在，可它现在就在这儿。文字在我眼前微微闪烁、游移，仿佛同时存在于多个瞬间。这样的时光魔法超出我的理解，但或许你有心智去领悟它的奥秘。', '阅读时光手稿，前往北郡山谷寻找索莉多米。', '', '前往北郡山谷寻找索莉多米。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49982, 'zhCN', '死灵日志', '我跟你说实话，$N——这本日志让我发冷。字面上的冷。每当我靠近它，温度就会下降，还一直听到我听不清的细微低语。那封面似乎是用……骨头做的。这里面装着大多数人视为禁忌的死亡魔法知识。你确定要走上这样一条黑暗之路吗？', '阅读死灵日志，前往北郡山谷寻找无赖哈尔伯特。', '', '前往北郡山谷寻找无赖哈尔伯特。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49983, 'zhCN', '烈焰秘典', '小心点，$N！这秘典烫得几乎拿不住。火焰在它表面舞动却不烧焦书页，周围的空气因热度而闪烁。我几乎能感受到其中蕴含的火焰魔法，乞求被释放。只有对毁灭满怀热情者，才该考虑这样的力量。', '阅读烈焰秘典，前往寒脊山谷寻找火焰领主科比。', '', '前往北郡山谷寻找焚化者科比。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49984, 'zhCN', '禁忌论著', '欢迎回来，$N！在你走之前，有个卫兵把它送来了，吩咐我交给你。我自己还没机会偷看。以一切神圣之名……我几乎无法直接正视这东西。那些符号仿佛在扭动、游移，我一直听到……低语。说着我听不懂、却令我充满恐惧的话语。如此疯狂的东西，只可能出自疯子帕塔尔，而只有真正疯了……或真正勇敢的人……才敢研究它。去拜访疯子帕塔尔，他会有更多答案。', '阅读禁忌论著，前往寒脊山谷寻找疯子帕塔尔。', '', '前往寒脊山谷寻找疯子帕塔尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49985, 'zhCN', '工程学手册', '妙极了！这本手册里满是前所未见的蓝图与示意图，$N。小齿轮、弹簧和发条装置仿佛从书页中洒出，我能听到看不见的机械传来轻微的滴答声。这里魔法与工程学的结合真是了不起。创新正等待着足够聪明去理解它的人。', '阅读工程学手册，前往寒脊山谷寻找诺曼·戈德夏尔。', '', '前往寒脊山谷寻找诺曼·戈德夏尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49986, 'zhCN', '太阳经文', '多美的景象，$N。这份经文散发着黎明暖光，读它让我充满希望与焕然一新的活力。那金色文字述说着借由太阳能量的治愈，以及引渡太阳赋予生命之力。如此耀眼的魔法只给世界带来祝福与新生。', '阅读太阳经文，前往寒脊山谷寻找随军牧师妮索妮。', '', '前往寒脊山谷寻找随军牧师妮索妮。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49987, 'zhCN', '死亡手册', '这本手册让我寒战至骨，$N。字面上的。它周围空气变冷，我能闻到葬礼准备特有的气味。其中的知识关乎死亡本身——并非邪恶，而是一种需被引导与疏导的自然之力。只有理解生与死平衡者，才该研习此等技艺。', '阅读死亡手册，前往寒脊山谷寻找清除者特罗斯。', '', '前往寒脊山谷寻找清除者特罗斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49988, 'zhCN', '符文铭文', '古老的力量流经这块石板，$N。刻于其表面的符文散发着内在之光，我能感到每个符号中都承载着数个世纪的重量。这是我们种族所知最古老的魔法形式——将力量束缚于永恒形态的艺术。当世界尚年轻时，这知识便已古老。', '阅读符文铭文，前往寒脊山谷寻找万达·贝蕾辛。', '', '前往寒脊山谷寻找万达·贝蕾辛。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49990, 'zhCN', '上古石板', '你击败那些狗头人一回来，我就被嘱托把这事告知你，$N。它似乎是一块上古石板，刻着野蛮人战士粗陋的标记。石头本身散发着原始之怒，我能感到追随这条道路者体内奔流的野性力量。在修道院处理其他事务之前，我劝你不妨先读读它。', '前往北郡山谷寻找掠夺者阿曼达。', '', '前往北郡山谷寻找掠夺者阿曼达。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49991, 'zhCN', '部族卷轴', '你击败那些狗头人一回来，我就被嘱托把这事告知你，$N。它似乎是一卷部族卷轴，标记着巫医的神秘符号。奇异的药草缀于其边，我几乎能听到古老魂灵的低声咒语。借由暗影与光明治愈的技艺，不可等闲视之。在修道院处理其他事务之前，我劝你不妨先读读它。', '前往北郡修道院寻找耶拉医生。', '', '前往北郡修道院寻找耶拉医生。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(49992, 'zhCN', '神圣信函', '你击败那些狗头人一回来，我就被嘱托把这事告知你，$N。它似乎是一封神圣信函，印着猎巫人的银色封印。羊皮纸本身似乎在排斥黑暗，受那些毕生献身于此世驱邪者所祝福。如此正义的怒火需要恰当的指引。在修道院处理其他事务之前，我劝你不妨先读读它。', '前往北郡修道院寻找埃林·提亚斯。', '', '前往北郡修道院寻找埃林·提亚斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51000, 'zhCN', '风暴秘典', '这卷书周围的山间空气噼啪作响着能量，$N。即便对付完那些难缠的狼，我也能感到其中蕴含的电力。山中风暴凶猛而无情——或许你有坚韧之心去掌握它们的狂怒？', '寻找风暴秘典，前往寒脊山谷寻找风暴嗝艾伦德。', '', '前往铁炉峰寻找风暴嗝艾伦德。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51001, 'zhCN', '守护者的誓言', '这誓言如山石之力般回响，$N。你面对那些狼时展现了勇气——如今文字述说着如峰峦般屹立不摇，面对任何风暴都不可动摇。你可有坚韧之心成为不可撼动的守护者？', '寻找守护者的誓言，前往寒脊山谷寻找锤子卡松。', '', '前往铁炉峰寻找锤子卡松。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51002, 'zhCN', '圣殿骑士的誓约', '以我的胡须起誓！圣光从此文件如锻炉之火般明亮，$N。你以荣誉应对那些狼——山地矮人向来知道，真正的信仰如同我们锻炉中不灭的永恒之火——稳定、强大、不可熄灭。', '寻找圣殿骑士的誓约，前往寒脊山谷寻找提杜伊斯·狮心。', '', '前往铁炉峰寻找提杜伊斯·狮心。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51003, 'zhCN', '游侠的指南', '妙极了！这本指南仍带着高海拔山间的气息，$N。你追踪那些狼时展现了技巧——我几乎能听到鹰的啼鸣，感到风穿过石隘的刺骨。山间荒野向足够勇敢回应者呼唤。', '寻找游侠的指南，前往寒脊山谷寻找巨鬃巴胡尔。', '', '前往铁炉峰寻找巨鬃巴胡尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51004, 'zhCN', '时光手稿', '奇怪……这手稿似乎同时存在于多个海拔，$N。看着你对付那些狼之后，我发现稀薄的山间空气必使时光魔法更加明显。只有心智最清明者，才该尝试此类研习。', '寻找时光手稿，前往寒脊山谷寻找比埃科。', '', '前往铁炉峰寻找比埃科。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51005, 'zhCN', '死灵日志', '这日志周围的石头都变冷了，$N。这些山脉藏着许多古老秘密，在目睹你如何对付那些狼之后，其中一些涉及不安的亡者。如此危险的知识，务必小心行事。', '寻找死灵日志，前往寒脊山谷寻找幽暗萨薇娜。', '', '前往铁炉峰寻找奥法娜·幽暗。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51006, 'zhCN', '烈焰秘典', '跟锻炉之火一样烫，这本！这秘典散发的热力足以温暖这些寒冷的山间厅堂，$N。你对抗那些狼时展现了精神之火——火焰魔法在此备受敬重。我们矮人懂得永不熄灭之焰的价值。', '寻找烈焰秘典，前往寒脊山谷寻找黛比·旋焰。', '', '前往铁炉峰寻找黛比·旋焰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51007, 'zhCN', '禁忌论著', '问候你，$N。克利普·厄鸣前不久过来，嘱我把这交给你。以山之诸王之名……这论著上的符号，当我没直视它们时似乎在游移、扭动，$N。看着你面对那些狼之后，当这东西靠近时，山间回响传来奇异的低语。务必极度谨慎地对待它。', '寻找禁忌论著，前往寒脊山谷寻找克利普·厄鸣。', '', '前往铁炉峰寻找克利普·厄鸣。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51008, 'zhCN', '太阳经文', '蒙福的圣光！这份经文如新雪映日般闪耀，$N。你对抗那些狼时展现了正义之勇——山峰更近天堂，或许正因如此，此海拔下圣光的祝福之感如此强烈。', '寻找太阳经文，前往寒脊山谷寻找牧师石光。', '', '前往铁炉峰寻找牧师石光。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51009, 'zhCN', '工程学手册', '这才像真正的矮人手艺！光是拿着这本手册，我就能听到齿轮咔嗒、蒸汽嘶嘶，$N。在看到你对付那些狼的务实做派后，看来冷栓宾克尔认为你有希望能向最优秀的他学艺。毕竟，我们的山地工程是全境最精湛的——只要你够聪明，能学着不把自己炸飞！', '寻找工程学手册，前往寒脊山谷寻找冷栓宾克尔。', '', '前往铁炉峰寻找冷栓宾克尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51010, 'zhCN', '符文铭文', '古老的力量流经这块石版，$N。此处所刻符文比我们最古老的厅堂更悠久，由塑造群山本身的双手刻成。在看着你直面那些狼之后，如此知识伴随着重大责任。', '寻找符文铭文，前往寒脊山谷寻找默蒙·铸引。', '', '前往铁炉峰寻找默蒙·铸引。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51011, 'zhCN', '上古石板', '这块石板脉动着重原始能量，$N。你像真正的战士般与那些狼战斗——蛮人的道路严苛却诚实。没有花哨技巧，只有纯粹的力量与决心。群山孕育战士，而非舞者。', '寻找上古石板，前往寒脊山谷寻找格雷林·铁须。', '', '前往铁炉峰寻找格雷林·铁须。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51012, 'zhCN', '猎人的指令', '这指令印着征服者的封印，$N。群山隐藏着许多必须连根拔起的邪恶，伊罗呼唤那些有勇气在这些冰封峰峦中狩猎黑暗者。你可具备成为邪恶狩猎者所需？', '前往寒脊山谷寻找征服者伊罗。', '', '前往铁炉峰寻找征服者伊罗。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51013, 'zhCN', '原始秘典', '原始的元素之力环绕这秘典涌动，$N！在看到你如何对付那些狼之后，其中蕴含的魔法如同山间风暴般狂野，且危险加倍。只有拥有拥抱混乱之力者，才敢研习如此原始的力量。', '寻找原始秘典，前往寒脊山谷寻找卡索·锤拳。', '', '前往铁炉峰寻找卡索·锤拳。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(51014, 'zhCN', '死亡手册', '$N，当这本手册靠近时，连空气都变得更冷了。在这严酷的群山之中，死亡是不离不弃的旅伴；在你了结那些野狼的痛苦之后，或许正因如此，有些人学会了引导死亡，而非畏惧它。请怀着应有的敬意对待这等知识。', '找到死亡手册，并在寒脊山谷寻找齐帕克·齿重。', '', '在铁炉峰寻找齐帕克·齿重。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52000, 'zhCN', '战士之怒', '有人托我把这个交给你，年轻的蛮兵。这似乎是一块刻着兽人战争符文的原石石板，符文中涌动着难以遏制的狂怒。石头散发着野性的力量，似乎出自穆''卡卡之手——他在试炼谷传授蛮兵之道。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找穆''卡卡。', '', '在试炼谷寻找穆''卡卡。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52001, 'zhCN', '深红之术', '有人托我把这个交给你，年轻的血法师。这似乎是一卷染血的卷轴，涌动着黑暗魔法，散发着铁锈与禁忌力量的气息。它似乎出自织肉者凯拉之手——她在试炼谷修习这些深红之术。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找织肉者凯拉。', '', '在试炼谷寻找织肉者凯拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52002, 'zhCN', '虚空低语', '有人托我把这个交给你，年轻的邪教徒。这似乎是一卷扭动的卷轴，上面覆满符号，无人直视时便自行变换游移。奇异的低语自其中回荡，似乎出自鲁格拉·萎手之手——他在试炼谷与禁忌力量沟通。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找鲁格拉·萎手。', '', '在试炼谷寻找鲁格拉·萎手。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52003, 'zhCN', '邪能束缚', '有人托我把这个交给你，年轻的邪誓者。这似乎是一份被绿色火焰环绕的恶魔契约，其地狱文字灼烧着读者的双眼。它似乎出自暴君格罗斯之手——他在试炼谷教导他人束缚恶魔之力。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找暴君格罗斯。', '', '在试炼谷寻找格里洛克·莫尔佐格。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52004, 'zhCN', '荣誉之盾', '有人托我把这个交给你，年轻的守护者。这似乎是一块磨亮的钢制石板，刻着守护誓约，散发着牢不可破的防御光环。它似乎出自兽穴军士戈尔穆克之手——她在试炼谷投身于守护他人。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找兽穴军士戈尔穆克。', '', '在试炼谷寻找兽穴军士戈尔穆克。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52005, 'zhCN', '黑暗誓言', '有人托我把这个交给你，年轻的索罗斯骑士。这似乎是一份环绕暗影、盖有索罗斯之印的文书，散发着冰冷的黑暗。它似乎出自扎戈克之手——他在试炼谷行走于暗影与荣誉之间的危险道路。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找斯派''罗。', '', '在试炼谷寻找斯派''罗。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52006, 'zhCN', '灵魂共契', '有人托我把这个交给你，年轻的死灵法师。这似乎是一块由巨兽骸骨雕成的古老石板，刻着低语着不死之语的死灵符号。它似乎出自复苏者卡格拉之手——他在试炼谷修习这些技艺。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找复苏者卡格拉。', '', '在试炼谷寻找复苏者卡格拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52007, 'zhCN', '元素之怒', '有人托我把这个交给你，年轻的元素使。这似乎是一卷噼啪作响、充满原始元素能量的卷轴，迷你风暴与火焰在其中盘旋。它似乎出自克鲁尔·碎岩之手——他在试炼谷与元素之灵沟通。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找克鲁尔·碎岩。', '', '在试炼谷寻找克鲁尔·碎岩。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52008, 'zhCN', '烈焰之路', '有人托我把这个交给你，年轻的控火师。这似乎是一份闷燃的手稿，散发着炽热，火焰在其焦黑的表面上舞动。它似乎出自格里什纳赫·灼疤之手——他在试炼谷精通火焰之术。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找格里什纳赫·灼疤。', '', '在试炼谷寻找格里什纳赫·灼疤。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52009, 'zhCN', '野性呼唤', '有人托我把这个交给你，年轻的游侠。这似乎是一本皮革装订的指南，带着荒野的气息，沾满泥污并印有野兽的足印。它似乎出自狼骑雅拉之手——那位在试炼谷守护荒野的游侠。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找狼骑雅拉。', '', '在试炼谷寻找狼骑雅拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52010, 'zhCN', '上古符文', '有人托我把这个交给你，年轻的符文大师。这似乎是一块厚重的石板，蚀刻着发光、涌动古老魔力的符文。它似乎出自齐娜·符读者之手——那位居于试炼谷的符文大师。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找齐娜·符读者。', '', '在试炼谷寻找莫格''尔符读者。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52011, 'zhCN', '雷霆之声', '有人托我把这个交给你，年轻的唤雷者。这似乎是一份噼啪作响、充满电能的手稿，雷声自书页中低沉轰鸣。它似乎出自齐姆''钦之手——那位在试炼谷统御风暴的唤雷者。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找齐姆''钦。', '', '在试炼谷寻找齐姆''钦。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52012, 'zhCN', '太阳祝福', '有人托我把这个交给你，年轻的太阳牧师。这似乎是一卷金色的经文，散发着温暖的阳光，涌动神圣的治愈能量。它似乎出自潘加乔·阳视之手——那位为试炼谷带来光明的太阳牧师。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找潘加乔·阳视。', '', '在试炼谷寻找潘加乔·阳视。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52013, 'zhCN', '神圣誓言', '有人托我把这个交给你，年轻的圣殿骑士。这似乎是一份受祝福的文书，散发圣光，刻着奉献神明的誓约。它似乎出自真理承载者奥莫古尔格之手——他在试炼谷担任圣殿骑士。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找真理承载者奥莫古尔格。', '', '在试炼谷寻找真理承载者奥莫古尔格。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52014, 'zhCN', '机械创新', '有人托我把这个交给你，年轻的修补匠。这似乎充满机械设计的技术蓝图，伴随着齿轮滴答作响的声音。它似乎出自机械小子帕罗德之手——那位在试炼谷工作的修补匠。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找机械小子帕罗德。', '', '在试炼谷寻找机械小子帕罗德。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52015, 'zhCN', '剧毒之术', '有人托我把这个交给你，年轻的毒药师。这似乎是一本危险的书卷，散发着奇异毒素的恶臭，绿色毒雾自书页间渗出。它似乎出自智者奎''斯佩之手——他在试炼谷研习毒药与解药。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找智者奎''斯佩。', '', '在试炼谷寻找智者奎''斯佩。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(52016, 'zhCN', '祖先智慧', '有人托我把这个交给你，年轻的巫医。这似乎是一卷古老的卷轴，装饰着部族的神物，低鸣着祖先之力与洛阿魔法。它似乎出自罗尔''乔库之手——他在试炼谷修习这些古老技艺。在你继续此地的职责之前，我建议你不妨先读读它。', '在试炼谷寻找罗尔''乔库。', '', '在试炼谷寻找罗尔''乔库。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53000, 'zhCN', '狂怒石板', '有人托我把这个交给你，年轻人。这似乎是一块刻着符文的骨制石板，涌动着原始的狂怒。古老的符号述说着超越死亡本身的无穷暴怒，它似乎出自殡葬师奇特之手——他在死亡之痕传授收割者之道。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找殡葬师奇特。', '', '在死亡之痕寻找殡葬师奇特。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53001, 'zhCN', '深红卷轴', '有人托我把这个交给你，年轻人。这似乎是一卷染有古老鲜血的黑暗卷轴，散发着恶毒的力量。深红之术向那些明白死亡与不死不过工具的人发出呼唤，它似乎出自伊琳娜·瓦尔里德之手——她在死亡之痕修习这些禁忌技艺。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找伊琳娜·瓦尔里德。', '', '在死亡之痕寻找伊琳娜·瓦尔里德。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53002, 'zhCN', '虚空手稿', '有人托我把这个交给你，年轻人。这似乎是一份破旧的手稿，覆满符号，被注视时仿佛扭动游移。古老存在的低语自其中回荡，它似乎出自撒迪厄斯·寻虚之手——他在死亡之痕与超越死亡的力量沟通。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找撒迪厄斯·寻虚。', '', '在死亡之痕寻找撒迪厄斯·寻虚。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53003, 'zhCN', '邪能契约', '有人托我把这个交给你，年轻人。这似乎是一份被绿色火焰环绕的恶魔契约，其地狱文字燃烧着邪恶的意图。邪能能量与那些已经尝过死亡滋味的人产生共鸣，它似乎出自达尔达尼斯之手——他在死亡之痕统御这些黑暗力量。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找达尔达尼斯。', '', '在死亡之痕寻找达尔达尼斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53004, 'zhCN', '守护者誓言', '有人托我把这个交给你，年轻人。这似乎是一块刻着守护符文的钢制石板，散发着延续至死亡之外的防御魔法。守护者誓言甚至约束着不死者去保护他人，它似乎出自死亡卫士布拉德福斯之手——他在死亡之痕坚守这份神圣职责。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找死亡卫士布拉德福斯。', '', '在死亡之痕寻找死亡卫士布拉德福斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53005, 'zhCN', '暗影敕令', '有人托我把这个交给你，年轻人。这似乎是一份环绕暗影、盖有索罗斯之印的宣告，散发着被高贵意志调和的冰冷黑暗。索罗斯骑士明白荣誉超越生死，它似乎出自布拉尔穆拉尔之手——他在死亡之痕恪守这些黑暗誓言。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找布拉尔穆拉尔。', '', '在死亡之痕寻找布拉尔穆拉尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53006, 'zhCN', '死亡秘典', '有人托我把这个交给你，年轻人。这似乎是一块刻着死灵符号、涌动死亡之力的古老骨制石板。统御亡者的技艺对那些亲身经历过死亡的人而言来得自然，它似乎出自多纳尔·织瘟之手——他在死亡之痕精通这些技艺。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找多纳尔·织瘟。', '', '在死亡之痕寻找多纳尔·织瘟。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53007, 'zhCN', '时光卷轴', '有人托我把这个交给你，年轻人。这似乎是一卷噼啪作响、充满原始元素狂怒的卷轴，自然之力被不灭的意志所束缚。$n，这份卷轴令我恐惧，它并不向我发出呼唤。然而，你的召唤似乎来自夸多尔米——他在死亡之痕扭曲时间与空间。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找夸多尔米。', '', '在死亡之痕寻找夸多尔米。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53008, 'zhCN', '灼痕宝典', '有人托我把这个交给你，年轻人。这似乎是一份闷燃的手稿，燃烧着冰冷的火焰，那是无温的吞噬之火。死亡无法熄灭控火师的火焰——它只会将其转化为更可怕的存在，它似乎出自卡德莫斯·烬焰之手——他在死亡之痕统御这些死亡之火。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找卡德莫斯·烬焰。', '', '在死亡之痕寻找卡德莫斯·烬焰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53009, 'zhCN', '猎人的指南', '有人托我把这个交给你，年轻人。这似乎是一本皮革装订的书卷，印有早已死去的野兽足印，散发着腐朽与古老荒野的气息。死亡并未终结游侠与荒野的联系——它使之加深为更黑暗的存在，它似乎出自古斯塔夫·疫翅之手——他在死亡之痕潜行于阴影之中。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找古斯塔夫·疫翅。', '', '在死亡之痕寻找古斯塔夫·疫翅。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53010, 'zhCN', '符文石板', '有人托我把这个交给你，年轻人。这似乎是一块蚀刻着发光符文的石板，涌动着不死的伟力。符文大师的技艺超越凡人之躯——其铭文在血肉腐朽后依然长存，它似乎出自威廉·巴尔蒂耶之手——他在死亡之痕镌刻这些永恒符号。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找威廉·巴尔蒂耶。', '', '在死亡之痕寻找威廉·巴尔蒂耶。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53011, 'zhCN', '风暴手稿', '有人托我把这个交给你，年轻人。这似乎是一份噼啪作响、闪动着幽灵闪电的手稿，雷声自彼岸之境回荡。唤雷者的风暴承载着亡者的声音，那是伴随着迷失灵魂之怒嚎啸的狂风，它似乎出自达伯特·斯塔泽之手——他在死亡之痕统御这些幽灵风暴。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找达伯特·斯塔泽。', '', '在死亡之痕寻找达伯特·斯塔泽。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53012, 'zhCN', '太阳经文', '有人托我把这个交给你，年轻人。这似乎是一卷金色的经文，散发着苍白的光辉，那是透过死亡之幕过滤出的神圣能量。即便是不死者也能够导引太阳之力，将圣光转化为既美丽又可怕的存在，它似乎出自阳语者塔蕾西娅之手——她在死亡之痕坚守这矛盾的信仰。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找阳语者塔蕾西娅。', '', '在死亡之痕寻找阳语者塔蕾西娅。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53013, 'zhCN', '神圣誓约', '有人托我把这个交给你，年轻人。这似乎是一份散发冷光的受祝福文书，是即便跨越坟墓依然束缚的神圣誓约。圣殿骑士对正义的奉献超越生死，造就了在不死中仍服务于正义的斗士，它似乎出自瓦埃利昂·宏钟之手——他在死亡之痕恪守这些神圣职责。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找瓦埃利昂·宏钟。', '', '在死亡之痕寻找瓦埃利昂·宏钟。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53014, 'zhCN', '机械结构图', '有人托我把这个交给你，年轻人。这似乎是绘制在防腐兽皮上的技术蓝图，是由死灵能量驱动的机械设计。死亡为发明带来新的视角——以灵魂能量而非蒸汽运转的机械，它似乎出自莱利·杰特之手——他在死亡之痕创造这些奇迹。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找莱利·杰特。', '', '在死亡之痕寻找莱利·杰特。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53015, 'zhCN', '毒液公式', '有人托我把这个交给你，年轻人。这似乎是一本散发奇异毒药恶臭的书卷，绿色毒雾自经过处理的皮肉书页间渗出。不死者在毒素上的理解胜过任何生者——死亡教授了关于毒药与腐朽的终极一课，它似乎出自毒液收集者彭多之手——他在死亡之痕调制这些致命化合物。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找药剂师凯兰。', '', '在死亡之痕寻找药剂师凯兰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53016, 'zhCN', '灵魂神物', '有人托我把这个交给你，年轻人。这似乎是一卷古老的卷轴，以骸骨与黑暗神物装饰，低鸣着不安灵魂的力量。巫医的技艺通过古老仪式连接生与死，它似乎出自影行者沃斯之手——他在死亡之痕修习这些神秘技艺。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找影行者沃斯。', '', '在死亡之痕寻找影行者沃斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53017, 'zhCN', '审判官的信函', '有人托我把这个交给你，年轻人。这似乎是一封密封的信函，盖有审判庭灼烧的火漆印记。既然你亲身经历过蜕变，便能分辨自然的演化与真正的腐化，它似乎出自贝利·惧憎之手——他在死亡之痕以绝对的公正进行狩猎。在你继续此地的职责之前，我建议你不妨先读读它。', '在死亡之痕寻找贝利·惧憎。', '', '在死亡之痕寻找贝利·惧憎。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(53201, 'zhCN', '星象图', '有人托我把这个交给你，年轻人。这似乎是一份空灵的图表，内含闪烁着真实星光的星图，涌动着来自遥远星系的宇宙力量。唤星者之道开启天界的奥秘，它来自兰德拉拉尼斯——他在死亡之痕统御星辰之力。在你继续此地的职责之前，我建议你不妨先读读它。', '阅读星象图，并在死亡之痕寻找兰德拉拉尼斯。', '', '在死亡之痕寻找兰德拉拉尼斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55100, 'zhCN', '灼痕宝典', '$N，你已完成初次狩猎，并证明了自己的价值。如今你面前的道路出现分歧——你必须选择自己的命运。$B$B这本灼痕宝典是学徒雅克·知尘留给你的。早在你出生之前，他便已感知到你灵魂中燃烧的那团火。控火师之道向那些愿掌控火焰本身之人发出呼唤。$B$B带着这本宝典前往纳拉其营地找他。他将指引你走上永恒之火的道路。', '在纳拉其营地寻找学徒雅克·知尘。', '', '在纳拉其营地寻找学徒雅克·知尘。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55101, 'zhCN', '虚空手稿', '$N，你的狩猎已完成，但一条更黑暗的道路正在召唤你。鲜少有牛头人敢尝试我将要提供给你的一切。$B$B这份虚空手稿由乌尔萨·摧梦留下，她行走在大多数人畏惧涉足的阴影之中。她在你身上看到了某种东西——一种为了更崇高的善而接纳禁忌知识的意愿。$B$B若你有勇气聆听帷幕之外的低语，便带着这份手稿前往纳拉其营地交给她。但你要明白，有些知识一旦习得便无法忘却。', '在纳拉其营地寻找乌尔萨·摧梦。', '', '在纳拉其营地寻找乌尔萨·摧梦。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55102, 'zhCN', '天象图', '$N，你已证明自己是一名猎手，但最伟大的奥秘不在平原之上，而在头顶的天穹。$B$B洛''绍的选民奥科''乌涅特意为你留下了这份天象图。她已解读星辰，看见你的命运书写于尚未命名的星座之中。唤星者之道极为古老，甚至早于我们最悠久的传统。$B$B当繁星明亮之时，带着这份图表前往纳拉其营地交给她。她将教导你统御整个宇宙。', '在纳拉其营地寻找洛''绍的选民奥科''乌涅。', '', '在纳拉其营地寻找洛''绍的选民奥科''乌涅。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55103, 'zhCN', '阳光祷言', '$N，你成功的狩猎已引起了太阳本身的注意。当你靠近时，安谢的光辉愈发明亮。$B$B晨行者雷角为你留下了这份阳光祷言，它受安谢自身光芒的祝福。他已预见，你将成为威胁我们世界的黑暗之中一座希望的灯塔。$B$B带着这份祷言前往纳拉其营地交给他。太阳牧师的道路正在等待——你将把光本身当作武器与护盾来挥舞。', '在纳拉其营地寻找晨行者雷角。', '', '在纳拉其营地寻找晨行者雷角。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55104, 'zhCN', '牛头人符文石', '$N，在你狩猎之时，古老的石头本身也在低语你的名字。当你经过，旧日的传统便悄然涌动。$B$B最古老传统的守护者戈赫罗为你留下了这块符文石。其上每一道刻痕都镌刻于第一位萨满与元素交谈之前、第一位德鲁伊向自然歌唱之前。符文大师之道是我们族人所知最古老的力量之路。$B$B前往纳拉其营地寻他。他将教导你将现实本身铭刻下来。', '在纳拉其营地寻找戈赫罗。', '', '在纳拉其营地寻找戈赫罗。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55105, 'zhCN', '元素图腾', '$N，在你狩猎期间，我亲眼看见元素本身回应着你的存在。大地在你脚下移动，火焰在你的靠近中起舞。$B$B阿穆瓦泰·鹰梦已为你备好这件元素图腾。她仅凭意志统御原始之力——不与精灵讨价，也不温柔请求。元素将服从你，或被强迫服从。$B$B带着这图腾前往纳拉其营地交给她。绝对元素统治之路正在等待你。', '在纳拉其营地寻找生命赐予者阿穆瓦泰。', '', '在纳拉其营地寻找生命赐予者阿穆瓦泰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55106, 'zhCN', '大地盾牌石板', '$N，在你整场狩猎中，你本能地将他人护于危难之外。大地母亲本身已选中你作为守护者。$B$B我们最坚定的卫士莫塔·破石者亲自为你镌刻了这块大地盾牌石板。他在你身上看到了一位不可撼动守护者的潜质——一位无论代价如何，都愿立于邪恶与无辜之间的存在。$B$B带着这块石板前往纳拉其营地交给他。守护者之道要求牺牲，却也给予至高的荣耀。', '在纳拉其营地寻找莫塔·破石者。', '', '在纳拉其营地寻找莫塔·破石者。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55107, 'zhCN', '雷电呼唤', '$N，在你狩猎时，空气本身都因能量而噼啪作响。风暴云在你的头顶聚集，却未落下一滴雨。你已被暴风本身选中。$B$B图安图·云尾在闪电风暴中镌刻下这份雷电呼唤留给你。他已掌控天空的狂怒，并看见同样的怒火沉睡于你的灵魂之中。$B$B带着这份手稿前往纳拉其营地交给他。唤雷者之道将教导你成为风暴的化身。', '在纳拉其营地寻找图安图·云尾。', '', '在纳拉其营地寻找图安图·云尾。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55108, 'zhCN', '祖先战争石板', '$N，我从未在如此年轻的人身上见过这般克制的狂怒。你的狩猎富有章法、精准而毁灭性十足。祖先的怒火在你的血液中奔流。$B$B加拉克·双棍在见证你的潜质后备下了这块祖先战争石板。他承载着千场战斗的狂怒，并认出了一位志趣相投的灵魂。蛮兵之道并非无脑的暴怒，而是专注的愤懑。$B$B带着这块石板前往纳拉其营地交给他。他将教导你驾驭战斗的风暴而不被其吞没。', '在纳拉其营地寻找加拉克·双棍。', '', '在纳拉其营地寻找加拉克·双棍。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55109, 'zhCN', '神圣誓言', '$N，你的狩猎以正义为标记——你只取所需，不无端伤害任何人。正义本身指引着你的步伐。$B$B贾克斯·晨翔为你留下了这份神圣誓言，书写于受大地母亲祝福的兽皮之上。他既是战士也是审判者，并在你身上看到了一位真正正义斗士的潜质。$B$B带着这份誓言前往纳拉其营地交给他。圣殿骑士之道将把你锻造成正义的化身。', '在纳拉其营地寻找贾克斯·晨翔。', '', '在纳拉其营地寻找贾克斯·晨翔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(55110, 'zhCN', '平原猎人指南', '$N，在你狩猎时，我看见你解读他人无法看见的踪迹，穿行他人无法通行的地形。荒野本身已将你视为己有。$B$B纳瓦特·风角在观察你的天赋后制作了这本平原猎人指南。他行走于他人无法追随的道路，并已将你标记为甚至能超越他技艺之人。$B$B带着这本指南前往纳拉其营地交给他。永恒的狩猎正呼唤着你——你将成为我们在荒野中的耳目。', '在纳拉其营地寻找纳瓦特·风角。', '', '在纳拉其营地寻找纳瓦特·风角。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(80651, 'zhCN', '决斗！', '未经训练的战士最先倒下。与其他玩家决斗，磨炼你的战斗技巧。尽情享受这场经验，并将其带入未来的战斗之中。', '你已受到挑战，要与另外五位英雄决斗。', '', '带着荣誉与荣耀归来！', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(80954, 'zhCN', '声望：战场', '该任务将为你以及你队伍中当前正在获取声望的全体成员，在战场中提供额外经验。此任务仅在进行该内容时给予额外经验。达到最高等级并完成目标，即可领取额外的声望奖励！', '在战场中获得额外奖励的声望。', '', '返回克罗米。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(80955, 'zhCN', '声望：地下城', '该任务将为你以及你队伍中当前正在获取声望的全体成员，在地下城中提供额外经验。此任务仅在进行该内容时给予额外经验。达到最高等级并完成目标，即可领取额外的声望奖励！', '在地下城中获得额外奖励的声望。', '', '返回克罗米。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(80956, 'zhCN', '声望：开放世界', '该任务将为你以及你队伍中当前正在获取声望的全体成员，在开放世界中提供额外经验。此任务仅在进行该内容时给予额外经验。达到最高等级并完成目标，即可领取额外的声望奖励！', '在开放世界中获得额外奖励的声望。', '', '返回克罗米。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(81244, 'zhCN', '地下城潜行', '召集板正为那些能够通关普通地下城的精英冒险者提供丰厚奖励。前往地下城查找器并加入一支队伍以证明你的价值，然后将成功的证明带给召集板，领取你的奖励。', '将你成功通关一个普通地下城的证明，带给任意主城的召集板。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(81246, 'zhCN', '史诗地下城潜行', '召集板正为那些能够通关史诗地下城的精英冒险者提供丰厚奖励。前往地下城查找器并加入一支队伍以证明你的价值，然后将成功的证明带给召集板，领取你的奖励。', '将你成功通关一个史诗地下城的证明，带给任意主城的召集板。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(81247, 'zhCN', '地下城潜行', '召集板正为那些能够通关普通地下城的精英冒险者提供丰厚奖励。前往地下城查找器并加入一支队伍以证明你的价值，然后将成功的证明带给召集板，领取你的奖励。', '将你成功通关一个普通地下城的证明，带给任意主城的召集板。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(81249, 'zhCN', '史诗地下城潜行', '召集板正为那些能够通关史诗地下城的精英冒险者提供丰厚奖励。前往地下城查找器并加入一支队伍以证明你的价值，然后将成功的证明带给召集板，领取你的奖励。', '将你成功通关一个史诗地下城的证明，带给任意主城的召集板。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(81255, 'zhCN', '攻城战：雷霆崖争夺战', '牛头人在莫高雷山谷最陡峭的石柱之巅建起了家园。雷霆崖是一座独一无二的城市。将它夷为平地，并击杀牛头人的领袖凯恩·血蹄。', '在雷霆崖击杀凯恩·血蹄。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(81260, 'zhCN', '武装号召：战场', '英雄！我们急需你在战场上的援助！敌军正在所有战线与我们争夺控制权！壮大我们的队伍，引领我们走向胜利！在任意一个战略要地施以援手：带领我们的士兵穿越灰谷的战场，木材对于制造战争机器与建造家园至关重要！掌控风暴之眼的塔楼，我们便能收复虚空风暴中潜藏的能量，将其从凯尔萨斯的控制下解放，以增强我方实力！坚守阿拉希境内的战略要地，那里收集的资源至关重要！在双子峰与敌军争夺，该地对于巩固我们在暮光高地中的阵地不可或缺！你在上述任何一处提供的援助，都是我们赢得这场战争的关键！胜利终将属于我们', '赢下任意一场战场对战，并返回召集板领取你的奖励。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(90189, 'zhCN', '经典随机英雄 60（首次）[经典随机地下城·英雄]', '', '', '', '', NULL);
