(90209, 'zhCN', '经典随机史诗 60（首次）[经典随机地下城·史诗]', '', '', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(90211, 'zhCN', '经典随机史诗 60（第N次）[经典随机地下城·史诗]', '', '', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(100071, 'zhCN', '迪菲亚破坏行动', '噢，呃……你是那种勇敢的人吗？就是那种对付危险、怪物还有……那些玩意儿的人？只是最近这里的情况不一样了。酒馆安静了，道路显得空荡，连平时那些吵闹的家伙都不经过了。我一直在劝自己这只是淡季，但是……我觉得不是那样。我听到一个传闻，只是个传闻，说那些迪菲亚匪徒在镇子东边某处建了个营地。人们说他们拦劫旅客、偷窃物资，或许更糟。我不太确定，但是……也许如果有人去那边给他们点教训，让他们三思，情况会缓和一些？那样或许大家就会回来了。', '在闪金镇以东的强盗堡垒削弱迪菲亚的势力。', '', '返回艾尔文森林闪金镇的米利卡·艾森斯泰德。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(100073, 'zhCN', '补给运输', '听着，如果你还有心继续这任务，我有些后续的事要托付你。有传言说迪菲亚在那边东头聚成了一个像样的窝点。那是个大营地，比寻常乌合之众组织得多。不久前，一些本地商人遭了袭。成箱的补给被抢走了，都是些有用的东西，比如工具、布料，甚至还有些稀有的烈酒。都是这一带人们赖以生存的货物。这并非没有风险，但如果有人能进去把失去的东西夺回来，我知道有几个人会感激不尽。我会确保你为此得到回报。', '从闪金镇以东的强盗堡垒取回 4 个被窃的补给箱。', '', '返回艾尔文森林闪金镇的雷米「双料」。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(100074, 'zhCN', '内部的背叛', '你找到了一份看似真正的联盟文件，它由一名深驻迪菲亚前哨、打扮成士兵的男子携带。文件内容指向联盟军队与本地匪徒之间的勾结。这种事本不该发生。需要一位忠诚的人看到它。将文件交给一位合适的联盟官员。若幸运，他们自会知道该如何处置。', '返回治安官杜汉。', '', '返回艾尔文森林闪金镇的治安官杜汉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(100077, 'zhCN', '率领团队副本！', '召集板正在寻找指挥官。保持队长身份，击败任意团队副本的最终首领，然后返回召集板领取你的奖励。', '带领任意团队副本队伍击败最终首领，赢得胜利。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(100078, 'zhCN', '率领地下城！', '召集板正在寻找指挥官。保持队长身份，击败任意非史诗+地下城的最终首领，然后返回召集板领取你的奖励。', '带领任意非史诗+地下城队伍击败最终地下城首领，赢得胜利。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(170010, 'zhCN', '艾泽拉斯的威胁：瑟提斯', '致艾泽拉斯的所有英雄：早在我们的记忆所及，其拉虫人便已侵扰艾泽拉斯。\\n\\n近来，他们开始利用希利苏斯阿努比萨斯的力量。阿努比萨斯是由活体岩石驱动的巨人，拥有奇异的力量。阿努比萨斯一个名为瑟提斯的具体化身，一直为位于希利苏斯的塞纳里奥议会的高贵成员们制造祸患。\\n\\n集结你的力量，摧毁瑟提斯。', '摧毁瑟提斯！', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(170015, 'zhCN', '艾泽拉斯的威胁：泰拉尔', '致艾泽拉斯的所有英雄：\\n\\n泰拉尔或许是伊瑟拉叛变副官中受影响最深的一位，他一直在惊吓艾泽拉斯的居民。他与翡翠梦境中黑暗力量的交融，粉碎了泰拉尔的理智与其肉身形态。这条龙如今以幽魂的形态存在，能够分裂为多个实体，每个都拥有毁灭性的魔法力量。泰拉尔是一个狡猾而无情的敌人，一心要将自身存在的疯狂变为艾泽拉斯居民的现实。', '击杀梦魇之龙泰拉尔！', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175000, 'zhCN', '苍白海岸的召唤', '你是要前往苍白海岸吗？$b$b我的主人，瑟文·达伦加领主，命我在此地招募一切能找到的助力。观你外貌，想必能成为极好的一员。$b$b你也知道，我主人的故乡斯卡迪尔德行省正面临至暗时刻：霜鬃巨魔自山中倾巢而下，匪徒在光天化日之下拦劫旅客……当然，还有那野蛮的艾尔迪尔，最坏的一伙。$b$b前往位于暴风城要塞内、回廊庭院之下的贵族议院，向达伦加领主禀报。告诉他是我派你来的。$b$b你所能提供的任何援助，他都会给予丰厚的奖赏。', '在暴风城要塞的庭院中找到阶梯，并在请愿者之厅与瑟文·达伦加领主交谈。', '', '与瑟文·达伦加领主交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175001, 'zhCN', '贵族议院', '<钟声在贵族议院中回荡。瑟文·达伦加领主叹了口气，在并不舒适的座位上挺直了背。>$b$b看来我们的喘息已到尽头。$b$b暂且退到一旁，让我们这些贵族把吾爱之行的命运辩论完毕。$b$b观察、聆听并评判。届时你便会理解我的绝望。', '出席贵族们的聚会。', '', '与瑟文·达伦加领主交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175002, 'zhCN', '家族庄园', '倘若暴风城那珍贵的律法注定让贵族议院无所作为，那便随它去。他们并非我唯一的出路；据我所知，没有任何律法禁止我以私人身份招募雇佣兵与冒险者的援助。$b$b因此，我就会这么做。你就当自己是被「雇用」了。$b$b拿上我的印章。我的儿子阿拉松留在了斯卡迪尔德，试图减轻该行的苦难。去见他，向他献上你的效劳。我会尽快设法派出更多人手；眼下，有你便已足够。', '向位于斯卡迪尔德的达伦加庄园的阿拉松·达伦加报到。', '', '与卡德米拉交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175003, 'zhCN', '灰天正义', '<卡德米拉拭了拭眼角。眼中骤然燃起决心。>$B$B你带着瑟文领主的印章。这意味着你得到了他的信任。所以，仔细听好：$B$B我需要你在那些灰天暴徒找到之前，把阿拉松的日记带给我。若那些纸页落入瑟蕾妮娅女爵手中，她会在黎明前签下他的死刑令。$B$B快去！我会设法引开门口的队长。', '在达伦加庄园内找到阿拉松的日记。', '', '返回卡德米拉', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175004, 'zhCN', '阴谋札记', '<卡德米拉啪地合上日记。>$B$B那么，是真的。我的主人阿拉松曾与艾尔迪尔勾结。$B$B你听说过他们吗？他们自称是这片土地原住民的子孙。渴求独立的异教徒与异端。简而言之，野蛮人。$B$B我的兄长数年前死于艾尔迪尔的一次伏击。$B$B日记中提及庄园地下的洞穴，以及关于水井的一些事。我怀疑我们能在下面找到答案。你愿意去查探究竟吗？', '下到达伦加庄园的水井中，调查其中隐藏之物。', '', '调查武器箱。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175005, 'zhCN', '信奉一种理想，便须甘愿背叛它', '<当你检视这些箱子时，一阵寒意顺着脊背流下：几乎所有武器都已被洗劫一空。周围一串脚印显露出一种令人不安的混合——沉重的靴印与赤足的足迹。>$B$B<看来那是真的：阿拉松·达伦加曾与艾尔迪尔结盟。>$B$B<你应当寻找更多信息，将他们的计划公之于世。>', '消除艾尔迪尔的威胁，并揭开他们在达伦加庄园水井中酝酿的阴谋。', '', '向赫德加队长报告', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175006, 'zhCN', '灰天的黑鸦', '我料想这座庄园里还埋藏着诸多秘密。达伦加家族背着我们冷湖家族暗中图谋已有多年；我们不过才触及他们阴谋的皮毛。$B$B至于你，你展现了勤勉与稳健的判断力。若你正前往灰天，我有一项任务交给你；这是至高的荣耀：$B$B去面见我的女主人瑟蕾妮娅·冷湖女爵，将我们今日在此揭发的真相禀报于她：阿拉松领主叛国行径的规模之巨，以及艾尔迪尔那阴森的图谋。', '向灰天的瑟蕾妮娅·冷湖女爵复命。', '', '去面见瑟蕾妮娅·冷湖女爵', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175007, 'zhCN', '伤口、疤痕与流血', '达伦加家族的背叛虽然阴险，但不过是这场蹂躏本省的无尽灾祸中的沧海一粟。$B$B我们对待艾尔迪尔，已如病者习惯了自己的宿疾。他们是这片土地上一处慢性的瘟疫，若非霜鬃巨魔的入侵，我早将他们肃清。$B$B<瑟蕾妮娅女爵定定地凝视着你，目光悠长而沉稳。>$B$B我相信你具备所需的一切。若你也这样认为，便去王座厅向灰空卫兵指挥官德拉温爵士复命。他会告诉你如何助我们击溃敌人、恢复秩序。', '向灰天王座厅的德拉温爵士复命。', '', '去面见德拉温爵士', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175008, 'zhCN', '当白昼渐短', '你！对，就是你！耽搁你片刻！$B$B你看起来是那种能照顾好自己的人。你正前往斯卡迪尔德省吗？我的丈夫杜尔甘在灰天宫廷，我需要有人把这些货物交给他。$B$B想必你已听说了：连接暴风城与铁炉堡的王道已被巨魔占据，贸易彻底停滞。斯卡迪尔德不再安全！而照眼下这般情形，我可不敢冒险前往灰天。$B$B我需要一名信差。你觉得如何？报酬定不会亏待你，我向你保证；我丈夫向来比我出手阔绰。', '前往灰天，将货物交给杜尔甘。', '', '将货物交给灰天的杜尔甘。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175009, 'zhCN', '邓郡的援助', '我已收到来自邓郡的令人不安的消息，却抽不出人手去援助那个村庄。$B$B此类事务通常由当地贵族处置，但邓郡隶属达伦加领地。而迄今为止，达伦加家族只让糟糕的局面雪上加霜。$B$B我需要你以灰天使者的身份前往邓郡。与阿姆罗斯·达戈尔队长交谈，看看村民需要何种帮助。', '向邓郡的阿姆罗斯·达戈尔队长复命。', '', '去面见邓郡的阿姆罗斯·达戈尔队长。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175010, 'zhCN', '王道之争', '温德海姆军士正于前线指挥战事，但我们对霜鬃巨魔的推进微乎其微。敌人仍掌控着王道，我们每斩杀一名巨魔，便有两名为其替补。$B$B在威胁斯卡迪尔德完整的所有危机中，没有比这更迫在眉睫的了。$B$B向温德海姆复命。自我统领灰空卫兵以来所学到的唯一一件事便是：战争并非总由大军赢得。即便是最卑微的士兵，也能扭转战局。', '向王道上灰天前哨的温德海姆军士复命。', '', '去面见王道上灰天前哨的温德海姆军士。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175011, 'zhCN', '克雷斯特海恩的援助', '我刚收到克雷斯特海恩一位牧师埃尔罗斯神父的来信。看来他们正遭遇某种……非比寻常的麻烦，姑且这么说。与墓穴有关。无疑，是艾尔迪尔的黑暗魔法。$B$B克雷斯特海恩是本省的的第二大聚居地，仅次于灰天。然而，它的位置使其成为最易遭艾尔迪尔暴力侵袭之地。$B$B以灰天使者的身份去面见埃尔罗斯神父，并尽你所能提供援助，以纾解克雷斯特海恩的苦难。', '向克雷斯特海恩的埃尔罗斯神父复命。', '', '去面见克雷斯特海恩的埃尔罗斯神父。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175012, 'zhCN', '圣风悬空修道院', '此地人人谈及王道，仿佛它是本省的命脉。他们错了。早在灰天第一块基石铺下之前，教会便已在斯卡迪尔德立足。$B$B圣风悬空修道院是其志业的长子；本省最古老、最崇高的建筑。然而，战争颠覆了棋局。如今我唯恐这座城市的当权者已疏于对修道院的职责。$B$B去吧，去面见阿姆罗德神父，告诉他灰天仍未忘记自己的誓约。教会绝不可倾覆。', '去圣风悬空修道院面见阿姆罗德神父。', '', '在圣风悬空修道院与阿姆罗德神父交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175013, 'zhCN', '信仰的危机', '修道院是研习与内省的圣殿，是人与神之间帷幕最稀薄之处。通透。$B$B这看似恩赐，但作为交换，它要求纪律与绝对的奉献。你可明白''绝对''一词的含义？很好，因为此处并非人人都明白。$B$B一些初修士正勉力将其付诸实践。甚至有几人正考虑弃修道院而去。$B$B去与他们交谈。向他们发起决斗。唤起他们对圣风等级秩序的记忆……以及背弃誓言的后果。', '向陷入信仰危机的初修士发起决斗，以唤起他们对圣风等级秩序的记忆。', '', '回到阿姆罗德神父处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175014, 'zhCN', '圣风的十字军', '如今我明白，那随军牧师不过是圣光意志的工具，回应着我们的祈祷。我祈求奇迹降临，而你便来到了此处。$B$B容我向你说明局势：修道院以东的山丘中，我们不过十个月前才发现了一个那种异教徒族类的巢穴，其存在本身便是对人类尊严的亵渎。$B$B我说的便是穴居人。$B$B尽管我派出了麾下最精锐的部下应付他们，但心底里，我始终疑心是将他们送向死路。或许你能证明我的直觉是错的？', '找到阿姆罗德神父派去应付穴居人的十字军。', '', '与十字军迪亚洛斯交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175015, 'zhCN', '肃清污坑', '穴居人的巢穴在冰封之河对岸，过了桥便是。$b$b<一种狂热的决心攫住了迪亚洛斯。>$b$b能杀多少就杀多少。灭绝他们。砸碎他们的脑壳！用利刃将他们刺穿！用你——将他们碾成肉泥！$b$b<一阵咳嗽打断了迪亚洛斯的激昂。他啐在雪地上的痰中带血。>$b$b让他们尝尝他们加诸我同袍身上的同等仁慈。', '击败污坑中的穴居人。', '', '向阿姆罗德神父复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175016, 'zhCN', '净化污坑', '<穴居人造物。它散发出奇异的绿色光芒，仿佛沐浴在辐射之中。>$B$B<若此神像与这些穴居人的信仰有所关联，那么它的来历无疑在诺姆瑞根。摧毁这些神像应能削弱他们。>$B$B<你应将此造物带往圣风悬空修道院，以便查验。>', '摧毁污坑中穴居人信仰的神像。', '', '在修道院找到学者恩哈隆，将穴居人神像交予他查看。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175017, 'zhCN', '击杀污坑之王', '里面的穴居人并非寻常穴居人……他们是士兵。有人在领导他们。他们听从号令。$B$B号令……<迪亚洛斯的呼吸紊乱不定。他每说一个字都像被刺痛。>有号令之处，便有领导者。有领导者之处，便有机会。$B$B找到他，杀了他。杀蛇只有一种方法，那便是斩下它的头颅。', '在污坑中击败污坑之王奥古斯都。', '', '向阿姆罗德神父复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175018, 'zhCN', '路旁的暴行', '<商人额头沁出汗珠，艰难地搜寻着词句。他的手腕上有被紧紧捆绑的痕迹；显然他曾被囚禁。>$B$B我的货车……我的货……我可怜的驴子托托……全毁了。何等灾祸……$B$B感谢圣光，卫兵及时赶到，在那些恶徒把我弄成和托托一样下场之前将他们吓退。$B$B<商人望着被洗劫的货车，垂头丧气。>$B$B我无法从这场打击中恢复过来了……我把全部身家都投进了这批货。求你，帮帮我！找出那些暴徒的巢穴，取回他们从我这里偷走的东西。', '在北艾尔文的深石洞穴中取回被盗的货物。', '', '回到商人萨温处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175019, 'zhCN', '北境之剑', '王道从未真正安全过，但南方的省份牵扯了我们全部注意力，该死的迪菲亚，它如今比以往任何时候都更加危险。$B$B城这一侧的士兵少得可怜，当地强盗对此心知肚明。$B$B你愿意助我们一臂之力吗？必须有人去追捕那些袭击商人的匪徒。为了王国的安危。', '击败藏身于北艾尔文深石洞穴中的强盗。', '', '回到卫兵多恩赫尔姆处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175020, 'zhCN', '自暗影井而下', '我确信暗影井河的源头正发生着什么。鱼人源源不断地涌向这片湖岸，而鱼儿绝不会这样咬钩。$b$b在鱼人数量超出我们应对能力之前，将你在此地发现的鱼人尽数消灭。$b$b这或许无法根治问题，但至少能让暴风城的寻常人家今日餐桌上能有鱼吃。', '击败北艾尔文兰登湖畔的鱼人。', '', '回到埃德林·萨尔米尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175021, 'zhCN', '为伤者寻钩草', '那些该死的鱼人……我迟早要报此仇！$B$B<渔夫的伤口尚新。虽看似无性命之忧，但须在情况恶化前得到医治。>$B$B一名鱼人伏击了我，夺走了我好不容易钓到的那点渔获。我能活着讲述此事已属万幸，如今却几乎站立不稳。我想它的武器淬了毒……$B$B这片湖中生长着一种我们渔夫常用来医治毒鱼所伤的植物。我们称之为钩草。帮我把几株嫩芽采来，好吗？', '在兰登湖采集钩草，交给受伤的渔夫。', '', '回到受伤的渔夫处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175022, 'zhCN', '白手套的恶作剧', '呃……那个……你好。$B$B我没在搞什么名堂，好吗？$B$B只是……我接到了一项任务，而且……说实话，我没自己想的那么勇敢。我觉得自己会把事情搞砸。我总是把事情搞砸……$B$B哈？你……你愿意帮我？真的吗？让我想想……你得这么做：$B$B<男孩一边一项项列出任务，一边一根根抬起纤细的手指。你注意到他的小指缺失了。>$B$B一：溜进城堡。二：抵达陈情者密室。三：打开这个酒壶。四：回到瑟……回到小保罗身边！$B$B这很简单……对吧？你愿意帮我吗？', '潜入暴风城城堡内的陈情者密室，打开小米的酒壶。', '', '回到小保罗处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175023, 'zhCN', '矿洞深处的秘密', '邓郡首先是一座矿业城镇。环顾四周。你可察觉到什么异样？没有？我告诉你：这里几乎已无男丁留存。$B$B几周前发生了某事，一件我无法解释之事：$B$B一伙豺狼人在换班途中突袭了矿洞。但是……他们从何而来？又为何仍在其隧道中出没？$B$B我怀疑矿工们把自己堵在了里面，若是如此，他们时日无多。我本盼着德拉温爵士派来更多士兵，但你便将就吧：前往矿洞。对付豺狼人，救出矿工。', '击败铁枝矿洞中的豺狼人，并探索其隧道寻找失踪的矿工。', '', '与阿尔托·比尔伯格交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175024, 'zhCN', '女巫的援助', '<你注意到那豺狼人竭力吐出正确的字眼时，神情中的绝望。>$B$B附近有女巫。林中有棚屋。她有法子。这是诅咒。黑暗魔法的诅咒。女巫是黑暗魔法行家。$B$B女巫诅咒了我们？$B$B你去与她谈。恳求。倾听。寻得治愈身心之法！', '找到住在邓郡上方峭壁孤棚中的女巫，请求她帮助解除矿工身上的诅咒。', '', '与贝尔德雷德交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175025, 'zhCN', '精灵尘', '兴趣。一切皆归结于此。$B$B我提议做个交易：我愿调制解除诅咒的药剂，但作为交换，我要你帮我取得一味材料：$B$B精灵尘。$B$B我的药剂需要它，包括这一剂；而如今我独自获取它愈发艰难。因为……嗯。它采自游荡于邓郡的精怪，它们可是些令人难以忍受的小东西，相信我，滑溜得不能再滑溜。$B$B杀几只精怪，给我带足精灵尘，我便会助你。', '从邓郡附近游荡的精怪身上获取精灵尘。摇动被施了魔的花朵以召唤它们。', '', '回到贝尔德雷德处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175026, 'zhCN', '安抚内心的豺狼人', '这个……<贝尔德雷德递给你一只盛有橙色液体的酒壶，宛若液态琥珀。>这些应该够了。我想。$B$B回到矿洞，在被诅咒所染的矿工之一身上试验这药剂。挑那些怀有敌意的；即已变成无脑豺狼人的那些。你知道的，以防它不能完全奏效。$B$B<一声短促的轻笑泄露了贝尔德雷德顽皮的幽默感。>', '在矿洞中的豺狼人身上试验贝尔德雷德的药剂。你需先将他们削弱。', '', '回到贝尔德雷德处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175027, 'zhCN', '精灵魔法', '这些峭壁的另一侧，水流切割出一座山谷，如今成了高等精灵的家园。他们的领袖，若这称号适用，是一位拥有可怖力量的女术士。我相信，她是整个斯卡迪尔德最强大的人。$B$B从此处进入山谷的唯一通道，是邓郡的一处洞穴。然而，它由精灵的附魔守护，挡住那些不被视为精灵之友者的去路。$B$B探查洞穴周边。若你寻得穿过屏障之法，便以最快速度赶往精灵圣所，向女术士阿玛兰忒陈情。若有人能施以援手拯救矿工，那便是她。', '设法穿过魔法屏障，抵达鎏金谷。抵达后，与阿玛兰忒·奈米尔女爵交谈。', '', '在纳马里恩圣所寻访阿玛兰忒·奈米尔女爵', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175028, 'zhCN', '邓郡招牌馅饼', '抱歉，我今天忙得不可开交，不再接任何订单了。改天再来吧——$b$b<面包师抬眼望了片刻。>$b$b哎呀呀……我们这里来了什么人？一位真正的嗜甜之徒！$b$b你来定是想尝尝我的拿手好戏。那闻名世界的邓郡馅饼！灰天、克雷斯特海恩、裂岩、暗影井，甚至邓卡扎德的人都专程赶来……而且总是去而复返！$b$b没错，你已是垂涎欲滴。我会为你做一个，别担心，但作为交换，我需要你搭把手今天的活计。先从作物田里收割麦子开始。收齐后，把它交给磨坊主。', '采集制作闻名遐迩的邓郡馅饼所需的麦子。', '', '与磨坊主巴特伦交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175029, 'zhCN', '自谷物至面粉', '面粉生产不能停，而今天的风实在不够大，难以完成所有这些订单……$B$B<你向磨坊主解释，你只需为面包师的活计磨一点麦子。>$B$B邓郡馅饼！？你早该说嘛！把麦子给我，我亲自帮你！$B$B我会把谷物倒入料斗；你来好好转动那摇柄。今日风不助我们，而若想做出像样的馅饼，我们需要上好的面粉。', '启动风车，产出制作闻名遐迩的邓郡馅饼所需的面粉。', '', '回到赫斯特温·蜜壳处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175030, 'zhCN', '从田垄到餐盘', '邓郡馅饼的配方需要数种材料。我这儿已有大部分所需之物，但你这嗜甜之徒仍须再提供几样。$B$B出去，给我带邓郡母鸡所产的最上等鸡蛋。$B$B还有……嗯……我本可让你去爬山，但你去酒馆买上几升他们从山顶运下的精致风拂牛奶，要更省事些。', '从邓郡酒馆取得邓郡鸡蛋与精致风拂牛奶。', '', '回到赫斯特温·蜜壳处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175031, 'zhCN', '甜美的耐心', '如今轮到我了。我或许不懂如何驾驭元素，或召唤奥术，或你们那种冒险者会做的任何事……可一旦你尝过邓郡馅饼，你便不会否认，我所达成的成就与之同样壮丽。$B$B大师需要时间。给我几分钟，以它应得的用心将其塑形，再让炉火的热力施展魔法。$B$B所以稍后再来吧，你这嗜甜之徒。', '等待面包师完成闻名遐迩的邓郡馅饼。', '', '与赫斯特温·蜜壳交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175032, 'zhCN', '遗失的徽记', '你！对，就是你。你没在这儿附近见过一枚徽记吧，有吗？$B$B<见你摇头，达隆德的肩膀垮了下来。>$B$B我是本村的脚夫，也是精灵们的''朋友''。我丢失的这枚徽记，是我通过洞穴中那道魔法屏障的凭仗。没有它，我无法履职；精灵们时不时需要我的服务。$B$B眼下便是这样的时刻。而那护符我已无处不寻。$B$B你愿意助我一臂之力吗？', '找到邓郡脚夫达隆德所属的魔法护符。', '', '与达隆德交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175033, 'zhCN', '送往乐土的货物', '你来了。好。送货所需的一切我都已备齐。拿上徽记。穿过洞穴中的魔法屏障时你会用上它。$B$B扛起包裹，前往纳马里恩圣所。抵达目的地后，寻找哈尔丁·绿歌。他是圣所的商人，也是下达你即将配送之订单的精灵。$B$B报酬你收着。你为我提供的帮助，这报酬你受之无愧。不过，若我没弄错，一旦你亲眼见到鎏金谷，你会觉得任何其他奖赏都黯然失色。', '取走达隆德的货物，穿过洞穴前往鎏金谷。抵达后，前往纳马里恩圣所找到哈尔丁·绿歌。', '', '在纳马里恩圣所寻访哈尔丁·绿歌', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175034, 'zhCN', '熊的暴怒', '熊正成为麻烦，而这全是艾尔迪尔的过错。那些关于森林与精灵的论调……伪善者！他们占据熊的洞穴，扰乱它们的冬眠节律……$B$B如今这些野兽狂怒地游荡林间，在村庄附近徘徊，袭击我们的农场。必须制止！$B$B唯一的短期对策便是猎杀它们。成年熊、幼熊……我们概不宽恕。$B$B将你在外发现的熊尽数杀死，把皮毛带给我，好让它们的死并非全然徒劳。', '杀死斯卡迪尔德熊，将皮毛带给约尔南·塔洛尔。', '', '回到约尔南·塔洛尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175035, 'zhCN', '理想即毒药', '你……你不是本地人。或许你听过我儿子的消息？$B$B阿贝隆是个红发，留着长须和蓬乱的鬃发。凯恩金发、面净无须、蓝眼、短发。$B$B他们几天前离开了村子。阿贝隆执意要……嗯，他有些复杂的念头：他想加入艾尔迪尔，正如他兄长凯恩加入了克雷斯特海恩民兵。$B$B他们起了争执。动了手。阿贝隆逃走了，凯恩在后面追。他们的眼神，噢，那眼神！我当时便知他们已准备不顾一切。甚至准备互相残杀。$B$B数日已过，我唯恐最坏的结局。若你探得他们的任何消息，若在旅途中与他们不期而遇……请告诉他们，他们的母亲深切地思念着他们。', '寻找线索追踪阿贝隆与凯恩，弄清他们的下落。', '', '与受伤的雇佣兵兰德克交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175036, 'zhCN', '艾尔德梅恩洞穴', '你看起来是那种能照顾好自己的人。或许我们能互相帮个忙。$B$B看到这人了吗？<兰德克毫不客气地晃了晃右侧那具裹尸。看衣着，是个艾尔迪尔。>$B$B我本打算剥下他的衣服，穿着潜入艾尔德梅恩洞穴。显然，如今这对我已是痴人说梦。$B$B但你……你方才提到了什么兄弟，对吧？既然你本就要去那洞穴，利用这伪装才是明智之举。若你进去后找到这帮乌合之众的首领……把他的脑袋带来给我。我们在灰天悬赏的酬金，五五分账。$B$B你觉得如何？', '检视兰德克旁的尸体，伪装成艾尔迪尔潜入艾尔德梅恩洞穴。', '', '与雷伊·安拉莫尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175037, 'zhCN', '艾尔迪尔的力气试炼', '你可具备所需的一切？你愿为这事业赴死吗？愿为斯卡迪尔德的自由而杀戮吗？$B$B那就向我证明你的价值。$B$B洞穴入口这段还有与你相仿的其他新兵，急于留下自己的印记。向他们挑战。给我好好演一场。让我看看你是什么材料铸成的。$B$B到那时，或许，我才会正眼看你。', '向艾尔迪尔学徒发起决斗并将其击败。', '', '回到雷伊·安拉莫尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175038, 'zhCN', '悬赏一颗头颅', '<你已成功进入艾尔德梅恩洞穴。如今，正如洞外那受伤的雇佣兵兰德克所言，剩下的唯有找到首领并取其首级。>$B$B<可以想见，这伙人的首领应位于洞穴最深处。>', '在艾尔德梅恩矿洞杀死酋长克拉根，将他的头颅带给兰德克。', '', '向兰德克复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175039, 'zhCN', '正直的兄弟', '又怎么了？是他们派你来折磨我的吗？我早就告诉过你——我绝不会让你听到我尖叫而得意。$B$B<你从囚犯身上认出了克雷斯特海恩那妇人对其两个儿子之一的描述：金发、短发、面净无须。这定是凯恩。>$B$B<你接着告诉他，是他母亲派你来的。>$B$B赞美圣光！我还以为要烂在这笼子里了。你必须把我弄出去。不惜一切代价。找到笼子的钥匙。某个艾尔迪尔拿着它。杀了他。把他们全杀了。这些野蛮者无一清白！', '找到开启凯恩牢笼的钥匙。为此，击败附近的艾尔迪尔。', '', '将钥匙交给凯恩', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175040, 'zhCN', '无谓的死亡，破碎的心', '我还能怎么做？我兄弟总是不切实际。他为某些念头辩护……他同情艾尔迪尔！他甚至想加入他们。$B$B我们面对面。兄弟对兄弟。男人对男人。而我杀了他。是的。我杀了他。因为那是我的职责。我身为士兵的职责。我身为兄弟的职责；守护我们家族的荣誉。$B$B我明白母亲不会如此看待。但父亲，相信我……若父亲尚在，他定会亲自动手杀了他。$B$B给。阿贝隆的项链。我不知道我被俘后艾尔迪尔如何处置了他的尸体，但母亲会想要一件可下葬之物，即便只是象征。拿去吧。', '回到克雷斯特海恩的阿拉莉娅处，将你探得的她两个儿子的下落告知于她。', '', '与阿拉莉娅交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175041, 'zhCN', '无人父母应埋葬自己的孩子', '<阿拉莉娅的啜泣持续了令人揪心的数分钟。随后，毫无预兆地，风暴平息，一种奇异而令人不安的平静攫住了她。>$B$B我们该把项链安葬了。我要为我儿子立一座坟。即便我没有他的遗体。我不在乎；我会找到他。我会的。$B$B我会的。$B$B你……我没有力气离开这屋子。也不愿村里任何人见到我这副模样。拿上项链。去墓园，找到我丈夫诺根·多尔曼的坟墓。将它葬在他左侧的壁龛里。', '将阿贝隆的遗物安葬在克雷斯特海恩墓园诺根·多尔曼的坟旁。', '', '回到阿拉莉娅处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175042, 'zhCN', '地下的声响', '我已闩上门，并为门槛祝祷。除此我不知还能做什么。$B$B教堂之下有什么正在蠢动。$B$B黑暗魔法，而且是最污秽的那种。死者正舍弃坟墓，在墓穴的廊道中游荡。$B$B<埃尔罗斯神父抬手做了一个手势，仿佛在为自己祝祷。>$B$B必须有人赐他们安息。而且要快，趁他们逃出墓穴、将恐惧播撒全村之前。', '击败在克雷斯特海恩教堂墓穴中游荡的亡灵。', '', '向埃尔罗斯神父复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175043, 'zhCN', '不惜一切代价', '<在一具男尸旁发现的日记。>$B$B“我最亲爱的阿兰娜。没有你的笑容，日子便日渐枯萎。我常想起我们如何令不可能变为可能；一名艾尔迪尔与一名十字军，无可救药地相恋。准备不顾一切。甘愿悖逆我们各自的信仰；圣光，林中之神。$B$B你深懂我，阿兰娜。所以你知晓我意欲何为。若我们曾令不可能变为可能，为何不再试一次？$B$B这是我的誓言：$B$B无论代价几何，我必将你带回。而我知道从何着手：$B$B你故事中的三姐妹。”', '在克雷斯特海恩教堂的墓穴中找到阿兰娜的墓冢。', '', '与阿兰娜交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175044, 'zhCN', '歌唱的女巫', '卡登想将我带回……$B$B他成功了……连我一起。连我们所有人一起……$B$B<每个字都如刺痛。存在的每一秒，都是煎熬。>$B$B如今我们无法死去……我们尝试过一切……$B$B别告诉埃尔罗斯神父……谁也别告诉！艾丝琳，在酒馆……找到她。她会知道去哪里寻三姐妹。$B$B求你……只有她们能助我。只有她们能纠正这悖乱。', '在克雷斯特海恩的酒馆寻访艾丝琳。', '', '与艾丝琳交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175045, 'zhCN', '三重祝福', '相传三姐妹栖居于迅水的瀑布之中。但通行需要一种安全凭据：$B$B三位不同女巫的祝福。$B$B这在往日轻而易举。然而如今，斯卡迪尔德几乎每一位女巫都已向莫格温娜宣誓效忠，她们会对你见而即攻。$B$B我自会赐你祝福，但仅凭我一人的不够。须由你去寻另外两位肯助你的女巫。', '获得三位斯卡迪尔德女巫的祝福。', '', '在灰天找到卡萨尔', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175046, 'zhCN', '今日渔获：鳟鱼', '噢！感谢圣光；一位旅人！而且看模样是个无畏的旅人！能请你帮个忙吗？$B$B不过一天前，艾尔迪尔便是在这座桥上伏击了几名旅人。看看这局势！卫兵劝我不要离开小径，可我卖的鳟鱼不会自己爬上峡谷来到我的摊前。而我实在不敢擅自走远。$B$B你能为我捕几条鳟鱼吗？我自会付你钱；小心驶得万年船！', '为店主默塞尔捕捉斯卡迪尔德鳟鱼。', '', '回到店主默塞尔处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175047, 'zhCN', '扫清渡口', '我们已追踪到昨夜袭击桥梁的艾尔迪尔，他们藏身于附近一处洞穴。$B$B我们不可轻易弃守岗位，也不指望灰天会派来援军；卫兵人手分散，正应付王道的战事。你知道的……那霜鬃巨魔。$B$B若你愿意，这便是一项交由你的任务。我会在你的地图上标出洞穴位置。进去，消灭你在洞中发现的艾尔迪尔。那些野蛮者只懂以眼还眼，我怕。$B$B而你知道么？我们也一样。', '消灭锯齿洞穴中的艾尔迪尔。', '', '回到卫兵格里姆斯班处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175048, 'zhCN', '帷幕稀薄之处', '退后……退后，否则我凭最后一口气也要向你降下诅咒……$B$B<一阵咳嗽令霍尔嘉痛苦地弯下腰。待她缓过气，眼中已无半分违逆之色。>$B$B他们派我们来对付有角者……去封闭那仪式开启的裂隙。但是……已经太迟了。他们全死了。$B$B退后。你进去只会找到死亡……', '深入夜织洞穴，击败有角者，并关闭黑木裂隙。', '', '回到霍尔嘉处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175049, 'zhCN', '鲜血与职责', '别杵在那儿！$B$B你是来搭把手的，还是来袖手旁观、任你的同袍在雪地中血流而亡的？$B$B在急救补给里找一卷厚绷带，照料伤员。他们正舍生守护本省与王国。你的王国亦然！$B$B快动起来！', '在急救补给中寻找厚绷带，照料伤员。', '', '回到战地医师索琳处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175050, 'zhCN', '牺牲的凭证', '巨魔的伏击，以及随后的战斗，将雪地染成鲜红。数百人丧生；朋友、同志。同袍。$B$B我们至今未能寻回他们的遗体。见鬼，自那以后我们除了把尸身抛入雪中一事无成。$B$B帮我个忙：我不要你扛任何尸体，但至少找回他们的徽章。待这场噩梦终结、最后一只霜鬃巨魔倒下时，我们能有凭吊之物。', '在霜鬃伏击点周边找回阵亡士兵的徽章。', '', '回到准尉埃德里克处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175051, 'zhCN', '夺回王道', '看看他们。害虫。<温德海姆将头猛地朝向树木，那是一个浸满恨意的动作。>$B$B自数周前首次伏击以来，争夺王道控制权的零星交火便从未停歇。我们的处境岌岌可危：每杀一只巨魔，便有两只补上。而我方损失却无法如此弥补。$B$B但总指挥派你来了。这意味着他在你身上看到了什么。某种是时候拿来一试的东西。$B$B深入森林，消灭任何在王道上徘徊的霜鬃伏击者。随后，向过河之桥附近的先遣队复命。', '斩杀在王道上徘徊的霜鬃伏击者。', '', '向弗里伦中尉复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175052, 'zhCN', '祖拉蒙达的獠牙', '让你身后那串巨魔尸骸，成为对其余者的警告。忘掉森林；真正的危胁就在前方。$B$B<弗里伦戴着手套的手一挥，指向你面前的遗迹。>$B$B祖拉蒙达。我们的侦察兵确信霜鬃巨魔正从内部协调其战事。洞穴广袤，必是敌人云集。而从你的神情看，这倒像一份请柬。$B$B好，我料到的也不外如此！深入遗迹，击倒每一个挡路的冷血杂种。去吧。去吧！', '杀死祖拉蒙达遗迹与洞穴中的霜鬃巨魔。', '', '回到弗里伦中尉处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175053, 'zhCN', '巨魔的冷酷仁慈', '当你直面一只霜鬃巨魔，三种结局之一会降临：你将其击倒，你成为它的下一餐，或你发现自己被拖向祖拉蒙达的废墟。$B$B那地方挤满了巨魔的囚徒；多半是我们在战斗中负伤的士兵。我不知他们打算如何处置他们，但我宁可不去知道。$B$B你在洞中杀出一条路时，尽可能解救更多人。我会在外面等候，确保他们被带往安全之地。', '取得万能钥匙，解救祖拉蒙达洞穴中的人质。', '', '回到弗里伦中尉处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175054, 'zhCN', '战争真正的野心', '感谢圣光……我以为再也见不到友善的面孔了。$B$B不知我在此藏身了多少天。我设法溜出了牢笼，却没走远。自那以后，我便等待机会了结……他。$B$B阿格拉莫尔。$B$B<那名囚徒神情一沉。>$B$B没错。这群巨魔的首领是个兽人。似乎是部落的一名指挥官。$B$B你与我不同。你能杀他。你必须杀他。$B$B灰空卫兵必须知晓。这场战争背后是部落……', '将阿格拉莫尔的头颅交给弗里伦中尉。', '', '回到弗里伦中尉处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175055, 'zhCN', '瞭望塔中的庇护', '你在里面干得漂亮。胜过我任何一名部下。<弗里伦咂了咂舌，低声补了一句：>换作我自己也未必能做得更好。$B$B你从祖拉蒙达救出的部分人质，已在河对岸的旧瞭望塔中避难。我在此侧重整秩序之际，你去他们那里，确保他们平安。$B$B有一位女祭司与他们在一起。他们称她莎拉。与她交谈。稍加助力，再最后一推，我们或许便能重夺王道之控。', '在旧瞭望塔与莎拉修女取得联系。', '', '与莎拉修女交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175056, 'zhCN', '圣光的暖意', '无论你是否为圣光的信徒，毫无疑问你是它的工具。$B$B你愿与我同作一段简短的祈祷吗？伤者会感激几句慰藉之言。而我相信，你那战士之心也会感激从如此暴行中暂得歇息。$B$B还有最后一件事。你需要暖暖身子。在篝火旁待上一会儿，投几根木柴进去拨旺火焰。$B$B毕竟，在你为斯卡迪尔德所做的一切之后，这是我们所能奉上的微薄之礼……', '向圣光祈祷，为伤者带来慰藉，并投入木柴助燃篝火。', '', '与莎拉修女交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175057, 'zhCN', '闭眼时眼前的野兽', '<尽管篝火温暖，那士兵的腿却仍未停止颤抖。那不是因为寒冷。是恐惧。>$B$B我所隶属的营守卫着卡拉多尔桥。我们挺过了第一次进攻，以及第二次……有那么一阵，我们真心以为能守住防线。$B$B但随后，他来了。$B$B一个高耸的巨魔，比我见过的任何一只都庞大。他骑着一头可怖的野兽。$B$B莎拉修女坚持要我们休息，可每当我闭上眼便看见他的脸与死者的脸，教人如何安眠？$B$B你必须设法杀了他。', '在卡拉多尔桥斩杀升天的阿尔塔津。', '', '回到士兵鲁尔文处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175058, 'zhCN', '卡拉多尔的补给', '莎拉修女的心胸比我们任何人都宽广，但并非所有病痛都能凭祈祷治愈。$B$B我们这里的干净绷带已用尽，消毒酒精昨日也已耗尽。更别提我们如今手无寸铁。$B$B讽刺。我们所需的一切，都在卡拉多尔桥的地窖里。$B$B<鲁尔文咬紧牙关闷哼。他仍未停止颤抖。>$B$B若你能杀出一条路抵达那桥，便把所有你能扛动的箱子带回来：医疗物资、武器、弹药……迟早我们得返回灰天……而全副武装地回去才是上策。', '在卡拉多尔桥内搜集医疗箱、武器与弹药。', '', '回到士兵鲁尔文处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175059, 'zhCN', '操纵霜鬃的那只手', '在你为斯卡迪尔德所做的一切之后……你所倾洒的所有鲜血。你自身所流的每一滴血。我们已不能再多求于你。$B$B回灰天去。去吧。歇息。你会需要你的力气，因为这远未结束。若部落与霜鬃巨魔结盟……这不过是一场更漫长战争的黎明。$B$B直接禀报总指挥德拉温爵士。关乎部落的警告，不可经中间人耽搁。$B$B我确信他会懂得如何嘉奖你在王道立下的功绩。', '将发生的一切禀报德拉温爵士。', '', '向德拉温爵士复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175060, 'zhCN', '悲剧的余烬', '他们在吞食尸体。何等怪诞的景象。$B$B那些食人者……你可见过？他们在饱食我们同类的血肉后，如蜥蜴般再生。甚至连同族。我只在驻守北方时才见过这般光景……$B$B我交付你的任务并不愉快：将尸体点燃；把它们从巨魔的食欲中拯救出来。$B$B拿上这支火把。<乔维克将手按住腹部；他的神情预示着一阵反胃的干呕。>$B$B趁现在，趁风向正对着他们……', '点燃王道周边的人类与巨魔尸体。', '', '向弗里伦中尉复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175061, 'zhCN', '斯凯德恩村', '野蛮的艾尔迪尔，本省之敌、王国之叛徒，已在距城不远之处扎营，盘踞于三姐妹瀑布之上。$b$b他们所谓的斯凯德恩村，是一种不可容忍的挑衅，是对我们和平的直接威胁。$b$b悬赏：$b斯凯德恩酋长的首级，及其艾尔迪尔追随者的歼灭。', '找到斯凯德恩村，消灭艾尔迪尔势力，并将其首领的头颅交给德拉温爵士。', '', '向德拉温爵士复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175062, 'zhCN', '三姐妹的哭号', '<手写命令。你读到如下内容：>$B$B急流渡口是一处地理瓶颈。若那座老桥消失……斯卡迪尔德的广袤土地将脱离暴风城的掌控。$B$B换言之：我们将孤立灰天。$B$B去斯凯德恩村，我的兄弟们，到酋长沙拉赫面前听令。在执行这些命令期间，他会容你们栖身：$B$B唤醒河流。将它在冰之枷锁中释放。唤来一场千年未见之洪流。让整个斯卡迪尔德见证三姐妹的哭号。此乃大地之母之令。$B$B<卡思巴德一人签署此羊皮卷。>', '击败潜伏在斯凯德恩村附近河畔的黑暗德鲁伊。', '', '向灰天的阿尔卡里安复命，他是奥术艺术与科学学院的一员', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175063, 'zhCN', '加尔达恩村', '野蛮的艾尔迪尔，本省之敌、王国之叛徒，已在道摩尔峰的坡地上扎营。$b$b他们称之为加尔达恩村，它对本地区的完整构成直接威胁。$b$b悬赏：$b加尔达恩酋长的首级，及其艾尔迪尔追随者的歼灭。', '找到加尔达恩村，消灭艾尔迪尔势力，并将其首领的头颅交给德拉温爵士。', '', '向德拉温爵士复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175064, 'zhCN', '狮鹫的开胃菜', '你是几周来我见到的第一个人。你该不会是灰天派来的吧？不是？对，不是。$B$B<布罗姆利垂头丧气。>$B$B无论如何，或许你能帮我。道摩尔峰。你知道这意味着什么吗？''道摩尔''在矮人语中意为''野猪''；而我确信你已注意到，它们是这座山上的祸患。$B$B你看就像那种一生宰过许多野猪的人，这任务或许让你觉得''厌''烦。但我的羽翼之友需要填饱肚子，而野猪恰是它们的主要食物来源。$B$B猎杀几头来，好吗？把你扛得动的所有肉都带回来。拜托了！', '从道摩尔峰收集野猪肉。', '', '回到狮鹫管理员布罗姆利处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175065, 'zhCN', '巢与羽', '你介意再帮我一把吗？有时狮鹫会把……''奇特''的物品带回巢中，最好赶在有人受伤前将其清理掉。$B$B既然你已有肉，先扔一大块喂它们填饱肚子、安静下来。之后你才可靠近那些巢。$B$B噢！若你找到任何掉落的羽毛，别随手丢进垃圾堆；它们的用途超乎你想象。把你找到的都带给我！', '清理道摩尔峰的狮鹫巢，收集掉落的羽毛。', '', '回到狮鹫管理员布罗姆利处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175066, 'zhCN', '乘达恩之翼', '哎。我想是的。有何不可？毕竟，你已为我们立下大功。你值得一份像样的奖赏。$B$B告诉我，你可愿乘于狮鹫之背翱翔？$B$B时机已到！而我心中恰有一只完美的狮鹫。亲切。温顺。但好奇。自从你这张新面孔出现在此，他便对你颇有好感。我料他想必会让你骑上去。', '在道摩尔峰骑上狮鹫达恩，飞越斯卡迪尔德。', '', '回到布罗姆利处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175067, 'zhCN', '她的阴郁之日', '她常在我的祈祷中。拉尔达，那可怜的女人……你听到那哀号了吗？定是那些日子之一。她的阴郁之日。暗影井的水流有一半是她的泪水。$B$B此症无药可医；失去女儿……违背常理。更糟的是，在她女儿出事后不久，他们便将她丈夫派驻风拂哨塔，日夜守望。而她，如此孤寂……$B$B你愿行个方便吗？你能带些吃食给她吗？她从没有胃口，可怜的人儿，有时竟全然忘了进食。$B$B她住在山脚下、湖岸边的那座孤屋里。', '在暗影井湖畔孤屋与拉尔达交谈。', '', '与拉尔达交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175068, 'zhCN', '以鱼人之血偿的代价', '是鱼人干的，你知道吗？他们掳走了我的小多萝西！$B$B''它们从不会上到这么高，''他们告诉我。''它们从未给我们惹过麻烦。''去他的信任！那些怪物夺走了我的女儿，只因镇上没一人认为它们会是威胁。$B$B但你是外地人。那你便懂得这世界如何运转。你已摘下了眼罩。$B$B我也一样。<拉尔达说到此处声音哽咽。>$B$B求你。下到瀑布去，能杀多少鱼人就杀多少。也许……也许你会找到多萝西？', '杀死9名暗影井鱼人战士与5名暗影井鱼人预言者。', '', '回到拉尔达处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175069, 'zhCN', '他们抓住了她的脚踝', '多萝西在岸边玩耍时失踪了。我总警告她要小心……总是。总是。$B$B可一次疏忽便已足够……有什么东西从水中涌出。他们抓住了她的脚踝。将她拖向瀑布，然后……$B$B<拉尔达战栗不已。>$B$B我不愿去想象她此刻是何感受……被囚、迷失、孤独。$B$B求你，寻找任何能表明鱼人将她带往何处的线索。', '在暗影井瀑布寻找有关多萝西下落的线索。', '', '回到拉尔达处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175070, 'zhCN', '以狗头人之血偿的代价', '若多萝西不在鱼人那里，那会是谁带走了……？$B$B<拉尔达拭去眼泪，眼中骤然燃起决然之火。>$B$B狗头人……！当然，定是它们。它们把我的小宝贝锁了起来，在暗处凿石或点烛。$B$B我女儿乖巧。非常、非常乖巧，且听话。它们不会甘愿放她走。我们得逼它们。$B$B它们住在附近一处洞穴里。我见过！扯下它们的尾巴。它们的须。它们肮脏的脑袋。把它们全杀了。一个不留！', '应对暗影井周边的狗头人威胁。', '', '回到拉尔达处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175071, 'zhCN', '狗头人带走了她', '<拉尔达湿润的目光泄露出一连串狂乱炽热的思绪。>$B$B村里的父母，我们总吓唬自家孩子……我们说，若不听话，狗头人便会把他们带走凿石头作为惩罚……$B$B或许我丈夫对我女儿也这么说过。或许，那便是他不再来此的缘由……$B$B<拉尔达从恍惚中惊醒，转向你。>$B$B狗头人带走了她。我确信无疑。$B$B深入它们的洞穴，寻找任何能表明他们将她囚于何处的线索。快。求你了！', '在暗影井洞穴内寻找有关多萝西下落的线索。', '', '回到拉尔达处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175072, 'zhCN', '那怪物，我的丈夫', '多萝西的父亲……罗特弗斯。$B$B他会不会将她带去了那座被诅咒的塔？当然，他想将我隔绝在女儿之外……他是个比鱼人和狗头人更可怕的怪物！我竟如此盲目。何等盲目……！$B$B<说话间，她攥紧双拳，直至指节发白。>$B$B去风拂哨塔找他。逼他说出他把她藏在哪里。告诉他把她还给我……$B$B<痛苦与愤怒扼住了她的声音。>$B$B我不在乎他。我只想要回女儿。我只想要回多萝西……', '在风拂哨塔与多萝西的父亲罗特弗斯当面对质。', '', '与罗特弗斯交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175073, 'zhCN', '灰天的奶酪拼盘', '你大概已注意到，若说我的酒馆里有什么让人百吃不厌，那便是风拂出产的奶酪。可照这被吞食的速度，我转眼便会断货。$b$b平日里，我会派侄子再去添些，但眼下斯卡迪尔德这般光景……何况暗影井又那么远！$b$b而你么……<多尔克雷斯特上下打量你，点了点头。>你的旅程磨炼了你。你由更坚韧的材料铸成。$b$b去暗影井，找到大奶酪师阿尔莫，订购一精挑细选的奶酪拼盘。我自会重金酬谢，毋庸置疑。', '在暗影井村与大奶酪师阿尔莫交谈。', '', '在暗影井村与大奶酪师阿尔莫交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175074, 'zhCN', '风拂牛奶', '暗影井的奶酪并非凭魔法凭空出现。你可曾有机会造访风拂那美丽的草甸？$B$B我们的牛在峰顶吃草。那是本地品种，自由徜徉于王国最肥沃的草场之中。除此之外别无秘诀！$B$B眼下，几头牛正等着挤奶。遗憾的是，村里已无多少闲手；许多人被征召去守护安德拉斯特堡垒、抵御黑石兽人，其余人则舍生守护王道、抵御巨魔。$B$B你愿帮我吗？我只需你装满几桶牛奶。我自会厚报！', '用桶装满风拂奶牛产下的新鲜牛奶。', '', '回到大奶酪师阿尔莫处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175075, 'zhCN', '风拂霉', '除牛奶外，还有一味材料令我的奶酪如此特别。$B$B霉菌！$B$B缺了它，那奶油般的质地、香气、风味……一切都会毁于一旦。这是个漫长的过程，相信我，需要耐心与极大的巧思。不过，我身为大奶酪师，自有其道理。$B$B况且，非任意霉菌皆可。我需要生长于某一特定洞穴中的那种。我会在你的地图上标出。$B$B你愿意去那里采集一些吗？', '从风拂洞穴采集新鲜霉菌。', '', '回到大奶酪师阿尔莫处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175076, 'zhCN', '剪毛而归', '哎呀！你好啊，年轻的$Gman:woman;！你可见过这些美人儿？这些羊正待修剪！$B$B愿搭把手吗？$B$B给。拿上剪刀，卷起袖子，拼命剪起来吧。剪完了把羊毛带给我，别担心，我不会亏待你！这些羊的羊毛价值连城；还是说，你以为只有它们的奶才值钱？', '修剪风拂绵羊，收集成捆羊毛。', '', '回到牧场主马塞兰·帕斯托雷处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175077, 'zhCN', '风拂头狼', '你已对这群羊生出感情了，是吧？$B$B它们每一只都有名字。而我从不忘记任何一只；即便早已不在的那些，名字我也记得……$B$B我们风拂的牧场主向来将狼挡在门外，但近来它们成了真正的麻烦。$B$B而因它们的饥饿，我已失去了太多羊。$B$B杀了狼群的头狼，顺带再除掉几只狼。没了首领、数量又减，余者再回来前必会三思。你说呢？', '杀死高风狼群及其头狼天噬。', '', '回到马塞兰·帕斯托雷处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175078, 'zhCN', '阿拉塞尔的营地', '沿下山之路而行，你会找到安德拉斯特堡垒。它受黑石兽人围困已有些时日。$B$B你既已走到此处，必是那种总在寻找事做的人。那好；这塔中并无多少动静，但地下室通向一处洞穴，那洞穴在堤岸脚下豁然开朗。$B$B我们数名弟兄已在下方扎营。他们正准备突袭围困堡垒的黑石兽人后方。$B$B去见阿拉塞尔。我确信他必有任务交予你。', '拜访位于塔脚、堤岸处的阿拉塞尔营地。', '', '与阿拉塞尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175079, 'zhCN', '宽厚慷慨的脊背', '敌军——若''军队''一词当真适用——并未料到会遭背后袭击。他们最精锐的战士都在前线，与堡垒守军缠斗不休。$B$B你可明白这意味着什么？这意味着出手之时已至。$B$B你面带不耐，而你既已至此，必是渴望一战。告诉我，你可愿领军冲锋？$B$B砍倒数名黑石士兵。余者由我与我的部下料理。你完成之后，向摩尔指挥官复命。', '从后方击败围困安德拉斯特堡垒的黑石兽人战士。', '', '在安德拉斯特堡垒向摩尔指挥官复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175080, 'zhCN', '黑石投石机', '兽人科技虽粗陋，投石机终究是投石机。而一颗够大够快的石头，所能造成的破坏不亚于火炮。$B$B我们得除掉它们。$B$B给。炸药。靠近时置于其底座，将那几台家伙炸上云霄。你完成之后，向摩尔指挥官复命。', '摧毁黑石兽人的攻城器械。', '', '在安德拉斯特堡垒向摩尔指挥官复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175081, 'zhCN', '胜利者的饥饿', '也许是我算错了，我需要你的帮助来纠正这个错误。$B$B我们的狩猎大师凯瑟里克·萨德森，无法及时填饱要塞里众人的肚子。而在这样一场战斗之后，我的部下需要的可不止是一碗寡淡的蔬菜汤来维持体力。$B$B去林子里找到凯瑟里克，尽你所能协助他。仅仅是来到这座堡垒、站到我面前，你就已经比大多数人更有勇气了。我相信你是完成这项任务的合适人选。$B$B去吧。', '在附近的林地中寻找安德拉斯特要塞的狩猎大师凯瑟里克·萨德森。', '', '与凯瑟里克·萨德森交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175082, 'zhCN', '牦牛狩猎', '首先，我们必须弄到足够的肉。对我们来说幸运的是，大自然会提供。$B$B<凯瑟里克做出一个夸张的手势，仿佛在指向周围的树林。>$B$B每年这个时候，牦牛会从瓦尔弗罗斯特丘陵下来寻找食物和水。尽管对邓卡扎德的矮人来说这是个痛处，但它们的肉滋补之力无与伦比。而我们正处于战争之中。$B$B猎杀几头，把肉带给我。我们比它们更需要这些肉。', '从扭曲丘陵的森林中采集牦牛肉，用来喂养要塞的士兵。', '', '返回凯瑟里克处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175083, 'zhCN', '莫向精灵问计', '看着你抱着胳膊站在那儿，而我却在准备口粮，这让我很不舒服。最后再跑一趟怎么样？$B$B泉之精灵就在附近；非常得体，非常热忱，但别搞错了：他们的善意是一面盾牌，他们的谨慎则是远离我们麻烦的借口。$B$B也许你比我更能从他们那儿讨到好。$B$B去拜访他们，好吗？为我们伤员讨些他们珍视的泉水中的附魔之水。他们以狂热的虔诚守护着那个地方，但他们早该像我们其余人一样出力了。', '在泉边找到高等精灵，并取得一批附魔之水。', '', '与萨纳德里尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175084, 'zhCN', '泉水双耳瓶', '这泉中的水，是我们极少与外圣所之人分享的礼物。$B$B<萨纳德里尔的眼神警惕了片刻，随后露出微笑。>$B$B但你们的事业是高尚的。在安德拉斯特流淌的鲜血与汗水，维系着我们山谷的和平；我们理应施以援手。$B$B带上双耳瓶，将自己浸入水中。守护泉水的灵魂会反抗；他一向如此，这脾气暴躁的老家伙。你将不得不……安抚他。', '用附魔之水注满双耳瓶，击败泉水的守护之魂，并将其带回安德拉斯特要塞治疗伤兵。', '', '向摩尔指挥官汇报', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175085, 'zhCN', '严厉的一课', '前些天夜里，一支士兵队伍从北郡、闪金镇和湖畔镇抵达。这本该是好消息，只可惜「士兵」这个词用在他们身上如此不妥。$B$B他们几乎没有任何战斗经验。$B$B去和他们谈谈，帮他们训练。他们有干劲，这已胜过大多数人，但他们需要一点务实精神。$B$B我是说，来一场痛快打斗。把那些不切实际的想法直接从他们脑子里打出去。', '向安德拉斯特要塞中新抵达的新兵发起决斗挑战。', '', '与摩尔指挥官交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175086, 'zhCN', '凯雷博尔的阴影', '你对我们的敌人了解多少？$B$B我们面对的兽人打着黑石的旗号，但我相信他们听命于自己的督军。或许是个反叛者，而且是个闹腾的反叛者。$B$B我已经数不清我们承受了多少次攻击。是时候把战争推向兽人了。$B$B找到我们部署在他们堡垒附近的军情七处特工。阿伦多尔会向你提供行动的详细情况。', '在凯雷博尔堡垒的外围找到军情七处特工。', '', '与阿伦多尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175087, 'zhCN', '凯雷博尔三恶', '<阿伦多尔最后环顾四周，咬着牙继续说道。>$B$B凯雷博尔。曾是人类要塞。如今，是兽人滋生的鼠洞。我们跟踪他们已有数日，并已铲除数名关键目标；上次对安德拉斯特的围攻就是他们的报复。$B$B但如果你想帮军情七处，凯雷博尔还有活要干。我这儿有一份名单：$B$B威弗尔，马厩管理员。$B$B屠夫艾戈尔，在瞭望塔处。$B$B术士卡雷戈尔，在堡垒后方。$B$B完成之后，向桥对面的萨玛拉汇报。', '潜入凯雷博尔堡垒，铲除马厩管理员威弗尔、屠夫艾戈尔和术士卡雷戈尔。', '', '向桥对面的萨玛拉汇报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175088, 'zhCN', '凯雷博尔的黏合剂', '兽人的军事策略通常可以概括为「去杀」，但他们的领袖库尔甘勇士所起的作用，远不止发号施令：他是把其余人粘合在一起的胶水。$B$B我们对他研究得很透彻。此时此刻，他应该待在指挥室里。多半独自一人。$B$B别让这杀他的机会溜走。哦！还有，记住，我们是军情七处；收集你找到的任何详述他们营级计划的文件。$B$B把它们交给桥对面的萨玛拉。', '在凯雷博尔堡垒的指挥室中杀死黑石勇士库尔甘。', '', '将黑石计划交给桥对面的萨玛拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175089, 'zhCN', '暗影井伏击', '该死。$B$B我们怀疑库尔甘是在听从他人的命令，这些文件证实了这一点。我们低估了敌人。$B$B库尔甘的目标是制造尽可能大的动静；在围攻安德拉斯特要塞的同时，另一支队伍正穿过暗影井，向艾尔文开辟道路。$B$B伏击者。他们会像刽子手的斧头一样，先扑向北郡，再扑向闪金镇。$B$B我们必须趁为时未晚，削减他们的数量。', '击败潜伏在暗影井中的黑石伏击者。', '', '向萨玛拉回报', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175090, 'zhCN', '及时避免悲剧', '就像他们本就是蟑螂一样，无论我们消灭多少兽人，都会有更多的取而代之。$B$B无论如何，胜利就是胜利，无论多么微小。$B$B返回安德拉斯特。向指挥官汇报。我会在桥的这一侧完成工作。', '返回安德拉斯特要塞，找到摩尔指挥官。', '', '向摩尔指挥官汇报', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175091, 'zhCN', '号角吹响之时', '你好。打扰一下。我是萨芙琳娜；我是要塞里两名文书之一。我的同事是个名叫达尔温的矮人。兽人进攻时，他出去查看城墙外的废墟了。$B$B而他还没回来。$B$B这里每个人都忙得不可开交，再加上外面那些黑石攻城器械……我知道现在不是去找他的好时机，但是……如果你能，如果你不介意的话……求你了！$B$B把达尔温平安地带回来给我。', '在要塞城墙外的废墟中找到达尔温。', '', '与达尔温交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175092, 'zhCN', '黑铁矮人', '听着。我知道黑石兽人是眼前的威胁，但他们不会是安德拉斯特长期面临的唯一问题。$B$B我说的是黑铁矮人。$B$B我不知道他们在搞什么名堂，但他们以前从未冒险靠得这么近。而且……嗯，看看你周围吧。$B$B兽人是可怕的敌人，但这座火山，这一切毁灭……都是黑铁矮人的手笔。$B$B想象一下他们能做什么。', '击败安德拉斯特要塞附近的黑铁矮人，揭开他们的计划。收集他们的笔记，然后拼合起来以破译其计划。', '', '返回达尔温处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175093, 'zhCN', '通知参议员', '他们是狂热者。一个邪教。从你带给我的文件中我了解到，他们怀有危险的思想。$B$B他们寻求以暗影束缚火焰。这就像往篝火里添更多木柴来试图熄灭它一样！$B$B我们必须敲响警钟。必须警告摩尔指挥官；不，我在说什么？必须警告铁炉堡和邓卡扎德的矮人！$B$B直接去铁炉堡。我会和萨芙琳娜返回要塞，向摩尔指挥官说明我们发现的一切，以便消息能送达邓卡扎德领主。', '通知铁炉堡的参议员巴林·红石。', '', '在铁炉堡与参议员巴林·红石交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175094, 'zhCN', '潜伏林中的危险', '朋友，我未曾见过你的面容。你选择在黑暗的时期来访，但或许这并非巧合。$B$B我在你眼中看到了战火。这个词直到最近才在这山谷中有一席之地。但现在，我们需要你这样的人。$B$B我亲爱的朋友梅瑞迪尔·阳心，出发去山谷采集药草，此刻本该已经返回。近来山谷充满了危险，我担心那些因我们尚不知晓的原因而失去理智的树人，可能袭击了她。$B$B你能去寻找梅瑞迪尔吗？你愿意为我们做这件事吗？', '在鎏金谷中找到梅瑞迪尔·阳心，确保她的安全。', '', '与梅瑞迪尔·阳心交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175095, 'zhCN', '贝洛利特精灵', '我正在河边采集药草。这个山谷一直是和平的避风港；在死亡与战争的汪洋中一座平静的小岛。精灵们通常爱玩闹，顶多淘气。但从不暴力。$B$B我现在这副样子无法采集剩下的药草。你愿意帮我吗？$B$B我需要的草药只长在这个山谷。是我亲自命名的：贝洛利特。给我带一大把来；我需要相当多才能治愈伤口中的毒，并踏上返回圣所的旅程。', '在鎏金谷中为梅瑞迪尔·阳心采集贝洛利特花。', '', '返回梅瑞迪尔·阳心处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175096, 'zhCN', '难以平息的愤怒', '鎏金谷。在我们的语言中，我们另称它为：能阿拉。$B$B<阿玛兰忒深吸一口从白色山峰吐出的清新空气。>$B$B它的美丽是一场幻象：森林正在躁动，不安。某种东西在其核心处黑暗下去。曾友好的树人，已变得暴力而具侵略性。而我的心告诉我，这仅仅是开始。$B$B如果你愿意帮忙，就深入林中，协助我们安抚在道路上徘徊的狂怒树人。然后，去寻找考拉诺斯，林地的守护者。他睿智而可敬；若有人能辨认出折磨森林的病症，那便是他。', '使用纳马里恩水晶安抚狂怒树人，然后找到考拉诺斯。', '', '与林地的守护者考拉诺斯交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175097, 'zhCN', '唯以性命方能偿还的债', '只要血精灵继续榨取林中的活力，这个山谷就永无宁日。而其生灵将被恶意填满。别无他法。$B$B有时，确保和平的唯一途径便是流血。我绝不会向圣所的精灵提出这种要求，但你……你与他们不同。你习惯了暴力。$B$B我直说了吧：森林要求魔导师们死。他们欠下了一笔唯以性命方能偿还的债……以及摧毁他们的水晶。', '在鎏金谷中杀死血精灵魔导师，并摧毁他们的恶魔水晶。', '', '返回林地的守护者考拉诺斯处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175098, 'zhCN', '献给树妖的琥珀', '最早回应森林召唤的，是树妖。她们如山上落雪般扑向魔导师，却不是其淫秽法术的对手。$B$B许多死去，但有些仅剩一丝生命得以逃脱。我已尽了所能治疗，但我的力量不足以救助她们所有人。$B$B拿去。<这位巨大的守护者递给你一件水晶般的物体，形似一滴琥珀。>用它来治疗你找到的受伤树妖。它会引导森林活力的一小部分；足以让死神之鹫无从下手。', '使用德鲁伊琥珀治疗鎏金谷中受伤的树妖。', '', '返回林地的守护者考拉诺斯处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175099, 'zhCN', '一切皆为障眼法', '假以时日，血精灵留下的创伤会结疤，森林将回归和平与沉思般的宁静。$B$B但是……我怀疑这一切不过是个障眼法。魔导师们一直鲁莽、冲动。这颇不符合他们的本性。$B$B你看：这片森林不只是森林。树木在地下紧握双手；数千年来，它们编织的网络一直将沉睡于这片土地之下的黑暗隔绝开来。$B$B去吧，与阿玛兰忒女爵谈谈。解释一切，并把我的担忧告诉她。', '返回阿玛兰忒·奈米尔女爵处，警告她森林深处的威胁。', '', '在圣所与阿玛兰忒·奈米尔女爵交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175100, 'zhCN', '厄达娅密室', '厄达娅密室是亘古之前由尘埃不如的双手开凿的。它们如迷宫般在森林之下延伸；事实上，它们不过是一个更为庞大的泰坦建筑群的表层。$B$B一座关押着不可言说之黑暗生灵的监狱。$B$B圣所脚下的湖泊隐藏着唯一的入口。我们需要你的帮助。若血精灵不惜冒此大险，那是因为他们的野心同样宏大。他们没安好心。$B$B找到被淹没的入口，冒险进入厄达娅密室。', '潜入圣所下的湖泊，找到被水淹没的入口，进入厄达娅密室。', '', '在密室中找到幸存者', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175101, 'zhCN', '使馆内的邪教', '仔细听我说。$B$B<黑暗游侠以呻吟和喘息之声说话。她时日无多。>$B$B那些疯子……我不知道他们图谋什么，也不需要知道。必须阻止他们。$B$B<她咬紧牙关。她的双眼如两颗残忍的宝石般燃烧。>$B$B若有力量，我本想亲自对付他们。必须有人让他们为自己的罪行付出代价。他们背叛了部落。他们的王国。他们杀光了营地里所有人。使节。他的助手们。护卫。全死了……$B$B我说，以眼还眼。趁为时未晚，杀光他们。', '在厄达娅密室中杀死「家族」的邪教徒。', '', '返回受伤的埃尼莉丝·奈米尔处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175102, 'zhCN', '邪教族长', '这帮乌合之众的头目是个名叫萨里昂的人。我仍难以置信；几天前，他还伪装成另一个文书。那是他的掩护。$B$B他究竟在策划什么并不重要。必须阻止他。若换作其他情形，我会亲自加入追猎。我会确保活捉他，折磨他以榨出每一点信息。$B$B但我们没有时间。$B$B杀了他便足矣。$B$B不过……让他受苦。', '在厄达娅密室深处面对族长萨里昂，了结他的疯狂。', '', '在圣所返回阿玛兰忒·奈米尔女爵处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175103, 'zhCN', '新生的祝福之种', '把你带到这里的事，那降临在人类的村庄矿工身上的诅咒，我并未忘记。$B$B山谷在愈合，我的力量在增长。你给予我们的帮助超出你的想象。我回报以恩惠是理所应当的。$B$B收下这份礼物。$B$B<精灵将一粒形似金块的种子放入你手中。>$B$B这是我故乡奎尔萨拉斯的纪念；一朵曾生长在现已失落之太阳之井旁的花的种子，它仍保留着光芒。把它交给矿工们；告诉他们把它埋在矿洞附近。$B$B当它绽放时，诅咒便会消退。', '将受祝福的金色种子带给采矿村的阿尔托·比尔伯格，并把它种在矿洞附近。', '', '与阿尔托·比尔伯格交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175104, 'zhCN', '我们从林中所取', '太阳之井陨落之后的魔法饥渴，是一种可怕的命运。血精灵采取了绝望的手段；在我们看来，那是道德上的错误。我们，高等精灵……嗯，我们开发了无数的补救之法。$B$B对一些人而言，答案在于冥想与自律。对另一些人而言，解决之道在于与森林的共生关系。$B$B这是一片特殊的森林，你知道吗？一股力量从其中散发，包裹并振奋灵魂。我们从不索取超过森林自由给予之物；我仅限于从落到地上的松果中提取魔法。$B$B如果你在树间漫步，请采几颗松果带给我。', '在鎏金谷的林地上采集附魔松果，带给塞莱多恩。', '', '在圣所返回塞莱多恩处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175105, 'zhCN', '塞莱多恩的面包', '给。看好了。$B$B<塞莱多恩用双手操控一缕能量火花。片刻之后，他将那能量倾注在桌上的面包上。>$B$B只需一口，便足以安抚灵魂，并为某人注入新生的活力。当然，也能在更实在的意义上充饥。$B$B你能否好心将它分发给圣所的居民？', '将塞莱多恩的附魔面包分发给纳马里恩圣所的居民。', '', '返回塞莱多恩处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175106, 'zhCN', '桥下的敌人', '你和其他人不一样。我是说，和这个圣所的精灵不一样。$B$B我来自灰天。一项官方任务，由德雷温爵士亲自签署。或许你能帮忙？$B$B近来，我们得知有一处艾尔迪尔营地位于圣所以北、卡拉多桥下。艾尔迪尔是祸害，考虑到灰天正面临巨魔的麻烦，他们只会让事情更棘手。$B$B扫清营地，好吗？你知道「扫清」是什么意思，对吧？$B$B报酬会物有所值。', '扫清位于圣所以北、卡拉多桥下的艾尔迪尔营地。', '', '在圣所返回丹多尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175107, 'zhCN', '裂岩的厄运', '<德雷温爵士点头向你致意。然后，他指向桌上的一叠文件。>$B$B报告。你的名字出现在大部分报告中。你赢得了我的尊敬。甚至我的信任。$B$B我还有最后一项任务给你。$B$B<德雷温爵士压低声音。>$B$B几天前，裂岩村惨遭艾尔迪尔残忍袭击。我们在调查此事，但他们似乎没留下活口。我要你前往现场，做我在该地区的眼线。$B$B向游侠桑德尔报到。尽你所能帮助他。', '前往裂岩的废墟，向游侠桑德尔报到，调查艾尔迪尔袭击。', '', '在裂岩与游侠桑德尔交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175108, 'zhCN', '逃亡者', '村庄已成鬼城。我的士兵？被屠宰了。但住在这里的人们……啊，问题就在这儿。他们怎么样了？$B$B我来告诉你我的看法：艾尔迪尔尽可能多地掳走了人。目的何在，我不知道，但我的部下发现了一条通往矿洞的踪迹。我怀疑不止一个灵魂在艾尔迪尔敲门时，试图躲进那些隧道。$B$B仔细搜查。从上到下。每条矿脉、每个竖井、每个被神遗弃的裂隙。我拿我的胡子打赌，里面一定还有幸存者。', '在矿洞深处搜寻可能在艾尔迪尔屠杀中幸存的村民。', '', '与梅芙交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175109, 'zhCN', '矿洞中的阴影', '通往矿洞的踪迹是单向的；换言之，进去的人从未出来。$B$B幸存者？那是我的希望。但他们被猎杀，这一点我确信无疑。而且在我看来，紧咬他们脚跟的那些生物，仍在那些隧道中游荡。$B$B我不知道你会在里面发现什么，但要做最坏的打算。无论什么挡你的路……把它送进地狱。', '调查矿洞寻找幸存者，并消灭你遇到的任何威胁。', '', '与梅芙交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175110, 'zhCN', '那个宿命之夜', '我……我希望我能提供更多帮助。艾尔迪尔在夜间来袭。他们如山间岩崩般扑向我们。他们带走了所有人。到处是尖叫。他们屠杀了士兵。还有一些村民……$B$B我无暇思考。我只是跑。我尽力地、尽快地跑。其他人跟在我身后。然后那些生物就扑向了我们。$B$B但他们不敢深入矿洞这么深。他们不敢跟到这么远。$B$B艾尔迪尔在策划什么。什么大事。否则，他们不会费如此周折把我们活捉。', '向桑德尔报告矿洞中发生的事。', '', '与桑德尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175111, 'zhCN', '劳瑞琳与特尔珀里安', '现在不是失去希望的时候。如果艾尔迪尔需要这些人活着，那我们就还有时间。我们仍能行动。$B$B我会确保这情报送达灰天。但当我的部下完成对村庄的侦察时，我要你出发去找劳瑞琳与特尔珀里安的营地。$B$B他们是我们最出色的。和我一样，他们受命调查裂岩的失踪事件，但他们更深入了林中。我敢打赌，此刻他们已有了有用的发现。$B$B我会在你的地图上标出他们的位置。', '在林中找到劳瑞琳与特尔珀里安的营地。', '', '与劳瑞琳交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175112, 'zhCN', '布雷卡格高地的艾尔迪尔', '这片区域，斯卡迪尔德古冢荒野，是艾尔迪尔领地的核心。他们的村庄仍遥不可及，但要开辟通往他们的道路，我们必须先对付在布雷卡格高地游荡的艾尔迪尔。$B$B少一个艾尔迪尔，就少一个需要担忧的敌人。$B$B沿着蜿蜒上山的小径走，削减他们的数量。为了灰天！为了斯卡迪尔德！以及所有那些人。', '击败布雷卡格高地的艾尔迪尔。', '', '返回劳瑞琳处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175113, 'zhCN', '布雷卡格高地瞭望塔', '尽管艾尔迪尔比任何人都熟悉这些树林，但如果没有驻扎在布雷卡格高地瞭望塔的哨兵，他们无法守住古冢荒野的边界。$B$B如果有人，比如说，把那座塔炸个粉碎……我们其余人推进艾尔迪尔领地、处理剩下的事就会容易得多。$B$B我说「有人」，但显然，我想的是你。$B$B带上这些炸药。把它们安放在塔基处。并在它们爆炸前，用你双腿能跑多快就多快逃开。', '使用劳瑞琳的炸药摧毁布雷卡格高地瞭望塔。', '', '在营地向劳瑞琳回报', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175114, 'zhCN', '酋长赛达尔恩', '据特尔珀里安与我所收集到的，布雷卡格高地的艾尔迪尔听命于一个名叫赛达尔恩酋长的暴君。$B$B对赢得了德雷温爵士尊敬的人而言，杀几个艾尔迪尔算不上多大挑战；炸掉一座瞭望塔也算不上。然而，击败古冢荒野中最血腥的领袖之一……对，那似乎更合你的节拍。$B$B杀死酋长赛达尔恩。他的死会给所有追随他的艾尔迪尔，以及其他部族的酋长，传递一个明确的讯息。', '在布雷卡格高地击败酋长赛达尔恩', '', '将酋长赛达尔恩的死讯告知劳瑞琳。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175115, 'zhCN', '艾尔迪尔符文', '桑德尔。裂岩。是的，我全听说了。$B$B既然你已在此，我需要一些协助：艾尔迪尔所施的魔法，与我们卡多雷数千年来所修的德鲁伊之道有许多共通。然而，艾尔迪尔掺入了一种黑暗元素；一个打破自然和谐的不谐之音。$B$B我必须研究它，理解它。从他们的符文开始。$B$B在凯尔峭岩村附近，大地裂成一道峡谷，艾尔迪尔在那里雕刻了众多独石柱。找到并带给我那些刻有符文的卵石，以便我研究它们散发的魔法。', '从凯尔峭岩附近的独石柱上收集符文卵石。', '', '将符文石送到特尔珀里安的营地。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175116, 'zhCN', '我梦魇中的女巫', '在我们位置的东南方向，深藏于森林深处岩隙间的，是艾尔迪尔村落凯尔峭岩，女巫巴加·达尔玛的家园。$B$B我与它（她）的魔法缠斗已有些时日。她派出害虫、诅咒和阴影来折磨我们。我尽我所能地防御，祈求森林的力量与女神的保护。$B$B你的援助可能让天平向我们倾斜。$B$B寻找凯尔峭岩，找到巴加·达尔玛。你很可能会发现她已被其邪恶法术吞噬。利用这一点；出其不意地袭击她，结束她可悲的存在。', '在凯尔峭岩村找到并击败女巫巴加·达尔玛。', '', '在营地向特尔珀里安回报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175117, 'zhCN', '巴伊莱·埃斯卡达的艾尔迪尔', '随着布雷卡格高地的艾尔迪尔溃败、其酋长伏诛、凯尔峭岩的女巫被斩，通往古冢荒野主村巴伊莱·埃斯卡达的道路已经敞开。$B$B仔细听好：$B$B若有一处你可能揭开艾尔迪尔如何处置裂岩俘虏的地方，那便是那里。$B$B我亲自用变形咒为这护符施了法。激活它，它会将你变成一只猫，让你能溜进巴伊莱·埃斯卡达，在其居民中潜行而不引人生疑。尽可能了解他们的图谋。最重要的是，查出他们对被掳者有何打算。', '使用特尔珀里安的猫形护符潜入巴伊莱·埃斯卡达，揭开艾尔迪尔的计划。', '', '找到黛德丽', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175118, 'zhCN', '一名叛逃的女巫', '当裂岩发生之事的传言传入我耳中时，我就知道冲突迟早会敲响巴伊莱·埃斯卡达的大门。因为你是为了查探那些绑架而来，不是吗？$B$B是的，我知道裂岩的人被关在哪里。我也确切知道我的同族打算如何处置他们。$B$B仔细听，亲爱的；也许你还来得及拯救他们。', '与黛德丽交谈，探明裂岩人民的命运。', '', '与黛德丽交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175119, 'zhCN', '莫格温娜的寂静者', '艾尔迪尔出于习惯与恐惧追随莫格温娜。但如果有人能证明她的魔法并非无懈可击，这或许会改变。$B$B在巴伊莱·埃斯卡达附近、我们上方的小山上，莫格温娜留下了她的一些「寂静者」；那些因不服从而被变成无脑傀儡的艾尔迪尔。$B$B直面他们。击碎他们的面具，打破禁锢他们的魔法。他们的解放，将如同山中引发雪崩的落石。', '在巴伊莱·埃斯卡达上方的小山上击碎莫格温娜的「寂静者」的面具，解放他们。', '', '将艾尔迪尔获解放之事告知黛德丽。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175120, 'zhCN', '大雄鹿的祝福', '要抵御守护莫格温娜小屋的魔法，我们需要两样东西：$B$B<黛德丽将一枚骨制护符放入你手中。>$B$B这个。以及大雄鹿的祝福。$B$B大雄鹿曾是莫格温娜的守护神，但她早已背弃他的教派，转而信奉扎根之影。$B$B前往山顶他的祭坛，向图腾致以敬意。鉴于莫格温娜对他所做之事，我怀疑大雄鹿之魂会十分乐意赐予我们眷顾。', '前往大雄鹿祭坛，献上骨制护符以获得他的祝福。', '', '返回黛德丽的小屋。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175121, 'zhCN', '车之死', '我开始反咒所需的一切都齐了，但是……啊，总有「但是」，不是吗？$B$B我们必须先平衡天平。我违抗大母亲冒了很大风险；在我们继续之前，我也要你做出牺牲。$B$B以命抵命。莫格温娜换瑟蕾妮娅·冷湖。$B$B只要她们任何一方还在呼吸，艾尔迪尔与灰天之间就无和平可言。别告诉我你很惊讶！和平之树必须用鲜血浇灌。$B$B拿上这毒药。把它送到城堡厨房的哈格隆德·多萝特手中。他是我们的一名特工。就这样。没有别的。就这么简单。', '将黛德丽的毒药送到灰天城堡厨房的哈格隆德·多萝特手中。', '', '在灰天城堡中找到厨师哈格隆德·多萝特', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175122, 'zhCN', '瑟蕾妮娅的最后一口', '<哈格隆德·多萝特用一把巨大的刀切下一大块新鲜烤面包。然后他将黛德丽给你的毒药倒入一只倒了一半酒的酒杯。>$B$B给。拿去给她。并确保她吞下最后一滴。效果应该近乎瞬间；先是困倦，然后是迷惑，最后是一种深沉的倦怠。几小时之内，她就会死去。$B$B而斯卡迪尔德将获自由。或者，至少我们是这样被教导的……', '将下过毒的茶点送给在私人寝宫的瑟蕾妮娅女爵。', '', '与瑟蕾妮娅女爵交谈，等待毒药生效', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175123, 'zhCN', '死后的忏悔', '我该叫卫兵吗？我本可以处决你，而这座城里没有一个人会眨一下眼。$B$B但我不会这么做。安心吧。我知道你为何而来，也知道你为何选择做你所做之事。请坐。放松。$B$B我只想……谈谈。', '聆听瑟蕾妮娅·冷湖女爵的忏悔。', '', '与瑟蕾妮娅女爵交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175124, 'zhCN', '那场未能成行的刺杀', '拿走我的戒指。把它带给黛德丽，作为我离世的证明。尽管这消息迟早会以某种方式传入她耳中。$B$B我会等你离开，然后保持极度的静止。下一个进入这些房间的人，将只看到一具尸体。$B$B会举行弥撒。我会下葬。然后，我对斯卡迪尔德的承诺便告期满，我将自由地在真正的死亡……或走一条属于自己的道路之间选择。', '将瑟蕾妮娅女爵的戒指带给巴伊莱·埃斯卡达的黛德丽。', '', '向黛德丽报告瑟蕾妮娅女爵的死讯', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175125, 'zhCN', '女巫之母的魔法书', '当你在照料瑟蕾妮娅时，我一直在苦苦钻研反咒。这并不容易，但有了护符和大雄鹿的祝福，我相信我已找到穿透守护莫格温娜小屋的魔法屏障的方法。$B$B给。$B$B<黛德丽归还了她先前给你的护符，但它变了。触感不同；从骨中散发的能量令人沉醉。>$B$B必要时把小屋翻个底朝天。那本魔法书中，藏着莫格温娜所行仪式的秘密……以及阻止她的关键。', '进入莫格温娜的小屋，取回她的魔法书。', '', '将莫格温娜的魔法书交给黛德丽', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175126, 'zhCN', '影骨深渊', '你来了！$B$B<黛德丽咧嘴一笑，满口黑牙。>$B$B这费了不小的力气，别以为没有。但最终我做到了，哦是的。斯卡迪尔德没有其他女巫能达成我所成就的：$B$B揭开了莫格温娜围绕影骨深渊所织防护的法术反咒。$B$B那就是你必须去的地方，而且要全速前往。在她完成仪式之前。在斯卡迪尔德诞下那东西之前……$B$B了结莫格温娜，就像你了结瑟蕾妮娅那样。别怕：我会就近待命……以防事情变糟。', '进入影骨深渊，在莫格温娜完成仪式前击败她。', '', '返回黛德丽处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175127, 'zhCN', '逃向大海的人', '我们当中逃离艾尔迪尔的人，并非都躲进了这座矿洞。在追击的混乱中，我想我看见我们的一些人逃向了海滩。$B$B如果他们至今未能自行返回，我担心他们可能陷入了极度困境。', '查明逃往消逝海岸的裂岩难民的命运。', '', '与海滩上的难民取得联系。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175128, 'zhCN', '最后的俘虏', '<这名男子为保护自己对鱼人而死，鱼人已在岩石远端建立起他们的村落。他们可能掳走了俘虏，若是如此，或许仍有幸存者等待救援。>$B$B<冒险进入鱼人聚落，拯救裂岩的囚犯。>', '冒险进入消逝海岸的鱼人村落，营救裂岩囚犯，然后向桑德尔汇报。', '', '返回桑德尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175129, 'zhCN', '羽鳞鱼人', '<致使这名男子受致命伤的鱼人，与你别处遇到的鱼人不同。>$B$B<杀死它们会减少斯卡迪尔德所面临的麻烦清单。>', '消除消逝海岸上的羽鳞鱼人威胁。', '', '返回桑德尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175130, 'zhCN', '变异鱼人的羽刺', '<一种前所未见的鱼人种类的羽刺。尖端似乎覆有毒素，比刚磨利的矛刺得更深。>$B$B<将其交给能够研究其来源的人，方为明智之举。>', '将这不知名的鱼人羽刺交给灰天的阿尔卡里安。', '', '在灰天与阿尔卡里安交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175131, 'zhCN', '战争的苦涩遗产', '<基尔达以锐利而不耐烦的手势示意你上前。他的目光阴沉而忧虑。>$B$B你说过你叫$N，对吧？嗯。好。你行。$B$B我有一项任务给你。我本想派我的山地卫兵，但他们被霜鬃、温迪戈、野猪、豹、熊、狼，还有……缠住了。$B$B<基尔达深吸一口气。>$B$B仔细听好：一支外交车队最近从铁炉堡出发，前往城邦邓卡扎德。出了岔子。他们在蜿蜒之路上遭伏击，虽然使节幸存并得以继续旅程，但他们请求增援。$B$B你就是那些增援。$B$', '侦察蜿蜒之路上的伏击地点，调查发生了什么，并追踪使节萨尔加斯·安威玛。', '', '阅读加密密函。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175132, 'zhCN', '一封加密讯息', '<这封密函的内容可能揭示伏击者的身份以及他们所遵循的命令。>$B$B<沿蜿蜒之路前行可抵达尼维拉恩；村里或许有人能破译文件内容。>$B$B<旅店老板通常熟知邻里间的每则谣言，认识的人也比任何人都多。从咨询尼维拉恩的旅店老板开始，或许是个好主意。>', '与尼维拉恩的旅店老板达利尼尔交谈，请他帮忙找能破译密函加密内容的人。', '', '找到戈林的房间', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175133, 'zhCN', '毛茸茸的骄傲', '<矮人费力地将目光聚焦在加密密函上。良久，他发出一声咕哝。>$B$B「破译这玩意儿，费的功夫比我估计的多。太多了！但是……<打嗝>，但我愿意做个交易。$B$B你看，我告诉过你，我欠旅店老板钱；那不全是真的。他和我做了笔交易：作为免除我债务的交换，我帮他干几件杂活。其中最主要的，就是喂养和清理他农场里的牦牛。$B$B我可不是要在这儿闲坐着！你照料牦牛的时候，我会试着破译这该死的讯息。」', '在尼维拉恩的农场喂养牦牛，并清理它们厩中的脏稻草。', '', '返回戈林处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175134, 'zhCN', '解渴', '除了牦牛，还有一件事。作为我与达利尼尔达成的交易的一部分，我答应帮他给旅店客人供应啤酒。$B$B但我是个学者！<打嗝>。这种事有失我的身份，况且，我还得帮你弄这个，对吧？$B$B<戈林带着狡黠的笑容晃了晃加密密函。>$B$B你来处理。去和他谈，告诉他你是代表我来的；你和我已经达成了交易。', '在旅店与达利尼尔交谈，并代戈林为口渴的客人供应啤酒。', '', '与戈林交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175135, 'zhCN', '破译密码', '是的，我完成了。而且……<戈林最后一次扫视他誊写的文件>。以我母亲的胡子发誓……$B$B<他几乎瞬间清醒了。>$B$B信里说得不多，但有一件事说得很清楚：那些伏击外交车队的人，是在听从邓卡扎德内部某人的命令。一个将安威玛参议员视为威胁……也是机会的人。$B$B他们没被命令杀他，而是吓唬他。$B$B你得走了，我估摸着。你得警告萨尔加斯·安威玛他所面临的危险。某个有权势的人正在密谋反对他，而且他们就在附近。', '在邓卡扎德寻找铁炉堡外交车队首领、参议员萨尔加斯·安威玛，并向他汇报你的发现。', '', '与萨尔加斯·安威玛交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175136, 'zhCN', '铁炉堡特使', '我有一项任务给你，还有一个头衔；就当是晋升吧。$B$B我要你以铁炉堡特使的身份，与这座城市的领主阿扎加尔·石歌谈谈。效忠于他，并协助邓卡扎德的政府，作为国王麦格尼·铜须的善意之举。$B$B与此同时，我和我的表亲将调查这桩阴谋，直到找出下令袭击的人。若走运，到那时你已赢得了领主的友谊……$B$B以及他的信任。', '在邓卡扎德城的接见广场，向阿扎加尔·石歌领主报到。', '', '向邓卡扎德领主阿扎加尔·石歌汇报', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175137, 'zhCN', '受将军统辖', '你说效忠于我？$B$B<领主的声音带着一丝怀疑。>$B$B你能为这座城市的矮人提供何种效劳？你精通战斗吗？你通晓治疗之道吗？或许建筑？$B$B<他巨大的眉毛随着问题微微一动。>$B$B无论如何，我接受你的效劳。我会让我的将军鲍格沃尔夫来决定如何最好地发挥你的才干。', '在邓卡扎德与鲍格沃尔夫将军交谈，看看你能如何协助城市的防御。', '', '与鲍格沃尔夫交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175138, 'zhCN', '支援梅塔特纳前哨', '你既然到了邓卡扎德，想必已目睹过凯雷德-扎拉姆的水域。很久以前，这座城市的矮人允许在湖畔修建梅塔特纳前哨；那是连接暴风城与铁炉堡的深铁电车的哨所与维护枢纽。$B$B我们最近收到了来自前哨的求救信号。尽管严格来说这不归我们管，但考虑到当今世界之态，我怀疑若我们不插手，还会有别人来援助他们。$B$B「我们」，自然包括你，自你向领主效忠以来。$B$B你的命令清楚了吗？', '前往梅塔特纳前哨，与机械师纳丁·螺丝刀交谈。', '', '与机械师纳丁·螺丝刀交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175139, 'zhCN', '深铁电车的外层水晶', '警报连着警报！电车的水下玻璃处于危急状态！$B$B连接铁炉堡与暴风城的线路，正好从我们脚下穿过。那些城里人认为它穿海而过……哈！不！它其实在冰冻的湖底；对，就是这片冰冻的湖！这里是霜蟹的家园，而玻璃上所有凹痕和划痕都是它们造成的！$B$B这些警报大作，我不能让梅塔特纳前哨无人看管；整个地方可能炸上天！你来负责！穿上潜水服，抓起强力胶带，把玻璃的外层修补好。$B$B顺便……帮我个忙，削减一下霜蟹的数量。', '穿上潜水服，修复深铁电车的外层玻璃，并杀死霜蟹', '', '返回机械师纳丁·螺丝刀处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175140, 'zhCN', '梅塔特纳站点警报！', '玻璃应该还能撑几个月，我想。但是……紧急状态通知停不下来。我不明白。这是个玩笑吗？肯定是玩笑！$B$B除非……嗯。$B$B<纳丁的眼睛像跳蚤一样扫过控制屏幕，胡乱按着按钮。>$B$B警报并非源自这个前哨，而是来自站点。梅塔特纳站点，在主设施那边！$B$B去那边，找我的上级，高阶机械师多尔里克斯。若他们需要援助，他会告诉你该做什么。 ', '前往梅塔特纳站点，查明发生了什么。', '', '与梅塔特纳报警机器人沟通', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175141, 'zhCN', '警告！危险！', '警告！危险！$B$B穴居人！$B$B<机器人的声音劈裂，听来像一支悲伤走调的小号。灯光暗了几秒。>$B$B穴居人——杀——我的——创造者！$B$B<警报猛然恢复，疯狂闪烁。>$B$B警告！危险！复仇！', '在梅塔特纳站点击败断天线穴居人。', '', '返回梅塔特纳报警机器人处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175142, 'zhCN', '警告！收集！', '警告！紧急！价值！$B$B<报警机器人朝营地中散落的一堆废料急促地走了几步。>$B$B零件——机器——价值！$B$B收集！收集！零件！', '在梅塔特纳站点收集梅塔特纳零件。', '', '返回梅塔特纳报警机器人处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175143, 'zhCN', '警告！击杀！', '<两声微弱的哔响后，报警机器人进入睡眠模式，开始播放一段录音：高阶机械师多尔里克斯的最后时刻。>$B$B「梅塔特纳站点失守了！穴居人……他们从内部蜂拥而至。他们在听从一名黑铁矮人的命令。他一定用暗影魔法奴役了他们脆弱的心智。我们的工程师试图守住设施，但我们做不到……」$B$B<录音骤然中断。>$B$B<报警机器人闪烁着恢复运作。>$B$B矮人！杀！警告！', '在梅塔特纳站点击败率领穴居人的黑铁矮人。', '', '返回梅塔特纳报警机器人处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175144, 'zhCN', '保护！数据！', '警告！搬运！运输！数据！信息！零件！记录！梅塔特纳！$B$B<报警机器人转动到位，开始蹒跚地朝梅塔特纳前哨走去，机械师纳丁·螺丝刀正在那里等候。突然，它嘎然而止，转向你，发出金属般的尖啸。>$B$B搬运单元！目的地：梅塔特纳前哨！', '将报警机器人搬运到梅塔特纳前哨。', '', '与机械师纳丁·螺丝刀交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175145, 'zhCN', '慷慨与职责', '$N，我会留下来看管梅塔特纳设施，但我需要你向鲍格沃尔夫第一手汇报这起破坏事件。$B$B告诉他派些卫兵来巩固该地区，并派一支机械师小队来恢复站点的运行安全。$B$B与此同时，我会研究报警机器人中储存的数据。我或许能提取出一些情报，搞清楚那个黑铁矮人为何想让连接暴风城与铁炉堡的深铁电车失效。$B$B快动身！没时间可耽搁了！', '前往邓卡扎德，将梅塔特纳站点发生的事情告知鲍格沃尔夫。', '', '与鲍格沃尔夫交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175146, 'zhCN', '博雷奥斯堡垒', '你通往这座城市的路，在邓卡扎德城门之前岔开一点，继续向山上攀爬。$B$B用我们自己的语言，那条古道被称为「斯凯尔德兰德」，即寒冬之路。$B$B我需要有人沿它走到博雷奥斯堡垒。我已数日没有他们的任何音讯。$B$B驻守那里的战士们正面对霜鬃巨魔。他们可能陷入了严重麻烦。$B$B<鲍格沃尔夫向你投来紧迫而急切的一瞥。>$B$B去吧。', '沿寒冬之路前往博雷奥斯堡垒，向卫兵队长埃尔德鲁因报到。', '', '与卫兵队长埃尔德鲁因交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175147, 'zhCN', '以血染雪', '如果鲍格沃尔夫派你来的，那我猜你有能力在外面自保。$B$B<埃尔德鲁因沉重的呼吸暴露了他的疲惫。他身边的战士也好不到哪去。>$B$B我们累垮了……打了这么久，筋疲力尽。$B$B你能了结那些仍在这堡垒附近游荡的巨魔吗？', '击败在博雷奥斯堡垒周围游荡的霜鬃巨魔。', '', '向卫兵队长埃尔德鲁因回报', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175148, 'zhCN', '狮鹫蛋', '这地方不只是堡垒。$B$B它曾是个栖息所，我们在那里繁育狮鹫。$B$B巨魔袭击时，有些逃走了。另一些倒下，战斗到最后一刻以保卫它们的巢。尽管霜鬃是残忍的敌人，我很难相信他们竟有条不紊到摧毁每一颗蛋。$B$B也许还有时间拯救一些。你会把你在外面找到的任何蛋带给我吗？', '从寒冬之路上博雷奥斯堡垒周围的巢穴中取回狮鹫蛋。', '', '将蛋交给哈尔吉', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175149, 'zhCN', '高高举起首级', '扑向我们的巨魔，不过是霜鬃大军的先锋。而且他们听从一名监工的命令。$B$B人类怎么说的来着？「船长与船共存亡」，我想。$B$B<矮人漆黑的眼眸中闪过一丝邪恶的光。>$B$B在你屠戮他部下的同时，让他全身而退，那可真是个耻辱。$B$B去找他。他一定在附近徘徊。一旦你解决了他，就把他的首级带给达尔格兰。沿寒冬之路再往前走便能找到他，假设巨魔还没结果他。$B$B他是我们的……侦察兵。', '击败霜鬃突袭者的领袖，将他的首级交给达尔格兰。', '', '将米格巴拉的首级交给沿寒冬之路更远的达尔格兰', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175150, 'zhCN', '部落干涉', '我们来谈谈补给。$B$B若不是部落，那些野蛮人至今还会只用棍棒和石头来攻击我们。$B$B他们在下面拼凑起的那个村子，堆满了成山的板条箱。几周来他们一直用这些来为其对抗谷中人类的战争提供燃料。$B$B砸碎你能找到的每个板条箱。在那儿制造些混乱。', '摧毁寒冬之路上霜鬃营地的部落补给。', '', '向达尔格兰回报', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175151, 'zhCN', '部落的干涉', '至于这些霜鬃如何运作……我们知之甚少，而即便那点所知，也超出我们情愿。但有一件事是肯定的：若没有部落之手的引导，他们的整个战略便会瓦解。他们绝无可能协调如此规模的袭击。$B$B我知道你已流了许多血才走到这里，但我必须请求你做最后的一次努力。$B$B砍倒在下方村子里混迹于霜鬃之间的部落士兵。$B$B他们的沉默，是我们唯有以他们性命才能买到的奖赏。', '杀死寒冬之路上霜鬃营地的部落特工。', '', '向达尔格兰回报', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175152, 'zhCN', '寒冬之路', '这条小径，寒冬之路，从东到西蜿蜒穿过艾尔德弗罗斯特的群峰。$B$B危难时刻，这个领域的矮人会向山谷对面的莫罗杜因山寻求建议。这并非巧合；因为在遥远的过去，泰坦在其雪顶之上建了一座天文台。$B$B数千年来，它唯一也是最终的居民，是一个名叫斯里穆斯的霜巨人。他同类中最睿智者。$B$B我担心他正面临那些霜鬃巨魔的严重威胁。而我们俩之间说，若有人能走完那条路并完好返回，那必定是你。', '沿寒冬之路前往莫罗杜因山顶，保护斯里穆斯免受巨魔侵害。', '', '与迷途的斯里穆斯交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175153, 'zhCN', '一座几近被遗忘的祭坛', '我了解霜鬃。啊，我甚至知道他们源自的帝国！远在世界北端。诺森德……我的故乡。$B$B但围攻这座神庙的生物并非寻常巨魔。我甚至不认为他们是霜鬃的盟友！$B$B我们本可亲自询问，但我担心对话已不再是选项。$B$B嗯……$B$B巨魔不会告诉我们任何事，但他们的洛阿或许愿意开口。$B$B下到他们的村庄，收集他们的精神熏香，然后沿蜿蜒上山的路前往残峰。在那里，你将找到一座古老的祭坛，以及一个或许肯接见你的灵魂。', '从寒冬之路上霜鬃营地的巨魔处取得精神熏香，并前往残峰山顶。', '', '向残峰之灵报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175154, 'zhCN', '废墟中的神庙', '跟我来。$B$B让我们在一个更配得上伟大雪豹之灵的地方交谈。一个更隐秘……也更危险的地方。$B$B<洛阿的眼中突然闪过一丝警告的光芒。>$B$B当心……', '与安祖尔丁交谈，前往雪豹神殿。击败病弱软泥怪，找到洛阿的祭坛。', '', '与祖拉尼兹交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175155, 'zhCN', '雪之洛阿之音', '现在，在此地，在我神庙的深处，那里过去是墓地，未来沦为废墟，我将给你答案。$B$B靠近些。', '向祖拉尼兹询问那些袭击斯里穆斯神庙的奇怪而含毒的巨魔。', '', '聆听祖拉尼兹', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175156, 'zhCN', '病光之子', '霜鬃巨魔撑不了多久，便要被病光之子击溃。$B$B他们本不该卷入那场战争，却白白耗尽了力量。$B$B但马特拉坎的饥渴，绝非仅凭他们便能餍足。那发光之物的野心，早已超越了德鲁克萨尔的边境。其影响，在你的故土之上亦已可感。$B$B光辉镇的狂热者，不过只是冰山一角。$B$B回到你的族人身边。将这片土地面临的危难告知邓卡扎德的矮人，并向我——或你愿祈求的任何人——祈祷，愿他们在为时已晚之前有所行动。', '返回邓卡扎德，将病光之子的威胁告知鲍格沃尔夫将军。', '', '与鲍格沃尔夫将军交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175157, 'zhCN', '噬骨巨魔', '过来吧，孩子。我想你很清楚，困扰我们灰天邻人的那场冲突。$B$B千万别以为霜鬃巨魔仅满足于夺取卡拉多尔对岸的土地。他们已有少数越过了桥梁，来到我们这边，盘踞在安祖拉克洞穴之中。$B$B那是个可怕的地方，一座古老的巨魔亡灵之城。$B$B作为邓卡扎德的主教，我必须请你将这些亵渎者斩于剑下，终结他们邪恶的巫术。', '击败盘踞在安祖拉克洞穴中的霜鬃巨魔。', '', '返回迪加恩主教处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175158, 'zhCN', '噬骨巨魔', '自远古以来，我们矮人与霜鬃巨魔便一直处于战争之中。这是不幸的巧合，却也是必然的：我们都将这些山脉称作「故乡」。$B$B尽管他们最近的侵犯集中在斯卡迪尔德的人类行省，仍有少数巨魔越过卡拉多尔桥，进入了邓卡扎德的边境。$B$B他们已躲入安祖拉克的亡灵之城。$B$B那些野蛮者必须死。而作为万神殿信条的族长，我自能为你提供的服务奉上丰厚的报酬。', '击败盘踞在安祖拉克洞穴中的霜鬃巨魔。', '', '返回阿尔比伦族长处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175159, 'zhCN', '安祖拉克的坏死', '还有更深一层。$B$B盘踞在安祖拉克洞穴中的那些巨魔，听从着一名女巫的黑暗号令。圣光明鉴，她满心只图不轨。$B$B我在幻象中见过她。我见她将亡魂从墓中拽出，我见她以之为食。$B$B你必须终结这一切。那些正遭她亵渎的魂魄……我知道他们是巨魔，也深知他们是亵渎者。但他们拥有灵魂，而在圣光眼中，那便是神圣的。$B$B作为邓卡扎德的主教，我无法坐视不理。', '击败在安祖拉克洞穴中统领噬骨巨魔的女巫。', '', '返回迪加恩主教处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175160, 'zhCN', '安祖拉克的坏死', '若非有那女巫统领，安祖拉克洞穴中的巨魔根本算不得如今这般大患。$B$B他们选址于此绝非偶然。安祖拉克是一座古老的亡灵之城，而那女巫一直在惊扰她先祖的安息，以他们的灵魂为食——倘若他们当真拥有那等东西的话。$B$B你瞧？那些野蛮者什么都不敬，连自己的祖先也不放过。$B$B杀掉他们是慈悲，就从她开始。', '击败在安祖拉克洞穴中统领噬骨巨魔的女巫。', '', '返回阿尔比伦族长处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175161, 'zhCN', '上百张嘴要喂', '山羊肉是我们的招牌！$B$B没听说过？我不意外；我们几乎一星半点都不外销。每一块从这扇门进来的肉，都在这间旅店里被当场吃光！$B$B<矮人得意地大笑起来，可笑着笑着，他咳出了一大团浓痰。>$B$B想尝尝鲜，顺便赚点金币？那便抓起这把大口径短枪，去凯雷德-扎拉姆冰封湖泊周围猎山羊吧。$B$B没弄到够全城人吃的肉，就别回来！', '在凯雷德-扎拉姆冰封湖泊附近猎杀山羊，收集它们的肉。', '', '返回旅店老板石辫处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175162, 'zhCN', '一台「智能」蒸汽坦克？', '你觉得我的智能蒸汽坦克如何？一件工程杰作的，信我：坚固、稳定、可靠。地道的巧匠手艺。$B$B它只需几处代码与系统微调，便能稳定齿轮、辅助瞄准功能，并调节内部温度。侏儒人造智能。$B$B梅塔特纳前哨的机械师纳丁·螺丝刀，会在我们将坦克交付客户前负责这些升级。$B$B我从你脸上看得出来：你巴不得试驾一把，对吧？很好……但前提是你保证把它完好无损地送到纳丁手里。', '登上智能蒸汽坦克，将其送到梅塔特纳前哨的机械师纳丁·螺丝刀处。', '', '与机械师纳丁·螺丝刀交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175163, 'zhCN', '如轮转不息', '诺希着手打造这台蒸汽坦克并非一时兴起；那是联盟军方为安德拉斯特雷要塞下的委托。我们必须修好它！$B$B邓卡扎德附近那些被摧毁的矮人坦克，或许仍残留着有价值的模块，可用来重建诺希的坦克。$B$B我听说有个旋转陀螺部件不久前沉入了湖底深处……把它也取回来，我们正需要它！$B$B你一把所有东西带给我，我就亲自着手收拾这个烂摊子。', '收集旧坦克模块，并从冰封湖底取回旋转陀螺部件。', '', '返回机械师纳丁·螺丝刀处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175164, 'zhCN', '安德拉斯特的什一税', '噔噔！没有机械师纳丁修不好的东西。$B$B那么，想登上真正的智能蒸汽涡轮坦克吗？$B$B把修好的坦克开到安德拉斯特要塞。还有这个拿着！$B$B<纳丁将厚厚一捆文件塞给你，里面满是图表、批注与操作说明。最后几页用极小的字号详列了条款与条件。>$B$B一到安德拉斯特，就把这些交给摩尔指挥官。', '将智能蒸汽涡轮坦克开到安德拉斯特要塞。', '', '与摩尔指挥官交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175165, 'zhCN', '插旗捕鱼', '卡扎德米尔湖一年大半时间都冰封不化。正因如此，这一带的渔民不得不……别出心裁。$B$B湖面上的每个冰窟窿都有自己的旗子，每面旗子都连着一枚鱼钩。鱼儿咬钩拉拽时，旗子便会弹出，向我们示警。$B$B看那儿：此刻就有好几面旗竖着。过去领取你的战利品吧，但小心点！当你把那些鱼拉出水面……嗯，其中有些会彻底发狂！', '启动捕鱼装置，收集卡扎德米尔鱼。', '', '返回洛法尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175166, 'zhCN', '勇士的葬礼', '这座城市住着英勇的战士，两百年间，他们以生命守护着我们的边境。$B$B近来，我们最敬爱的一位战士倒下了。又是巨魔那好战欲望的又一个牺牲品。$B$B他的名字是霍尔多·石拳。$B$B我要你前往雪纱墓地，参加他的葬礼。致以敬意；了解我们的习俗。并确保他得到与其功绩相称的哀荣。', '前往雪纱墓地参加勇士霍尔多·石拳的葬礼，并与其遗孀交谈。', '', '与霍尔多的遗孀比尔娜·石拳交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175167, 'zhCN', '两信，一族', '这对你或许显得奇怪，但我必须请你帮个忙。我发现自己需要一个新的视角，而还有什么人比一个陌生人更适合提供呢？$B$B出席这场仪式的，有圣光教会的贝奥恩主教，以及万神殿信条的卡泽米尔族长。二人都指望我将亡夫的灵魂托付于各自的信仰；而这是他生前无暇亲自做出的选择。$B$B与他们谈谈。熟悉他们的信仰与信条，再将你的见解分享给我。', '与贝奥恩主教和卡泽米尔族长交谈，了解他们的信仰与信条。', '', '与比尔娜交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175168, 'zhCN', '信仰之跃', '又是你。$B$B告诉我，我能为你效劳什么？', '向贝奥恩主教表明你愿意协助这场仪式。', '', '与贝奥恩主教交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175169, 'zhCN', '信仰之跃', '啊，你的好奇心是一种美德。$B$B你是带着更多疑问回来的吗？', '向卡泽米尔族长表明你愿意协助这场仪式。', '', '与卡泽米尔族长交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175170, 'zhCN', '逝者之尊严', '这座墓地是邓卡扎德矮人最神圣的所在之一。$B$B但你看看四周：$B$B不是积雪堆积，便是杂草丛生、四处蔓延。逝者理应得到尊重；至少，他们的名字应当清晰可辨。$B$B我自己已经整理了数座坟墓。你愿意帮我清理其余的吗？', '帮忙整理雪纱墓地。', '', '向贝奥恩主教复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175171, 'zhCN', '逝者之尊严', '矮人，一如我们的创造者，是秩序的存在。而秩序，存在于我们所作的一切之中。$B$B但我们也终有一死，因此也会犯错。这便是时光为何对我们的造物如此残酷。$B$B证据就在你眼前。$B$B我几乎认不出这座墓地已变成了灌木丛。$B$B帮我清理它。逝者值得的尊重，胜过掘墓人给予他们的。', '帮忙整理雪纱墓地', '', '向卡泽米尔族长复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175172, 'zhCN', '葬仪劫掠者', '有桩事让我不安。$B$B当我就坟墓的状况质问掘墓人时，他说了句让我挥之不去的话。$B$B他说他不敢独自来墓地。他什么也没亲眼见到，却听到了声响。低吼声。还有雪地里的脚步声。$B$B他确信某种害虫已在附近安家，任谁也改变不了他的想法。$B$B你能去看看吗？', '调查墓地边缘，找出威胁的源头。然后将其清除。', '', '返回贝奥恩主教处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175173, 'zhCN', '葬仪劫掠者', '雪地里的脚印。巨大，五趾。$B$B新鲜的。$B$B竟无人察觉，令我惊讶。无人拉响警报。绕着墓地走一小圈，便足以发现好几处。$B$B你知道这意味着什么吗？$B$B意味着附近有雪人。而雪人向来是威胁。$B$B找出它们的巢穴，终结它们。', '调查墓地边缘，找出威胁的源头。然后将其清除。', '', '返回卡泽米尔族长处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175174, 'zhCN', '传承数世纪的习俗', '这座城市有个丧葬习俗：从山顶燃烧的火焰上点燃一支蜡烛，再借它照亮逝者的坟墓。$B$B拿上这个。$B$B<矮人递给你一支简朴的蜡烛，白得纯粹，与雪一般无二。>$B$B通往顶峰的攀行漫长而艰辛；寒冷与疲惫会损耗你的身体。但你的心灵，从未如此轻盈。$B$B一旦抵达山顶，寻到守焰者恩里尔，带着被他圣火点燃的蜡烛返回。', '沿通往海尔根峰的小径上行，向守焰者恩里尔报到。', '', '与守焰者恩里尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175175, 'zhCN', '传承数世纪的习俗', '在邓卡扎德的矮人中，有一项属于土灵的传统：从山顶团结火盆中燃烧的火焰上点燃一支蜡烛。$B$B<卡泽米尔以极大的庄重，将一支白烛放入你摊开的掌心。>$B$B你愿走那通往海尔根峰顶的小径吗？若你愿承担这番攀登，便去峰顶寻到守焰者，请他为勇士霍尔多·石拳点燃这支蜡烛。', '沿通往海尔根峰的小径上行，向守焰者恩里尔报到。', '', '与守焰者恩里尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175176, 'zhCN', '霜寒分遣队', '此处的元素善变无常；上一场横扫山岭的暴风雪，留下了一支冰霜元素的分遣队。$B$B它们无一不怀敌意。$B$B从此处起，通往峰顶的路便险恶难行。老实说，我正打算动身前往邓卡扎德，请求领主相助。$B$B但你来了。而且你看起来足够有能力。或许……或许你愿意考虑独自去对付那些元素？', '击败在海尔根峰游荡的冰霜元素。', '', '返回守焰者恩里尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175177, 'zhCN', '木之献祭', '身为守焰者，我的职责是确保团结火盆永不熄灭。$B$B我们邓卡扎德的矮人，在离开铁炉堡、于三锤之战黎明之际，首次点燃了它。而在三氏族放下分歧、和平重回矮人族群之前，我们无意让它熄灭。$B$B从我的营地打捞几截木桩，抛入峰顶火盆的烈焰之中。', '从恩里尔的营地收集木桩，投入团结火盆以添薪火。', '', '向团结之魂致以敬意', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175178, 'zhCN', '团结之烛', '我明白了。$B$B你不仅走完了这条通往峰顶的小径——这壮举足以令许多人膝软——还直面了霜寒恶魔，将他们逐回元素位面。$B$B而这一切，只为一支蜡烛。$B$B<一声迸发响起，似是巨大的笑声，又或许是火焰的噼啪。>$B$B逝者生前定是一位了不得的勇士，你才肯如此费心。$B$B你已得到我的祝福。带上蜡烛，返回墓地吧。', '等待团结之魂点燃蜡烛，并将其带回墓地。', '', '返回比尔娜·石拳处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175179, 'zhCN', '告别仪式', '我已决定将亡夫的灵魂托付于圣光。$B$B他此生饱经战争；死亡与暴力数不胜数。若圣光能予霍尔多哪怕一丝安宁，予我些许慰藉……$B$B你愿留下聆听贝奥恩主教的布道吗？$B$B当你准备好仪式开始之时，与他交谈。', '通知贝奥恩主教，仪式可以开始了。', '', '与贝奥恩主教交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175180, 'zhCN', '告别仪式', '霍尔多常谈起传承。他期望留给我们一座更安全、更强大的城市。$B$B更自主的城市。$B$B他对灵性向来兴趣寥寥，但我相信，他会欣赏万神殿信条的务实。$B$B去了解，去铭记，去敬奉。这便是我们现在必须为亡夫所做的。$B$B当你准备好仪式开始之时，与族长交谈。', '通知卡泽米尔族长，仪式可以开始了。', '', '与卡泽米尔族长交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175181, 'zhCN', '信众壮大', '多谢你了。若无你的帮助，我相信石拳一家最终会选上万神殿信条。$B$B那自然是一门高贵的宗教，却少了慰藉。而人面对死亡时，最需的莫过于悲悯。$B$B不过，我还有最后一个请求。你途经邓卡扎德时，去见见我的上级迪加恩主教。告诉他，石拳家族已皈依圣光。', '前往邓卡扎德，将石拳家族皈依圣光的消息告知迪加恩主教。', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175182, 'zhCN', '信众壮大', '我在此的使命已了，但还有最后一项任务托付于你。$B$B阿尔比伦族长是我在邓卡扎德教团的领袖。我要你返回城中，将这片墓地里发生的一切告知于他。$B$B告诉他，勇士霍尔多·石拳及其家族已皈依万神殿信条。', '前往邓卡扎德，将石拳家族皈依万神殿信条的消息告知阿尔比伦族长。', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175183, 'zhCN', '领主的核心圈', '仔细听好：我与堂兄索拉津一直在抽丝剥茧，追查这桩阴谋。$B$B起初，我们以为这是黑铁矮人的阴谋。但绝非如此。$B$B一切线索都指向领主本人：阿扎加尔·石歌。$B$B我们担心他正策划一场对抗铁炉堡的战争。$B$B索拉津和我正被监视，你却仍获准自由通行。所以，记住我的话：前往阿达-甘巴德要塞。它属于铜须氏族，离此不远。$B$B你必须拉响警报！', '向阿达-甘巴德要塞的山地卫兵队长报到，就领主的阴谋拉响警报。', '', '与法里格纳尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175184, 'zhCN', '雪与灰相遇之处', '若邓卡扎德领主果真渴求战争，这座要塞将第一个尝到他战锤的痛击。$B$B这意味着我不能再白白耗费力气与工会缠斗。$B$B你在此现身，便足以证明安威玛参议员信任你。因而，我也如此。$B$B前往前线。助我的部下击退影灼工会的黑铁矮人，好让他们有序撤离。', '协助击退阿达-甘巴德要塞附近的影灼工会侦察兵与斥候。', '', '向法里格纳尔复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175185, 'zhCN', '火之无心馈赠', '被工会奴役的火元素在死亡时会释放出一种精华：类似余烬之物。$B$B我认识几位炼金术士，愿出高价争得研究它们的机会；而我们，恐怕得将它们派上更实际的用场。$B$B收集一些那样的余烬，用来为前线受伤的山地卫兵灼烙伤口、止血疗伤。', '从工会被奴役的元素生物身上收集余烬，用它们为阿达-甘巴德山地卫兵的伤口止血。', '', '向法里格纳尔复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175186, 'zhCN', '地狱中的朋友', '在我组织要塞防御的同时，有项新任务交给你。$B$B这次有些敏感，也更为危险。$B$B我要你找到恩格里姆。他是工会里的一名矮人。一名渗透者。他为我们充当线人，但我已有一阵子没他的消息，怕是凶多吉少。$B$B若他还活着，你会在焰嗥洞穴附近找到他。运气好的话，他能帮我们厘清工会与邓卡扎德之间、以及领主战争阴谋的关联。', '在焰嗥洞穴附近寻找工会线人恩格里姆。', '', '与恩格里姆交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175187, 'zhCN', '烬影', '作为对他们效力的奖赏，大术士索格林姆将雪人浸入影焰之中。$B$B那些活下来的，被锻造成火与余烬的生物；工会的精锐，他自己的亲卫队。$B$B无论索格林姆的图谋为何，雪人都是其核心。我们越早将他们从棋局中抹去，对大家越好。$B$B尽你所能，将在其中发现的它们尽数斩杀。', '消灭焰嗥洞穴中影灼部族的雪人。', '', '向恩格里姆复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175188, 'zhCN', '残酷者凯瑟里克', '术士凯瑟里克——索格林姆的左右手——就躺在焰嗥洞穴的心脏深处。$B$B<从他的语气听来，恩格里姆对他的憎恶，似乎更甚于大术士本人。>$B$B我要你杀了他，把他的誓言指环带给我。$B$B计划的下一步，我们正用得着它。', '在焰嗥洞穴深处击败术士凯瑟里克，取得他的誓言指环。', '', '返回恩格里姆处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175189, 'zhCN', '影焰诞生之地', '我先前对你讲的关于烬影雪人与索格林姆黑魔法之事，不过是个故事罢了；是工会用谣言拼凑缝合的宣传。$B$B真相，我怕，要阴险得多，也更为隐秘难寻。$B$B但我怀疑已久，答案就在其中。$B$B<恩格里姆以一记凌厉的手势指向洞穴。>$B$B将你发现的任何神器与遗物带给我；任何能阐明工会起源与索格林姆影焰来源的东西。', '从焰嗥洞穴中取回黑暗法术神器。', '', '返回恩格里姆处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175190, 'zhCN', '索格林姆之伤', '把手给我。$B$B<恩格里姆将凯瑟里克的指环套上你的手指。随后他开始低声念诵咒文。>$B$B一道幻象附魔。它将赋予你凯瑟里克的外貌；探索索格林姆之伤，你定然用得着。$B$B若邓卡扎德领主与影灼工会当真结盟，你便能在那里找到揭穿他们阴谋所需的证据。', '探索索格林姆之伤，收集能将影灼工会与邓卡扎德领主联系起来的阴谋证据。', '', '检视那封密函', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175191, 'zhCN', '崭新而阴险的命令', '<文件内容如下：>$B$B「随着大术士的计划临近实现，工会的职责也随之扩展。」$B$B「特此召集索格林姆之伤内的所有工人前往黑渊堡，接受新指令。」$B$B「出席并非可选。」', '前往黑渊堡，听取工会的新命令。', '', '与监工纳格里姆·焚灭者交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175192, 'zhCN', '残酷的纪律', '那些新兵。$B$B他们知道你是谁，因为他们听过你的名字。而自然地，他们已学会畏惧它。$B$B我本打算亲自走入他们中间，给几个人一点纪律的教训，但我相信，你更能有效地将他们震慑屈服。', '向工会新兵发起战斗并将其击败。', '', '返回纳格里姆处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175193, 'zhCN', '黑石奴隶', '还有一桩事。$B$B我本不会想到拿这种事烦你，但既然你坚持，我确信你定比我的人成功得多。$B$B黑石奴隶近来一直惹是生非。他们态度违抗，干活的速度也远不及他们所能。$B$B你觉得你能教训他们几个吗？', '惩戒索格林姆之伤中的黑石奴隶。', '', '返回纳格里姆处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175194, 'zhCN', '受折磨的火焰', '你不在时，出了个始料未及的变故：$B$B影灼之魂再次挣脱了束缚。$B$B那帮女巫会试图安抚它，但你清楚那些有抱负的术士……他们根本不配与你相比！$B$B我相信，这次得靠你的本领才能将它制服。', '在索格林姆之伤中击败影灼之魂。', '', '向纳格里姆复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175195, 'zhCN', '棋局已布', '您的气度，大人，激励着我们所有人。我的部下不会很快忘记这堂谦逊之课。我也不会。$B$B身为领袖，也须亲力亲为。$B$B既然一切就绪，我们该通知邓卡扎德的联络人了。这才是一件配得上您法术的任务！城里那些蠢货，就算把手直接从您的幻象中穿过，也认不出来。$B$B代我向索拉津问好。那矮人已证明自己是个有用的棋子；您定会同意。他那满腔的野心……', '离开索格林姆之伤，将你发现的关于工会阴谋及索拉津·安威玛参与其中的一切，告知恩格里姆。', '', '与恩格里姆交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175196, 'zhCN', '背信的野心', '<恩格里姆摩挲着下巴。>$B$B不，这其实说得通。若索拉津的野心是夺回铁炉堡王座、复兴安威玛王朝，他便需要一支军队。$B$B第一步，便是挑起外交危机，将铁炉堡与邓卡扎德逼入公开战争。他的堂兄、萨尔加斯参议员，从一开始便是他不自知的棋子。$B$B我怀疑，计划的下一步是待国王与领主的军队彼此消耗殆尽后，工会再卷入战局。但究竟是什么疯狂，让索拉津以为自己能驾驭这些狂热者？$B$B你必须立刻在邓卡扎德拉响警报。直接禀报阿扎加尔·石歌领主。', '前往邓卡扎德，直接禀报阿扎加尔·石歌领主。', '', '禀报邓卡扎德领主阿扎加尔·石歌', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175197, 'zhCN', '影灼地下城 [PH]', '', '', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175198, 'zhCN', '北门之声', '我见你和达伦加领主交谈过。那群乌合之众没派你来吧，我相信？<瑟蒙·斯帕达以高傲而审视的目光打量着你。>$b$b不过听我说。他们当然没有。你倒更像个雇佣兵，我猜。$b$b事情是这样的，我们在暴风城北门有一群愤怒的暴民，要求就斯卡迪尔德的局势给出答复。我们迄今尝试的一切都没能安抚他们，但我忽然想到，由与他们「身份相仿」之人出面劝说，或许比一纸官方文书更有效。$b$b去和他们谈谈。必要时吓唬吓唬他们。办完后，去找我侄子泰尔·斯帕达，他正守在门口。', '告知暴风城矮人区中忧心忡忡的市民，贵族议院已听闻他们的请求。', '', '与卫兵泰尔·斯帕达交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175199, 'zhCN', '铁枝矿洞中的暗影', '<仔细检视矿石后，你注意到一处奇异的异样：一道既不属于石头、也不属于洒落其上的光线的「暗影」。>$b$b<在寻找能解读这一异象、并判断它是否与矿工遭遇相关的人之前，多收集些样本方为明智之举。>', '在铁枝矿洞收集暗影矿石，并找人加以分析。', '', '与贝尔德雷德交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175200, 'zhCN', '无可赦之罪', '终有一天，我们皆得圣光的宽恕。尽管对某些人而言，赦罪要以性命为代价。$B$B你愿成为它神圣审判的工具吗？$B$B通常，忏悔之封印是不可侵犯的原则。但圣光已允准向你揭示三个名字：$B$B奥尔德伦修士、圣骑士阿比盖尔与塞缪尔·克劳。圣光认定这三人都不足蒙赦。$B$B谨记：阐释其意非我辈之责，执行其意才是。若有必要，便付诸实行。', '在圣风修道院内外杀死奥尔德伦修士、圣骑士阿比盖尔与塞缪尔·克劳。', '', '返回忏悔者默恩处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175201, 'zhCN', '矿洞隐藏之物', '那些从灰天派来的铁皮蛮子，没有一个能解决豺狼人的问题——除非他们所谓的「解决」是指「杀光」。若真如此，你也不会听我抱怨。$b$B无论如何，我无法再为你做什么了。这算是我客客气气请你离开我的小屋。$b$B<贝尔德雷德用她极长的手指指向门。>$b$B那就再见了！去干你最擅长的事吧，我也不知道是什么；杀生、采花……或是与人交谈。对，就是这个！把你的发现告诉阿姆罗斯队长。那阿姆罗斯，真是个好人，嗯？如此关切……我敢说他从没离开过酒馆。', '将铁枝矿洞中发生的事告知阿姆罗斯·达戈尔队长。', '', '与阿姆罗斯·达戈尔队长交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175202, 'zhCN', '向灰天复命', '返回灰天，将你所知的一切禀报德雷温爵士。事无巨细：奇诡的与平常的，皆不可遗漏。$B$B这位卫兵统领是个判断稳健的人。若这诅咒之事确有真相，他自会知道该当如何。$B$B后会有期，$N。此乃荣幸。', '前往灰天，向德雷温爵士复命。', '', '与灰天的德雷温爵士交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175203, 'zhCN', '三姐妹的智慧', '三姐妹栖身于迅水瀑布深处的一处隐秘洞穴。从灰天前往，最快捷的路径便是穿过「祖母的良方」的地窖。$b$B你得从后院溜进去，就在我们左侧。店由两姐妹经营：希尔达与泽尔达，草药师。表面上是如此。$b$B若被她们逮到，她们可不止朝你扔一把草药那么简单。', '潜入「祖母的良方」的地窖，利用秘密活板门。然后找到三姐妹。', '', '在三姐妹面前现身', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175204, 'zhCN', '枢机之罪', '数周前，有个人来到你面前。卡登。他寻求一味禁药，一样不可能之物：$B$B能治愈死亡本身的魔法。$B$B我们警告过他，擅改神圣轮回的后果，他却充耳不闻。久而久之，一个声音在他心智的边缘低语，将我们拒绝给予他的知识献上。$B$B你愿打破这诅咒吗？那便去它的诞生之地：悬空修道院下的墓穴。卡登正是在那里，以一具被亵渎的躯体，犯下那枢机之罪。$B$B<三姐妹最后以长久而沉默的目光注视着你。>', '深入圣风修道院的墓穴，击败罗伊斯枢机主教。', '', '返回三姐妹处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175205, 'zhCN', '来自克雷斯特海恩的消息', '那些被卡登从死亡中唤起者，很快将化为灰烬。如此，阿兰娜便能得到她挚爱从她手中夺走的安息。$B$B谨记此训：黑影本无武器伤你，唯你置于其手中的那一件例外。恋人的执念、疯子的暴怒、圣徒的僵固……$B$B皆可被扭曲变形。$B$B<三姐妹在离去前，将你的名字祝福了三次。>$B$B去吧。离开此地。你在这段故事中的角色已近尾声。灰天那些铁皮士兵会想知道，你已处理了克雷斯特海恩的威胁。', '返回灰天，将克雷斯特海恩发生的事禀报德雷温爵士。', '', '向德雷温爵士复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175206, 'zhCN', '各色奶酪', '抱歉麻烦你，但我此刻真是分身乏术。母亲离不开店，父亲又心事重重；一边是风拂奶酪日渐响亮的名声，一边是暴风城的局势……$B$B能帮我个小忙吗？我送货迟了。$B$B我只需将这份奶酪拼盘送到暴风城公园的精灵扎拉迪尔那里。花不了多少时间，而你可就帮了我天大的忙。', '将这份奶酪拼盘送到暴风城公园的扎拉迪尔处。', '', '与暴风城公园的扎拉迪尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175207, 'zhCN', '苍白海岸', '<关于斯卡迪尔德行省及其眼下所陷危机的阴暗消息与险恶谣言，正传遍暴风城王国乃至更远之处。>$B$B<无疑，这对王国与联盟皆是凶讯。但它们也为你这般冒险者提供了契机：献上你的服务、填满你的钱袋、闯出你的名号。>$B$B<搜寻更多信息方为明智。>', '进一步了解斯卡迪尔德的危机。', '', '与达伦加家族的侍从交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175208, 'zhCN', '来自卡拉诺斯的密函', '我可不是头回见你和卫兵统领交谈，我便擅自向他打听过你。$B$B他是个寡言之人，能听他称赞更是罕事。但他称赞了你。你既赢得他的信任，便也赢得了我的。$B$B<矮人的目光染上哀伤。>$B$B不久前，我收到卡拉诺斯山地卫兵队长基尔达的密函；事关至急，牵及这片土地与邓卡扎德城邦。$B$B去他面前报到。告诉他，格拉姆吉尔从灰天派你来的。', '前往卡拉诺斯，到山地卫兵队长基尔达面前报到。', '', '到卡拉诺斯的基尔达面前报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175323, 'zhCN', '改心', '你看起来像是个……有能力的人。你不会介意帮一个贫穷卑微的吟游诗人一把吧？$B$B说来，除了唱歌，我也擅长炼金术。噢不，别担心！这里没有巫术。只有科学。$B$B<艾丝琳向你使了个心照不宣的眼色。>$B$B但科学，人所共知，需要……材料。$B$B此例而言，一颗狐心。$B$B完整的。', '取得一颗斯卡迪尔狐的心脏。', '', '将心脏带给艾丝琳', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175324, 'zhCN', '以牙换歌', '等等。$B$B在你踏入那广袤奇绝的世界之前，我有个差事。$B$B是是，我知道我讨人嫌。但我保证这值得你费心。$B$B你和我们法警约尔南·塔洛尔谈过了吗？若他还没开口，也快了：杀几头熊，把熊皮带给他。$B$B我只要牙齿。$B$B我是说熊的牙。不是法警的。还没到时候。$B$B五十颗牙应当够了。', '从老雾森林中游荡的熊身上收集五十颗熊牙。', '', '将牙齿带给艾丝琳', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175325, 'zhCN', '致盲黑鸦', '我知道你是此地异乡人，但连你也定已注意到：$B$B斯卡迪尔德的乌鸦，比田里的草还多。$B$B而其中有些乌鸦……$B$B<艾丝琳打了个寒颤。>$B$B有些乌鸦正过分密切地注视着我们。$B$B你知道我怎么想吗？我想它们被附身了。它们听命于某个第三方。或许是个女巫。或更糟的东西。$B$B带一只它们的眼睛给我，我们便能确知。', '在老雾森林取得一颗被附身的乌鸦之眼。', '', '将被附身的乌鸦之眼带给艾丝琳', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175326, 'zhCN', '近处有狼', '啊，近来邓郡难得见到新面孔。$B$B我猜你算是……个雇佣兵？$B$B好，好。我钱袋宽裕，也有活要干。$B$B贸易中断，王国疏于护路，狼群便猖狂起来。它们抵达邓郡只是时间问题。$B$B在这以南杀几只。提醒它们畏惧钢铁与火焰。$B', '斩杀在邓郡悬崖脚下徘徊的狼。', '', '向约林复命', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175327, 'zhCN', '可怜的佩图尼亚', '你……带着武器。$b$b当然。你一路走到了这里。而道路如今这般光景……$b$b<乌莉拉不停地抓挠自己的手。>$b$b能帮我个忙吗？$b$b昨夜……佩图尼亚不见了。我的一只母鸡。她是个美丽的生灵。一只下蛋的母鸡，和其他的一样。$b$b我看到了血。还有羽毛。我想是村子里游荡的某只狐狸吃了她。$b$b你能……找找她吗？她该在某只狐狸的肚子里，我猜。而说真的，我想把她埋了。$b$b<乌莉拉含泪的双眼向你投来恳求的目光。>$b', '在邓郡附近游荡的某只狐狸的胃中，找到母鸡佩图尼亚的残骸。', '', '返回乌莉拉·灰谷处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175328, 'zhCN', '不过是死灵法术', '我想你是要回灰天了。$B$B若是如此，我有件事相求。$B$B去教堂，把你在克雷斯特海恩这里墓穴中的发现告诉牧师。$B$B让他去查城市档案，或圣风修道院，若有必要；总该有人，在某个时刻，描述过这类魔法。$B$B以及我们该如何自保。$B$B<「关切」二字，远不足以形容埃尔罗斯眼中深切的不安。>$B$B那情景仿佛……仿佛圣光本身，病态而残忍，将他们从墓中唤起……$B', '将克雷斯特海恩墓穴中发生的事，告知灰天教堂的随军牧师孔瑟。', '', '与灰天的随军牧师孔瑟交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175329, 'zhCN', '延后的祝福', '什么……？不，我并非在祈祷。尽管对我们许多人而言，罗伊斯枢机主教是位圣洁之人：他将圣光带至这片土地，并创立圣风修道院作为朝圣地。$B$B多年来我渴望踏上这趟旅程，但……不。还不行。年迈的母亲需要我。我不能留她无人照料。$B$B你参观过修道院了吗？若你哪天行至圣风，或许能帮我个小忙。$B$B<拉薇娅将一只银制吊坠交给你。>$B$B在修道院里找人为它祝圣，并为我母亲的灵魂念一段祷词。我知道这不同于亲自朝圣，但……我只能将就。$B', '将拉薇娅·维尔莫的吊坠带给圣风修道院的教堂司事塔蕾丝。', '', '与塔蕾丝交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175330, 'zhCN', '矿与薪火', '幸会！容我自我介绍：杜尔甘·戈拉尔。商人。创业者……$B$B<矮人皱起眉头。>$B$B我们见过吗？我记不住面孔。也记不住名字。不过无妨。$B$B有件或许能让你感兴趣的小差事。实在微不足道。$B$B<杜尔甘将一封密封卷轴交给你。>$B$B给克雷斯特海恩的法警。我需要许可，在村子附近进行小规模挖掘。附近没有矿场，而那片土地之下，谁知道藏着什么财富！$B', '将杜尔甘·戈拉尔的卷轴递交给克雷斯特海恩的法警。', '', '与约尔南·塔洛尔交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175331, 'zhCN', '会歌唱的花', '想赚今天的面包钱吗？$b$b你只需把这送到克雷斯特海恩。$b$b<希尔达递给你一束白色草药。花朵状如泡沫。>$b$b它们只长在雪歌谷，我们一位常客托我们给她弄一大把。$b$b她名叫艾丝琳。你会在酒馆找到她；若你运气好，正唱着歌。或许也在养嗓休息。$b', '将雪歌花送给克雷斯特海恩的艾丝琳。', '', '与艾丝琳交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175332, 'zhCN', '附魔小饰品', '你要上前线，对吧？$B$B恕我冒昧，我从你的装束作了这般揣测。我叫埃德伦。埃德伦·努布拉。$B$B若你前往雪歌谷，去王道……能为我弄几件霜鬃小饰品吗？$B$B我听过我们士兵讲的故事。那些恶魔仿佛隐了形，直到贴到你面前。$B$B我怀疑，除却身手，其中还涉有魔法。$B', '从雪歌谷的霜鬃伏击者身上收集十件附魔小饰品。', '', '将饰品带给埃德伦·努布拉', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175333, 'zhCN', '骨首之鸟', '<一尊石雕神像。刻画着某种鸟，其首唯余枯骨。>$B$B<埃德伦·努布拉会有兴趣研究它。>', '将霜鬃神像带给灰天的埃德伦·努布拉。', '', '与埃德伦·努布拉交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175334, 'zhCN', '给拔毛乌鸦的肉', '<拉马尔的目光落在壁炉上。塌陷的双肩与眼下的眼袋，道尽一个被击垮之人。>$b$b我们的肉用尽了，而肉向来是本店的招牌。$b$b霜鬃在王道游猎，灰天的猎人已有一阵子避开雪歌谷。$b$b<厨子匆匆打量你一眼。>$b$b你来是因为战争，我猜。那迟早你会去前线。届时记得我。给我带尽可能多的肉：熊、剑齿虎；都无所谓。', '在雪歌谷收集野兽肉。', '', '返回拉马尔·雷巴克处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175335, 'zhCN', '欢迎的代价', '你不是我们的一员。但若黛德丽容你在巴伊莱·埃斯卡达现身……那你便有权尝试挣得自己的一席之地。$B$B从村边林地给我们带些鹿肉来，我向你保证，你会在这里的艾尔迪尔中交到不止一个朋友。$B$B篝火旁一段好故事……一顿配得上战士的餐食……赢得我们的心，便是这般简单。', '从斯卡迪尔德古冢收集鹿肉。', '', '返回明德拉·罗布尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175336, 'zhCN', '给女巫的苔藓', '巴伊莱·埃斯卡达上方有座洞穴，那里生长着一种在斯卡迪尔德颇为罕见的苔藓。$B$B对像我这样的女巫而言，它极有用处。$B$B既然你反正要爬上去，不妨刮下些洞壁，给我带一把来。$B$B你觉得如何？', '从巴伊莱·埃斯卡达上方的洞穴采集暗影苔藓，带给黛德丽。', '', '将苔藓带给黛德丽', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175337, 'zhCN', '以奶换酒', '这就走了？$B$B抱歉戈林让你一直来回奔波。若你再路过尼维拉恩，请务必到舒适洞窟歇脚。$B$B你方才说你要去邓卡扎德？那样的话，或许你能帮我个忙。$B$B我得把这交给石辫。<达利尼尔提起满满一桶奶，龇牙咧嘴地递给你。>$B$B我牦牛的奶。它们在尼维拉恩产得比我们喝得还多，我便想……或许他会有兴趣买一些。至少时不时地。', '将那桶牦牛奶带给邓卡扎德的旅店老板石辫。', '', '与石辫交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175338, 'zhCN', '戈林的卷轴', '我还有最后一件事相求。$B$B别紧张，小子。这一件不必应付醉鬼，也不必清理牦牛粪。$B$B<戈林将一卷用丝带与橙色封蜡系住的卷轴递给你。>$B$B给邓卡扎德的学识守护者埃尔格伦·碎帆。她是我教团的领袖，而我研究进展寥寥，欠她一声抱歉。$B$B只怪酒实在不是好伙伴！$B$B这份文书便是我的歉意。$B', '将戈林的卷轴送给邓卡扎德的埃尔格伦·碎帆。', '', '与埃尔格伦·碎帆交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175339, 'zhCN', '白如艾尔德霜', '嘿，你！过来。$B$B你是外乡人，这意味着你迟早要再出去。我没说错吧？$B$B我有桩活，也有付酬的金币，若你有兴趣。$B$B<莫里克突然压低了声音。>$B$B我只需你给我带一张完美的艾尔德霜狐皮毛。我与妻子即将庆祝周年纪念，没什么比一件美丽的白色毛皮大衣更能讨她欢心了——就像这座城市贵妇们所披的那种。', '在邓卡扎德周边取得一张完美的艾尔德霜狐皮毛。', '', '将皮毛带给莫里克', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175340, 'zhCN', '无人送她鲜花', '这个……$B$B给。$B$B<杜拉克递给你一把花；大多明显已经蔫了。>$B$B给我母亲。在凯雷德-扎拉姆的墓地。湖边。$B$B无人给她送花了。而我父亲……唉。父亲在埃律德娜·石歌偷走他仅存的心之后，便将她忘了。$B$B墓碑上的名字是玛莎·阿戈斯。$B', '将杜拉克的鲜花带到凯雷德-扎拉姆墓地里玛莎·阿戈斯的坟前。', '', '返回杜拉克处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175341, 'zhCN', '治愈之手', '你已见识外头的情形了吧，不是吗？$B$B战争、死亡与混乱。无论我如何祈祷，都自觉帮不上忙。$B$B所幸我懂药草。凯雷德-扎拉姆一带生长着一种药用花，我可据此调制药膏，医治我们的伤员。$B$B若你办得到，给我采一打来。$B', '在凯雷德-扎拉姆周边采集雪镜花', '', '返回约维特里德处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175342, 'zhCN', '多半是张地毯', '初来安德拉斯特？$B$B我是达纳尔·戈雷特，以此地贵族议院代表之身到此。做什么，你问？自然是确保我们拨给这座要塞的款项用得其所。$B$B若你想赢得我与暴风城贵族的青睐，我有一桩任务给你：$B$B这些兽人的座狼是壮美的生灵。它们的皮毛能卖个国王赎金般的价钱。不止一位贵族乐意将一张制成地毯。$B$B杀几只，把皮带来给我。我会以我资助者闻名的慷慨付你报酬。', '在安德拉斯特与凯雷博尔周边收集黑色座狼皮毛。', '', '将皮毛带给达纳尔·戈雷特', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175343, 'zhCN', '无聊的和平', '你不是……达隆德。$B$B恕我。哈尔丁与我惯于与他打交道；除他常来探望外，这处圣所鲜少迎来新面孔。$B$B但此中正藏契机。我想将这封信送到我在灰天的兄弟阿尔卡里安手中。鉴于苍白海岸的局势，达隆德不敢踏上这趟旅程。$B$B而他本是个脚夫。你却是个 $C，除非我的眼睛被什么法术欺骗。$B$B<瓦埃洛尔打个响指，阿尔卡里安的信便出现在你口袋里。>$B', '将瓦埃洛尔的信带给灰天的阿尔卡里安。', '', '在灰天冷湖堡与阿尔卡里安交谈', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175344, 'zhCN', '无圣之死者', '此处出了岔子，彻头彻尾的岔子。$B$B没时间多言！$B$B我们必须将这等地怪物从这地方净化清除。', '击败在圣风墓穴中游荡的亡灵怪物。', '', '返回阿比盖尔处', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175345, 'zhCN', '正义或许盲目，却并非耳聋', '正义或许盲目，却并非耳聋。而我担心，我们修道院的人对这些盘踞悬崖的鹰，长久以来过分宽容了。$B$B这座神圣的建筑已被那些鸟儿的污秽亵渎。$B$B就在我准备下令之时，圣光恰如其分地将你派到了我面前。那绝非偶然。$B$B世上没有偶然。$B$B那么，你愿意去处置那些鹰吗？你愿意见证圣光意志的实现吗？$B', '击败在圣风修道院周围游荡的鹰', '', '返回忏悔者默恩', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175346, 'zhCN', '边境线上的密探', '还在这儿？$B$B<巴林发出一声疲惫的叹息，仿佛你的存在本身已成了一项政策议题。>$B$B好吧。既然这事儿似乎已刻进了你的紧迫感里，或许把消息传出去是审慎之举。当然，纯粹是出于预防。$B$B去卡拉诺斯，把你对我说的话告诉山地卫兵队长基尔达。让他确保消息送到艾达·甘巴德手中，并让我们边境的密探保持警惕。$B', '向卡拉诺斯的山地卫兵队长基尔达汇报，让他把消息传递给艾达·甘巴德，并提醒铁炉堡在边境线上的密探。', '', '与卡拉诺斯的山地卫兵队长基尔达交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175347, 'zhCN', '暗影矿石', '<仔细端详这块矿石，你注意到一种奇异的异常：一道既不属于石头、也不属于落在它身上的光线的「阴影」。>$b$B<在去找能够解读这一异常、并判断它是否与矿工遭遇之事有关的能人之前，多采集些样本是明智之举。>', '在铁枝矿洞采集暗影矿石，并找人分析它。', '', '与贝尔德雷德交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175348, 'zhCN', '带给灰天的消息', '我还有另一个任务给你。最后一件差事，配得上一位已被证明是邓卡扎德之友的人。$B$B你去过灰天，不是吗？<鲍格沃尔夫将军没等你就答。>很好，很好。$B$B我需要你向卫兵指挥官德雷文爵士汇报，告知他冬日之路上的局势。告诉他，我们正在尽一切所能，将霜鬃挡在桥的这一侧。$B$B还要告诉他深跑矿车遭破坏的麻烦事。$B$B去吧。他会想尽快得到我们的消息。', '向灰天的德雷文爵士汇报，告知他邓卡扎德的处境以及他们正面临的麻烦。', '', '向灰天的德雷文爵士汇报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175349, 'zhCN', '一剂痒痛良方', '你有兴趣在我们「祖母的良药」店里买的任何东西都享受终身折扣吗？$b$b那就听好了，因为我有一项任务，你只需会走路就行，无需其他才能。$b$b<希尔达递给你一个玻璃小瓶，里面装着明亮闪烁的液体。>$b$b我需要你把这个送到邓郡的乌莉拉·灰谷手中。如今路上情形如此，几乎没有什么商队离开灰天。而那位可怜的女人几周前就已订购了这瓶药膏。$b$b我甚至不敢想象，她的皮疹如今该恶化到什么地步了。', '将希尔达的药膏送给邓郡的乌莉拉·灰谷。', '', '与乌莉拉·灰谷交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(175350, 'zhCN', '温顺的牛群', '你。$b$b<泽尔达用俏皮的手势招呼你靠近。若她脸上的皱纹不那么深，你或许会以为她在向你调情。>$b$b我想请你帮个忙。姑且称之为一项「任务」吧。你会发现这是件极其简单的事：$b$b我需要你把这个护符带到暗影井村。更确切地说，是塞德温的马厩。$b$b他若说什么，别理他，把护符直接交给他的一头牛。哪一头？$b$b见到她时，你自然知道。本能会告诉你。', '将泽尔达的护符带到暗影井塞德温的马厩里那头牛那里。', '', '观察那头牛。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(176000, 'zhCN', '一块怪异的废料', '<这块废料还是温热的，散发着机油味。一侧印着半个被刮花的风险投资公司序列号，有人还在下面潦草地写了「原型——勿拾」。>$B$B工程师会知道这是什么。联盟在反抗军营地有一个，部落在格罗姆高营地有一个。', '将这块怪异的废料交给反抗军营地或格罗姆高营地的打捞工程师。', '', '将废料交给一名打捞工程师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(176001, 'zhCN', '地精的破烂', '那个序列号是风险投资的存货，其余的还在外面！地精们在这片丛林里掠夺木材和矿石，他们丢弃的机器比诺姆瑞根造过的还多。$B$B我能用他们的残骸组装出一台像样的打捞装置，但精密零件需要配件：从他们工人那里拿六个完好齿轮箱、从他们某台伐木机里取一个能量核心，还有他们在营地堆着的那种易燃燃料罐。最后那个请轻拿轻放。', '为菲泽尔·齿哨带回：6 个来自荆棘谷北部风险投资公司的回收齿轮箱、1 个来自风险投资公司伐木机的伐木机能量核心，以及 1 个来自风险投资公司营地的易燃燃料罐。', '', '返回菲泽尔·齿哨。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(176002, 'zhCN', '需要组装', '齿轮、动力、燃料……却还缺个脑子。我的逻辑核心总爱按气味给铜币分类。$B$B风险投资公司自己造了个拾荒原型，结果失控了。它在他们的营地巡逻，见什么捡什么，连钉住的都不放过。它的逻辑核心校准得无可挑剔。毁掉那台机器，把核心带给我。', '摧毁风险投资公司营地里的失控的战利品机器人原型，并将其校准逻辑核心带给菲泽尔·齿哨。', '', '返回菲泽尔·齿哨。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(176004, 'zhCN', '持照打捞助手', '八个完美样本！准备好了。$B$B有个问题：藏宝海湾拥有这片海岸的打捞权，没有执照的拾荒机器人最终只会变成雷维尔加兹男爵桌上的废铁。我填好了申请表。把它交给男爵，一旦盖上他的印章，这台拾荒机器人就是你的了。', '将打捞执照申请交给藏宝海湾的雷维尔加兹男爵。', '', '将申请表交给藏宝海湾的雷维尔加兹男爵。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(176011, 'zhCN', '地精的破烂', '风险投资公司的破烂！朋友，你知道那是什么吗？免费库存。那些风险投资的小子扔掉的利润比凯赞一年挣的还多。$B$B听着：一个机械搭档，你干苦力的时候它帮你捡战利品。我需要他们工人手里的六个能用的齿轮箱、某台伐木机里的一个能量核心，还有他们营地的一个燃料罐。那个可别晃。', '为格里兹克·窃屑带回：6 个来自荆棘谷北部风险投资公司的回收齿轮箱、1 个来自风险投资公司伐木机的伐木机能量核心，以及 1 个来自风险投资公司营地的易燃燃料罐。', '', '返回格里兹克·窃屑。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(176012, 'zhCN', '需要组装', '齿轮、动力、燃料：机身已完成。脑子才是最贵的部分。$B$B风险投资公司自己造了个抢货原型，结果弄丢了遥控器，现在正把他们的营地拆得乱七八糟。它的逻辑核心是顶级品质。砸了那玩意儿，把核心带给我，咱们就能省下数月的研究。', '摧毁风险投资公司营地里的失控的战利品机器人原型，并将其校准逻辑核心带给格里兹克·窃屑。', '', '返回格里兹克·窃屑。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(176014, 'zhCN', '持照打捞助手', '八个样本！咱们有产品了！$B$B一个小细节：藏宝海湾拥有此地的打捞权，雷维尔加兹男爵对一切都要抽成。我填好了执照申请。把它交给藏宝海湾的男爵，盖上他的章，这台拾荒机器人就全归你了。', '将打捞执照申请交给藏宝海湾的雷维尔加兹男爵。', '', '将申请表交给藏宝海湾的雷维尔加兹男爵。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(199999, 'zhCN', '游侠之道', '做一名游侠，不只是在$n手里抄起一把弓，或在树丛掩护下战斗。做一名游侠，其核心在于你与荒野之间有着深厚的羁绊。你是荒野的守护者。我派我的猎鹰乔去周围侦察，可他至今未归。请你找到他，指引他回到我身边。', '在北郡山谷一带找到欧文的猎鹰。', '', '在北郡山谷一带找到欧文的猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200000, 'zhCN', '一场突袭！', '附近的灌木丛中传来窸窣声。你遭到袭击了！', '杀死那只可疑的生物。', '', '照料那只猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200003, 'zhCN', '一场突袭！', '附近的灌木丛中传来窸窣声。你遭到袭击了！', '杀死那只可疑的生物。', '', '照料那只猎鹰。', NULL);
