(200012, 'zhCN', '一场突袭！', '附近的灌木丛中传来窸窣声。你遭到袭击了！', '杀死那只可疑的生物。', '', '照料那只猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200015, 'zhCN', '一场突袭！', '附近的灌木丛中传来窸窣声。你遭到袭击了！', '杀死那只可疑的生物。', '', '照料那只猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200001, 'zhCN', '猎鹰是朋友', '你在猎鹰身上发现一张字条，上面写着：<若你读到这番话，说明你已经找到了我的朋友。这张字条上附着一个小小红瓶。若他受了伤，就把它给他，他自会知道下一步该怎么做。>', '对猎鹰使用红色药剂瓶。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
