(200016, 'zhCN', '猎鹰是朋友', '你在猎鹰身上发现一张字条，上面写着：<若你读到这番话，说明你已经找到了我的朋友。这张字条上附着一个小小红瓶。若他受了伤，就把它给他，他自会知道下一步该怎么做。>', '对猎鹰使用红色药剂瓶。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200002, 'zhCN', '游侠之道', '做一名游侠，不只是在$n手里抄起一把弓，或在树丛掩护下战斗。做一名游侠，其核心在于你与荒野之间有着深厚的羁绊。你是荒野的守护者。我派我的猎鹰塔洛斯去周围侦察，可他至今未归。请你找到他，指引他回到我身边。', '在寒脊山谷找到巴胡尔的猎鹰。', '', '在寒脊山谷找到巴胡尔的猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200005, 'zhCN', '游侠之道', '做一名游侠，不只是在$n手里抄起一把弓，或在树丛掩护下战斗。做一名游侠，其核心在于你与荒野之间有着深厚的羁绊。你是荒野的守护者。我派我的猎鹰布里姆去周围侦察，可他至今未归。请你找到他，指引他回到我身边。', '在幽影谷找到海德里尔的猎鹰。', '', '在幽影谷找到海德里尔的猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200008, 'zhCN', '游侠之道', '做游侠，可不只是抄起把弓、$n，或躲树后头打架。说到底，做游侠意味着你与荒野有着深切的羁绊。你是它的守护者。我派我的猎鹰比基去周围侦察，可他至今未归。请你找到他，指引他回到我身边。', '在试炼谷找到你的塔杜恩的猎鹰。', '', '在试炼谷找到你的塔杜恩的猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200011, 'zhCN', '游侠之道', '做一名游侠，不只是在$n手里抄起一把弓，或在树丛掩护下战斗。做一名游侠，其核心在于你与荒野之间有着深厚的羁绊。你是荒野的守护者。我派我的猎鹰费洛去周围侦察，可他至今未归。请你找到他，指引他回到我身边。', '在周围区域找到克拉莉斯的猎鹰。', '', '在周围区域找到克拉莉斯的猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200014, 'zhCN', '游侠之道', '做一名游侠，不只是在$n手里抄起一把弓，或在树丛掩护下战斗。做一名游侠，其核心在于你与荒野之间有着深厚的羁绊。你是荒野的守护者。我派我的猎鹰基德去周围侦察，可他至今未归。请你找到他，指引他回到我身边。', '在红云台地找到纳瓦特的猎鹰。', '', '在红云台地找到纳瓦特的猎鹰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200017, 'zhCN', '鲜血即力量', '啊，$C。你期盼的日子终于来了。鲜血。到了这一步，你总该以某种方式对它不再陌生。鲜血即是生命。但正如你即将学到的，鲜血也是力量。我想让你想象，在一个你能掌控他人躯壳中生命精华的世界里，你将有何种能耐。只要手腕一抖，便能将他们的内脏碾碎……令人沉醉。假以时日，你会学到更多。眼下，我需要你协助我推进自己的研究，而借此我也能助你修习。附近有一本典籍，本地那伙匪徒也已窥得其中奥秘，而我研究正需要它。他们之中有人拿着我的书——一位血法师。替我取来，我确信他们身上就带着。', '从迪菲亚血法师手中取得鲜血之书。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200018, 'zhCN', '鲜血即力量', '啊，$C。你期盼的日子终于来了。鲜血。到了这一步，你总该以某种方式对它不再陌生。鲜血即是生命。但正如你即将学到的，鲜血也是力量。我想让你想象，在一个你能掌控他人躯壳中生命精华的世界里，你将有何种能耐。只要手腕一抖，便能将他们的内脏碾碎……令人沉醉。假以时日，你会学到更多。眼下，我需要你协助我推进自己的研究，而借此我也能助你修习。附近有一本典籍，被小劣魔营地里一个可疑的暗夜精灵握在手中，我研究正需要它。替我取来。', '从那个可疑的暗夜精灵手中取得鲜血之书。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200019, 'zhCN', '鲜血即力量', '啊，$C。你期盼的日子终于来了。鲜血。到了这一步，你总该以某种方式对它不再陌生。鲜血即是生命。但正如你即将学到的，鲜血也是力量。我想让你想象，在一个你能掌控他人躯壳中生命精华的世界里，你将有何种能耐。只要手腕一抖，便能将他们的内脏碾碎……令人沉醉。假以时日，你会学到更多。眼下，我需要你协助我推进自己的研究，而借此我也能助你修习。附近有一本典籍，被一个在附近废弃房屋里翻找的可疑血精灵所得，我研究正需要它。替我取来。', '从那个可疑的血精灵手中取得鲜血之书。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200020, 'zhCN', '鲜血即力量', '啊，$C。你期盼的日子终于来了。鲜血。到了这一步，你总该以某种方式对它不再陌生。鲜血即是生命。但正如你即将学到的，鲜血也是力量。我想让你想象，在一个你能掌控他人躯壳中生命精华的世界里，你将有何种能耐。只要手腕一抖，便能将他们的内脏碾碎……令人沉醉。假以时日，你会学到更多。眼下，我需要你协助我推进自己的研究，而借此我也能助你修习。附近有一本典籍，在小鬼游荡的那个洞穴里，被一个古怪的巨魔握着，我研究正需要它。替我取来，我确信他们身上就带着。', '从那个神秘的巨魔手中取得鲜血之书。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200021, 'zhCN', '步入恶魔之境', '于是，一切开始了。幸会，$N。我已然看出，你已开始感受到在血脉中燃烧的残余邪能。我羡慕你，曾几何时，我也未曾像如今这般习惯它。你是邪誓者，正因如此，你处在凡俗与恶魔之辈的边界。然而，与某些人不同，你我不会堕入邪能魔法所设的权力陷阱——太多其他修行者都陷了进去，往往还浑然不觉。或许有朝一日，你甚至会强大到化身为恶魔形态，但眼下，你的邪能强化便足以激发你真正的潜能，令你获益良多。让我说清楚：部落与联盟对我们毫无用处，但为了实现我们更宏大的目标，必须让他们相信我们是盟友。切勿忘记这一点。当一切到了紧要关头，别忘了你真正的忠诚所在。现在，来一场考验。一具名为洛克的强大恶魔的颅骨已被放置在附近区域。替我找来。', '取回洛克的头骨。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200022, 'zhCN', '步入恶魔之境', '于是，一切开始了。幸会，$N。我已然看出，你已开始感受到在血脉中燃烧的残余邪能。我羡慕你，曾几何时，我也未曾像如今这般习惯它。你是邪誓者，正因如此，你处在凡俗与恶魔之辈的边界。然而，与某些人不同，你我不会堕入邪能魔法所设的权力陷阱——太多其他修行者都陷了进去，往往还浑然不觉。或许有朝一日，你甚至会强大到化身为恶魔形态，但眼下，你的邪能强化便足以激发你真正的潜能，令你获益良多。让我说清楚：部落与联盟对我们毫无用处，但为了实现我们更宏大的目标，必须让他们相信我们是盟友。切勿忘记这一点。当一切到了紧要关头，别忘了你真正的忠诚所在。现在，来一场考验。一具名为卡兹的强大恶魔的颅骨已被放置在附近区域。替我找来。', '取回卡兹的头骨。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200023, 'zhCN', '步入恶魔之境', '于是，一切开始了。幸会，$N。我已然看出，你已开始感受到在血脉中燃烧的残余邪能。我羡慕你，曾几何时，我也未曾像如今这般习惯它。你是邪誓者，正因如此，你处在凡俗与恶魔之辈的边界。然而，与某些人不同，你我不会堕入邪能魔法所设的权力陷阱——太多其他修行者都陷了进去，往往还浑然不觉。或许有朝一日，你甚至会强大到化身为恶魔形态，但眼下，你的邪能强化便足以激发你真正的潜能，令你获益良多。让我说清楚：部落与联盟对我们毫无用处，但为了实现我们更宏大的目标，必须让他们相信我们是盟友。切勿忘记这一点。当一切到了紧要关头，别忘了你真正的忠诚所在。现在，来一场考验。一具名为帕克斯的强大恶魔的颅骨已被放置在附近区域。替我找来。', '取回帕克斯的头骨。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200024, 'zhCN', '毒染世界', '欢迎，$C。这么说，你是来「下毒于井」的咯？我向来乐意教导毒艺领域中崭露头角的新晋大师，但作为回报，我偶尔也需要你帮个忙。这没问题吧？看看你四周。各色市民皆有。但他们纯净无瑕，这很好，他们尚未被玷污。我这里有一剂我亲手调制的药水。它的效用，你无需操心。我需要你将它泼在三个特定的人身上：其一，阳语者塔蕾西娅；其二，贝利·怖恨；其三，多纳尔·织瘟。此事办妥后回来找我，我定不让你的时间白费。', '将神秘药剂泼洒在附近的市民身上。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200025, 'zhCN', '毒染世界', '欢迎，$C。这么说，你是来「下毒于井」的咯？我向来乐意教导毒艺领域中崭露头角的新晋大师，但作为回报，我偶尔也需要你帮个忙。这没问题吧？看看你四周。各色市民皆有。但他们纯净无瑕，这很好，他们尚未被玷污。我这里有一剂我亲手调制的药水。它的效用，你无需操心。我需要你将它泼在三个特定的人身上：其一，艾克索达人·特卢萨拉；其二，哈伦多尔·屠暗者；其三，奥金尼的巴拉兰。此事办妥后回来找我，我定不让你的时间白费。', '将神秘药剂泼洒在附近的市民身上。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200026, 'zhCN', '毒染世界', '欢迎，$C。这么说，你是来「往井里下毒」的咯？我向来乐意教导毒艺领域中崭露头角的新晋大师，但作为回报，我偶尔也需要你帮个忙。这没问题吧？看看你四周。各色市民皆有。但他们纯净无瑕，这很好，他们尚未被玷污。我这里有一剂我亲手调制的药水。它的效用，你无需操心。我需要你将它泼在三个特定的人身上：其一，潘加乔·阳视；其二，奥莫古尔格·持真者；其三，克拉加尔·复生者。此事办妥后回来找我，我定不让你的时间白费。', '将神秘药剂泼洒在附近的市民身上。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200027, 'zhCN', '医生在此！', '欢迎，$C。我看得出来，你已与西莱图斯的力量相当熟稔了。让我来指引你，朋友。我有一项任务，而且还是至关重要的那种。据我们的斥候说，我有一位朋友在矿井下受了伤。我方才才得到消息，本已打算动身，但我觉得这任务交给如你一般的人再合适不过。找到我的朋友，用你洛阿之酿的力量治愈他，然后回到我这里。', '用 1 级洛阿之酿治疗你训练师受伤的朋友。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200028, 'zhCN', '谁喊了医生？', '太感谢你了，朋友！有些狗头人真不友善，他们欺负小瓦''祖，只因他做自己。让我说清楚：狗头人只想挖矿。我们敲石头、制蜡烛、探索世界。我的同胞们，我们不明白为何有些人恨我们。我们并非有意惹人厌。抱歉。我感谢那些没有伤害我的好朋友……替我谢谢你的朋友照顾我，也谢谢你的帮助！哦……不，等等。看你的背后！他回来了！！！', '杀死那个欺负小瓦''祖的狗头人！', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200029, 'zhCN', '医生在此！', '祖格祖格，$C。我看得出来，你已与西莱图斯的力量相当熟稔了。让我来指引你，伙计。我有一项任务，而且还是至关重要的那种。据我们的斥候说，我有一位朋友在沙漠外被蝎子所伤。我方才才得到消息，本已打算动身，但我觉得这任务交给如你一般的人再合适不过。他是个强壮的巨魔，巨魔中的巨魔。老实说，许多人被那些该死的蝎子所伤。但无论如何，保持警觉。找到我的朋友，用你洛阿之酿的力量治愈他，然后回到我这里。', '用 1 级洛阿之酿治疗你训练师受伤的朋友。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200030, 'zhCN', '谁喊了医生？', '我的同胞们在外头设法对付那些蝎子的事。这比看上去更危险。我并非第一个受伤的。我只能向洛阿祈祷，自己没有被毒到。但我的确受了伤。谢谢你治愈了我，伙计。哦，不！看你的背后，伙计！有只蝎子回来要完成任务了！', '杀死蝎潜行者。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200031, 'zhCN', '医生在此！', '祖格祖格，$C。我看得出来，你已与西莱图斯的力量相当熟稔了。让我来指引你，伙计。我有一项任务，而且还是至关重要的那种。据我们的斥候说，我有一位朋友在沙漠外被蝎子所伤。我方才才得到消息，本已打算动身，但我觉得这任务交给如你一般的人再合适不过。他是个强壮的巨魔，巨魔中的巨魔。老实说，许多人被那些该死的蝎子所伤。但无论如何，保持警觉。找到我的朋友，用你洛阿之酿的力量治愈他，然后回到我这里。', '用 1 级洛阿之酿治疗你训练师受伤的朋友。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200032, 'zhCN', '姆莎的勇士', '科多伊什，$N。看来姆莎并未将你遗忘，很好，正缺你这般受眷顾之人。作为唤星者，我们是姆莎的勇士，正因如此，我们必须贯彻她的意志——无论它领我们去向何方，无论它究为何物。然而，当这片土地沉浸在和平之中时，人也须学会依旧向姆莎致以敬意，如此当大地再度充斥战争与绝望时，她才会现身指引我们。前往山中供奉姆莎的神龛朝圣，静心冥想，向女神致敬，然后回到我身边。', '前往供奉姆莎的古老神龛赞颂姆莎。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200033, 'zhCN', '艾露恩的勇士', '巴尔阿·达什，马拉诺雷，$N。看来艾露恩并未将你遗忘，很好，正缺你这般受眷顾之人。作为唤星者，我们是艾露恩的勇士，正因如此，我们必须贯彻她的意志——无论它领我们去向何方，无论它究为何物。然而，当这片土地沉浸在和平之中时，人也须学会依旧向艾露恩致以敬意，如此当大地再度充斥战争与绝望时，她才会现身指引我们。在北面的山中，有一座古老的雕像，纪念泰兰德亲率部队登陆东部王国之时——那是对天灾本身的直击，也助了我的族裔。自雕像立起后，它已倾颓并被遗忘。但它仍是艾露恩追随者的朝圣之地。去那里，静心冥想，向女神致敬，然后回到我身边。', '找到那座倒下的雕像并赞颂艾露恩。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200034, 'zhCN', '内心的恶魔', '啊哈，$N，欢迎，你可喜欢自己这副凡人的皮囊？对我们而言，向艾泽拉斯施放地狱之火的时候到了，一步步来。你心知肚明，我们人数有限，但假以时日，我们的队伍会壮大。我想不必提醒你——部落的苦难并非你的首要关切，想必你也明白。他们不过是一件工具、一面盾牌，好让我们推进自己的目标。每一步、每一刻，我们都须给这个世界制造浩劫，却又绝不能暴露我们的秘密——我们乃恶魔——正因如此，我有一桩小任务交给你。有个苦工，懒到无可救药，任你如何威逼，都休想让他干活。我在此受上级之命处置他。我们可以给他加薪，可以拿棍子打到他听话，甚至干脆劝他去干活。但是……杀了他吧，他怎么死的，我们编个借口便是。多半说是蝎子袭击。', '杀死那个懒到无可救药的苦工。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200035, 'zhCN', '内心的恶魔', '啊哈，$N，欢迎，你可喜欢自己这副凡人的皮囊？对我们而言，向艾泽拉斯施放地狱之火的时候到了，一步步来。你心知肚明，我们人数有限，但假以时日，我们的队伍会壮大。我想不必提醒你——部落的苦难并非你的首要关切，想必你也明白。他们不过是一件工具、一面盾牌，好让我们推进自己的目标。每一步、每一刻，我们都须给这个世界制造浩劫，却又绝不能暴露我们的秘密——我们乃恶魔——正因如此，我有一桩小任务交给你。有个人在死亡之痕惹是生非。他一醒过来，便横冲直撞地制造破坏。我在此受上级之命处置他。换作平时，我倒会和这种人做朋友，但我们必须装出站在他们那边的样子。杀了他吧，他怎么死的，我们编个借口便是。', '杀死那个疯狂的亡灵。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200036, 'zhCN', '内心的恶魔', '啊哈，$N，欢迎，你可喜欢自己这副凡人的皮囊？对我们而言，向艾泽拉斯施放地狱之火的时候到了，一步步来。你心知肚明，我们人数有限，但假以时日，我们的队伍会壮大。我想不必提醒你——联盟的苦难并非你的首要关切，想必你也明白。他们不过是一件工具、一面盾牌，好让我们推进自己的目标。每一步、每一刻，我们都须给这个世界制造浩劫，却又绝不能暴露我们的秘密——我们乃恶魔——正因如此，我有一桩小任务交给你。有个本不该在此的萨特。他正给幽影谷的当地居民惹麻烦。我在此受上级之命处置他。杀了他吧，此处的人可不容萨特。', '杀死幽影谷的萨特欺诈者。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200037, 'zhCN', '暗影界之召', '再敢看我的头盔时咧嘴一笑，我就把这些刀插进你的胸膛，$N。……你倒是有胆量。我感应到，你来我这里是为了求教。今天我确有一桩简单的任务给你，年轻的$C。山谷里有个行将就木之人。盛年时，他是战场上的巨兽，取过许多性命。可如今，他在山谷自己的家中过着恬淡的日子。他终将死去，暗影界会收走他。但今天还不是他的死期。然而，我能感受到他渴望离开这个位面，却不知自己离去后将面临什么。你或许没料到这样的任务，但我恳请你去拜访他，与他聊聊。', '拜访北郡山谷的詹金斯老汉。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200038, 'zhCN', '暗影界之召', '欢迎，$C。我听闻了许多关于你来到幽影谷的事。我有许多可教你。但你来得正是时候，因为我有一项特别的任务交给你。在奥达希尔，有位行将就木的老年精灵。盛年时，他是战场上的巨兽，取过许多性命。可如今，他在奥达希尔过着恬淡的日子。他终将死去，暗影界会收走他。但今天还不是他的死期。然而，我能感受到他渴望离开这个位面，却不知自己离去后将面临什么。你或许没料到这样的任务，但我恳请你去拜访他，与他聊聊。', '拜访奥达希尔的萨拉多尔。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200039, 'zhCN', '暗影界之召', '再敢看我的头盔时咧嘴一笑，我就把这把刀插进你的胸膛，$N。 ……你倒是有胆量。我感应到，你来我这里是为了求教。今天我确有一桩简单的任务给你，年轻的$C。在死亡之痕，有个人，可以说，本已行将就木，却被天灾杀死，又再度爬起。他终将死去，这一次，暗影界会收走他。但今天还不是他的死期。然而，我能感受到他渴望离开这个位面，却不知自己离去后将面临什么。你或许没料到这样的任务，但我恳请你去拜访他，与他聊聊。', '拜访死亡之痕的达林·索夫特。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200040, 'zhCN', '死亡之召', '幸会，$C。很高兴你今日能来墓地与我作伴。天气真好，不是吗？看来你已与不死之身打过交道，你唤起亡者的能力令我印象深刻。或许你能为我所用，想必你也不会介意。我欲召唤一具格外强大的亡灵，却不敢亲自尝试——我实在太重要了。而你，若在此成功，必能学得不少。若你失败了呢？我便将你收作我的亡者。不必多想。让我在你的地图上标出仪式举行的地点。你必须收集特定物品方能完成仪式。去吧。', '找到并与仪式法阵互动。', '', '与仪式法阵互动。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200043, 'zhCN', '死亡之召', '幸会，$C。很高兴你今日能来墓地与我作伴。天气真好，不是吗？看来你已与不死之身打过交道，你唤起亡者的能力令我印象深刻。或许你能为我所用，想必你也不会介意。我欲召唤一具格外强大的亡灵，却不敢亲自尝试——我实在太重要了。而你，若在此成功，必能学得不少。若你失败了呢？我便将你收作我的亡者。不必多想。让我在你的地图上标出仪式举行的地点。你必须收集特定物品方能完成仪式。去吧。', '找到并与仪式法阵互动。', '', '与仪式法阵互动。', NULL);
