REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200041, 'zhCN', '死亡在呼唤', '仪式法阵旁的地上有张字条。为召唤那具亡灵巨怪，我须将以下材料带到法阵处：——骨头——新鲜血肉——颅骨。附近的迪菲亚匪徒正好有需要的东西。', '杀死迪菲亚匪徒，并掠夺他们的骨头、血肉与颅骨。', '', '返回仪式法阵。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200042, 'zhCN', '亡者之召', '<材料化作一缕青烟，消散进仪式法阵> ……似乎有些不对劲。召唤失败了，再检查一遍仪式法阵。但小心些，它不稳定。', '杀死那具亡灵巨怪。', '', '返回你的训练师。', NULL);
