REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200044, 'zhCN', '死亡在呼唤', '为召唤那具亡灵巨怪，我须将以下材料带到仪式法阵处：——骨头——新鲜血肉——颅骨。附近的穴居人正好有需要的东西。', '杀死穴居人，并掠夺他们的骨头、血肉与颅骨。', '', '返回仪式法阵。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200047, 'zhCN', '死亡在呼唤', '为召唤那具亡灵巨怪，我须将以下材料带到仪式法阵处：——骨头——新鲜血肉——颅骨。附近的小劣魔正好有需要的东西。', '杀死小劣魔，并掠夺他们的骨头、血肉与颅骨。', '', '返回仪式法阵。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200049, 'zhCN', '死亡之召', '祖格祖格，$C。很高兴你今日能来墓地与我作伴。今日天气不错，不是吗？看来你已与不死之身打过交道，你唤起亡者的能力令我印象深刻。或许你能为我所用，想必你也不会介意。我欲召唤一具格外强大的亡灵，却不敢亲自尝试——我实在太重要了。而你，若在此成功，必能学得不少。若你失败了呢？我便将你收作我的亡者。不必多想。让我在你的地图上标出仪式举行的地点。你必须收集特定物品方能完成仪式。去吧。', '找到并与仪式法阵互动。', '', '与仪式法阵互动。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200050, 'zhCN', '死亡在呼唤', '为召唤那具亡灵巨怪，我须将以下材料带到仪式法阵处：——骨头——新鲜血肉——颅骨。附近的邪恶小鬼正好有需要的东西。', '杀死邪恶小鬼，并掠夺他们的骨头、血肉与颅骨。', '', '返回仪式法阵。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200053, 'zhCN', '死亡在呼唤', '为召唤那具亡灵巨怪，我须将以下材料带到仪式法阵处：——骨头——新鲜血肉——颅骨。附近的食尸鬼正好有需要的东西。', '杀死食尸鬼，并掠夺他们的骨头、血肉与颅骨。', '', '返回仪式法阵。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200055, 'zhCN', '狩猎开始', '我能感到一股邪恶的存在。你也感觉到了，对吧？这正是你在最恰当时机来到我面前的缘由。这里有一个。一个女巫。满腹邪恶与恶意地蛰伏着。愿圣光庇佑我们将要做的事。来，拿着这支火把。她就在附近，我已在你的地图上标出了她的位置。用火把照她，揭穿她的真身。杀了她。绝不手软。待她伏诛后回来找我。该死的女巫。', '揭穿女巫并杀死她。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200056, 'zhCN', '狩猎开始', '我能感到一股邪恶的存在。你也感觉到了，对吧？这正是你在最恰当时机来到我面前的缘由。这里有一个。一个女巫。满腹邪恶与恶意地蛰伏着。愿圣光庇佑我们将要做的事。来，拿着这支火把。她就在附近，我已在你的地图上标出了她的位置。用火把照她，揭穿她的真身。杀了她。绝不手软。待她伏诛后回来找我。该死的女巫。', '揭穿女巫并杀死她。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200057, 'zhCN', '狩猎开始', '我能感到一股邪恶的存在。你也感觉到了，对吧？这正是你在最恰当时机来到我面前的缘由。这里有一个。一个女巫。满腹邪恶与恶意地蛰伏着。愿圣光庇佑我们将要做的事。来，拿着这支火把。她就在附近，我已在你的地图上标出了她的位置。用火把照她，揭穿她的真身。杀了她。绝不手软。待她伏诛后回来找我。该死的女巫。', '揭穿女巫并杀死她。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200058, 'zhCN', '遗失的坠饰', '幸会，$C。你来得正是时候。我遗失了一枚颇为强大的坠饰。说「遗失」或许不太贴切，但唉，我们最好别在字眼上纠缠。嗯，既然你要帮我，我想至少该向你说明发生了什么。事情是这样的：我试图感化当地的迪菲亚，让他们追随安舍之阳，并向他们阐明其与圣光的关联……可他们并不领情，把我赶走了。慌乱之中，我弄丢了我的坠饰。求你，替我找回来。', '找到遗失的坠饰。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200060, 'zhCN', '遗失的坠饰', '幸会，$C。你来得正是时候。我遗失了一枚颇为强大的坠饰。说「遗失」或许不太贴切，但唉，我们最好别在字眼上纠缠。嗯，既然你要帮我，我想至少该向你说明发生了什么。事情是这样的：我在铁炉峰以南扎营，试图侦察当地的穴居人种群。不幸的是，有天夜里我熟睡时遭他们一群人伏击，被赶出营地，营帐也被洗劫。慌乱之中，我弄丢了我的坠饰。求你，替我找回来。', '找到遗失的坠饰。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200061, 'zhCN', '遗失的坠饰', '幸会，$C。你来得正是时候。我遗失了一枚颇为强大的坠饰。说「遗失」或许不太贴切，但唉，我们最好别在字眼上纠缠。嗯，既然你要帮我，我想至少该向你说明发生了什么。事情是这样的：我试图向小劣魔展示，他们同样也能皈依圣光……但结果并不妙。他们把我赶出营地，我险些没能活着逃出来。慌乱之中，我弄丢了我的坠饰。求你，替我找回来。', '找到遗失的坠饰。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200062, 'zhCN', '遗失的坠饰', '幸会，$C。你来得正是时候。我遗失了一枚颇为强大的坠饰。说「遗失」或许不太贴切，但唉，我们最好别在字眼上纠缠。嗯，既然你要帮我，我想至少该向你说明发生了什么。事情是这样的：我试图向当地营地的血色十字军证明，我们可携手合作，因为我们都追随圣光。他们并不领情，把我赶出了营地……慌乱之中，我弄丢了我的坠饰。求你，替我找回来。', '找到遗失的坠饰。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200064, 'zhCN', '遗失的坠饰', '幸会，$C。你来得正是时候。我遗失了一枚颇为强大的坠饰。说「遗失」或许不太贴切，但唉，我们最好别在字眼上纠缠。嗯，既然你要帮我，我想至少该向你说明发生了什么。事情是这样的：我试图向那些猪人展示圣光……没有奏效。他们并不领情，把我赶出了营地……慌乱之中，我弄丢了我的坠饰。求你，替我找回来。', '找到遗失的坠饰。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200065, 'zhCN', '巧思卓绝！', '哎呀我的天！你好啊，邻居！我看你是个爱鼓捣机械的料，说实在的，我正盼着找你这样的人。我正试着造一种特别的枪，有人管它叫土制枪，可我还缺点金属。狗头人营地附近有些金属，可以用来给你我造把枪。替我收集一些，我这就去鼓捣起来！', '收集 3 个废料金属。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200066, 'zhCN', '巧思卓绝！', '哎呀我的天！你好啊！$N，是吧？？我看你是个爱鼓捣机械的料，说实在的，我正盼着找你这样的人。我正试着造一种特别的枪，有人管它叫土制枪，可我还缺点金属。那些被穴居人盘踞的废弃营地附近有些金属，可以用来给你我造把枪。替我收集一些，我这就去鼓捣起来！', '收集 3 个废料金属。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200067, 'zhCN', '巧思卓绝！', '幸会。$N，是吧？欢迎来到奥达希尔。你似乎是个爱鼓捣机械的料，说实在的，我正盼着找你这样的人。我正试着造一种特别的枪，有人管它叫土制枪，可我还缺点金属。小劣魔营地附近有些金属，可以用来给你我造把枪。替我收集一些，我这就去鼓捣起来！', '收集 3 个废料金属。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200068, 'zhCN', '巧思卓绝！', '祖格，祖格，$N。今日，我要证明兽人的巧思。洛克塔·欧加！我要造一把枪给自己，若你助我，也给你造一把！小鬼洞穴里有些金属，可以用来给你我造枪。替我收集一些，我便造枪。', '收集 3 个废料金属。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200069, 'zhCN', '巧思卓绝！', '幸会，$N。我见你四处乱晃，正有一桩配得上你这般才智的任务。我是一名机械师，这点先说清楚。你？我不敢断言，但或许你今日能证明自己机械师的身份。我想给自己造一种特别的枪，有你相助，也能给你造一把。血色营地附近有些金属，尤其是在他们首领的帐篷内外，可用来给你我造枪。替我收集一些，我这就去鼓捣起来！', '收集 3 个废料金属。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200071, 'zhCN', '走向疯狂！', '你来得最是时候，$N。我听到了彼岸的低语。它告诉我，有个对我们事业格外危险的人物。我需要你迅速将其铲除。若你办成，我将赏你一件配得上上古之神信徒的武器。你要找的那人就在本地的教堂里，在图书馆翼某处。他名叫「萨缪尔兄弟」。结果了他。', '杀死萨缪尔兄弟。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200072, 'zhCN', '走向疯狂！', '你来得最是时候，$N。我听到了彼岸的低语。它告诉我，有个对我们事业格外危险的人物。我需要你迅速将其铲除。若你办成，我将赏你一件配得上上古之神信徒的武器。你要找的那人就在铁炉峰内等候。他名叫「布罗莫斯·格朗纳」。结果了他。', '杀死布罗莫斯·格朗纳。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200073, 'zhCN', '走向疯狂！', '你来得最是时候，$N。我听到了彼岸的低语。它告诉我，有个对我们事业格外危险的人物。我需要你迅速将其铲除。若你办成，我将赏你一件配得上上古之神信徒的武器。你要找的那人就在奥达希尔内，我想是在外头某处。她名叫「阿莉西娅」。结果了她。', '杀死阿莉西娅。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200074, 'zhCN', '走向疯狂！', '祖格，祖格，你来得最是时候，$N。我听到了彼岸的低语。它告诉我，有个对我们事业格外危险的人物。我需要你迅速将其铲除。若你办成，我将赏你一件配得上上古之神信徒的武器。你要找的那人就在洞穴外头，在巫医附近某处。他名叫「肯''贾伊」。结果了他。', '杀死肯''贾伊。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200075, 'zhCN', '走向疯狂！', '你来得最是时候，$N。我听到了彼岸的低语。它告诉我，有个对我们事业格外危险的人物。我需要你迅速将其铲除。若你办成，我将赏你一件配得上上古之神信徒的武器。你要找的那人就在旅店里。他名叫「丹纳尔·斯特恩」。结果了他。', '杀死丹纳尔·斯特恩。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200076, 'zhCN', '走向疯狂！', '你来得最是时候，$N。我听到了彼岸的低语。它告诉我，有个对我们事业格外危险的人物。我需要你迅速将其铲除。若你办成，我将赏你一件配得上上古之神信徒的武器。你要找的那人就在本地的酋长小屋里。他名叫「奥纳科娜·战心」。结果了他。', '杀死奥纳科娜·战心。', '', '返回你的训练师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200077, 'zhCN', '宁静的生活', '欢迎加入圣序，$N。我一直在等候你的到来。作为圣殿骑士，我们已臻至神圣信仰的最高阶序，正因如此，我们肩上的责任颇重。圣骑士与牧师与我们并肩，借圣光维系这世间的和平；我们虽各有微妙不同，却都盼望着再度将光辉带回艾泽拉斯。纵使其间险阻重重。我们的道路或许不同，但有人或许会说它更为严苛。身为圣殿骑士，意味着对情绪、战斗节奏与心智保持着极其精准的掌控。为保持身心康健，我喜爱在北郡山谷的瀑布下冥想。那里有一座雕像，纪念联盟一位陨落的英雄，而正是在那里，我寻得冥想的安宁。你必须凭借敏捷的身法抵达那座雕像。请你亲自前往那处。归来时，告诉我你有何体验。', '探访北郡山谷的瀑布。', '', '探访北郡山谷的瀑布。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200079, 'zhCN', '宁静的生活', '欢迎加入圣序，$N。我一直在等候你的到来。作为圣殿骑士，我们已臻至神圣信仰的最高阶序，正因如此，我们肩上的责任颇重。圣骑士与牧师与我们并肩，借圣光维系这世间的和平；我们虽各有微妙不同，却都盼望着再度将光辉带回艾泽拉斯。纵使其间险阻重重。我们的道路或许不同，但有人或许会说它更为严苛。身为圣殿骑士，意味着对情绪、战斗节奏与心智保持着极其精准的掌控。为保持身心康健，我喜爱在一座山丘上冥想——第三次战争后，几位造访的圣骑士为纪念一位强大的圣骑士，在那儿立了一座雕像。请你亲自前往那处。归来时，告诉我你有何体验。', '探访幽影谷乌瑟尔的雕像。', '', '探访幽影谷乌瑟尔的雕像。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200080, 'zhCN', '宁静的生活', '祖格祖格，$N。我一直在等候你的到来。作为圣殿骑士，我们已臻至神圣信仰的最高阶序，正因如此，我们肩上的责任颇重。圣骑士与牧师与我们并肩，借圣光维系这世间的和平；我们虽各有微妙不同，却都盼望着再度将光辉带回艾泽拉斯。纵使其间险阻重重。我们的道路或许不同，但有人或许会说它更为严苛。身为圣殿骑士，意味着对情绪、战斗节奏与心智保持着极其精准的掌控。为保持身心康健，我喜爱在一座强大圣骑士的雕像旁冥想——第三次战争后，我们圣序为纪念他，在此秘密立像。要抵达那里，你得施展敏捷的身法。请你亲自前往那处。归来时，告诉我你有何体验。', '探访试炼谷南部群山中那座隐秘的雕像。', '', '探访试炼谷南部群山中那座隐秘的雕像。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200081, 'zhCN', '宁静的生活', '幸会，$N。我一直在等候你的到来。作为圣殿骑士，我们已臻至神圣信仰的最高阶序，正因如此，我们肩上的责任颇重。圣骑士与牧师与我们并肩，借圣光维系这世间的和平；我们虽各有微妙不同，却都盼望着再度将光辉带回艾泽拉斯。纵使其间险阻重重。我们的道路或许不同，但有人或许会说它更为严苛。身为圣殿骑士，意味着对情绪、战斗节奏与心智保持着极其精准的掌控。为保持身心康健，我喜爱在一座曾强大无比的圣骑士的雕像旁冥想——第三次战争后，它在此被秘密立起。它被藏在山间的一道裂隙中，要抵达那里，你得施展敏捷的身法。请你亲自前往那处。归来时，告诉我你有何体验。', '探访死亡之痕西部群山中那座隐秘的雕像。', '', '探访死亡之痕西部群山中那座隐秘的雕像。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
