REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200083, 'zhCN', '宁静的生活', '欢迎加入圣序，$N。我一直在等候你的到来。作为圣殿骑士，我们已臻至神圣信仰的最高阶序，正因如此，我们肩上的责任颇重。圣骑士与牧师与我们并肩，借圣光维系这世间的和平；我们虽各有微妙不同，却都盼望着再度将光辉带回艾泽拉斯。纵使其间险阻重重。我们的道路或许不同，但有人或许会说它更为严苛。身为圣殿骑士，意味着对情绪、战斗节奏与心智保持着极其精准的掌控。为保持身心康健，我喜爱在附近不远处一座雕像旁冥想——那是为纪念一位在第三次战争中陨落的强大圣骑士而立。请你亲自前往那处。归来时，告诉我你有何体验。', '探访寒脊隘口乌瑟尔的雕像。', '', '探访寒脊隘口乌瑟尔的雕像。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200086, 'zhCN', '自有其用', '你好，$N。很高兴与你结识，在你到来之前我便已听闻了许多关于你的事。你到我这里来学习，身为一名$C，你已然展现出自己是一名勤勉的奥术学子。但我们召唤出的力量，远不止闪电与电能而已。假以时日，你便会知晓自己的潜力究竟有多深。不过此刻……我确有一桩差事要交给你。附近有个人，人称「诺姆·规范者」，他总来向我求助，帮他搞那些……机械捣鼓把戏……他需要些闪电，$N，可我眼下正忙。你能去帮帮他吗？', '协助诺曼·戈德夏尔完成他的机械捣鼓把戏。', '', '协助诺曼·戈德夏尔完成他的机械捣鼓把戏。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200087, 'zhCN', '被盗的能量核心', '嘿，$N！真高兴你的训练师总算派了人来帮我。这任务很简单，我只想要点能量！可不幸的是，我的能量核心被附近的一只狗头人劳工给偷走了。你能帮我取回来吗？', '击杀狗头人劳工，直到其中一只掉落能量核心。', '', '回去找诺曼·戈德夏尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200088, 'zhCN', '风暴使者之差事', '谢谢你取回这个能量核心！你现在可以回到你的训练师那里，让他知道你为我做了什么。', '向你的训练师汇报你的成功。', '', '向你的训练师汇报你的成功。', NULL);
