REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200104, 'zhCN', '欢迎加入战团', '哈！哈！欢迎，$N。很高兴你能加入战团。你大概在想，战团到底是什么？以你的来历，我本以为你早该知道了。唉，小$c，这下你可要猛然清醒了。战团是所有蛮兵、暴徒与大力士齐聚一堂、较量谁才是最强、最残暴、最有权势之人的地方。那才是我们真正检验自身本领的唯一方式。就是这样！你或许还是个新手，但绝不会有人对你手下留情。你的第一项考验，和其他所有新兵一模一样。有个人一直在搞破坏、散布谣言，就因为他没能通过考验、被战团拒之门外。他叫杰拉德。杀了他，哈哈哈！若你真能办成此事，我便赏你一件适合你这等新手的武器。活着回来见我，否则就死在外面吧。', '击杀杰拉德，然后回到你的训练师身边。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
