REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200109, 'zhCN', '力量符文', '你好，$N。我很高兴你终于来与我相会，我一直在等候你的到来。今天，要给你这名胸怀大志的符文大师上一堂简单的解题课。也许你会成功，也许不会。喏，我这儿有枚符文。符文上刻着一道谜题。解开它，再回来见我。提示？我至多只能告诉你，这道谜题的答案就在这座修道院之内，而非外面。你回来时我自会知晓你是否解开了谜题，不必担心。若成功了，我便有赏于你。', '解开刻在符石上的谜题。', '', '回到你的训练师身边。', NULL);
