(200110, 'zhCN', '力量符文', '你好，$N。我很高兴你终于来与我相会，我一直在等候你的到来。今天，要给你这名胸怀大志的符文大师上一堂简单的解题课。也许你会成功，也许不会。喏，我这儿有枚符文。符文上刻着一道谜题。解开它，再回来见我。提示？我至多只能告诉你，这道谜题的答案就在这座建筑之内，而非外面。你回来时我自会知晓你是否解开了谜题，不必担心。若成功了，我便有赏于你。', '解开刻在符石上的谜题。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200111, 'zhCN', '力量符文', '你好，$N。我很高兴你终于来与我相会，我一直在等候你的到来。今天，要给你这名胸怀大志的符文大师上一堂简单的解题课。也许你会成功，也许不会。喏，我这儿有枚符文。符文上刻着一道谜题。解开它，再回来见我。提示？我至多只能告诉你，这道谜题的答案就在奥达希尔之内，而非外面。你回来时我自会知晓你是否解开了谜题，不必担心。若成功了，我便有赏于你。', '解开刻在符石上的谜题。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200112, 'zhCN', '力量符文', '祖格祖格，$N。我很高兴你终于来与我相会，我一直在等候你的到来。今天，要给你这名胸怀大志的符文大师上一堂简单的解题课。也许你会成功，也许不会。喏，我这儿有枚符文。符文上刻着一道谜题。解开它，再回来见我。提示？我至多只能告诉你，这道谜题的答案就在这兽穴之内，而非外面。你回来时我自会知晓你是否解开了谜题，不必担心。若成功了，我便有赏于你。', '解开刻在符石上的谜题。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200113, 'zhCN', '力量符文', '你好，$N。我很高兴你终于来与我相会，我一直在等候你的到来。今天，要给你这名胸怀大志的符文大师上一堂简单的解题课。也许你会成功，也许不会。喏，我这儿有枚符文。符文上刻着一道谜题。解开它，再回来见我。提示？我至多只能告诉你，这道谜题的答案就在旅店之内，而非外面。你回来时我自会知晓你是否解开了谜题，不必担心。若成功了，我便有赏于你。', '解开刻在符石上的谜题。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200114, 'zhCN', '以力量求和平', '很高兴见到你，$N。我们一同还有许多事要完成，而我的朋友，你还有太多要学！我们是守护者，正因如此，守护艾泽拉斯便是我们字面上的职责。从偶尔抢劫路人的无赖，到对我们族类构成更大威胁的怪物，响应召唤的人正是我们。正如我方才所言，今天我便有这般一桩差事交给你。若你能办成，便已完全准备好继续深入你的修行了。附近狗头人矿洞里有个人，名叫「小瓦''祖」，我想他或许需要我的帮助。去拜访他，看看他有何需求。', '在狗头人矿洞中找到「小瓦''祖」。', '', '在狗头人矿洞中找到「小瓦''祖」。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200115, 'zhCN', '防御优先', '你好啊朋友！小瓦''祖很高兴见到你。小瓦''祖有麻烦事。你看，有些狗头人不喜欢小瓦''祖，我都受够这事儿了。我得能保护自己才行！我可不能叫你去杀好狗头人……那可不行。但附近的迪菲亚，没人喜欢他们！他们有武器。你能给我弄一把他们的剑吗？我真是感激不尽！', '击杀迪菲亚，直到为小瓦''祖找到一件合适的武器。', '', '回去找小瓦''祖。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200116, 'zhCN', '助友一臂', '哇，这武器太完美了！现在我就能防住邪恶的齐皮和其他坏狗头人了。谢谢你！我在矿洞里发现了一块金属，我想是别人掉在矿里的。我把它交给了你的训练师，现在他会把它给你的！', '带着成功的消息回到训练师身边。', '', '带着成功的消息回到训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200117, 'zhCN', '以力量求和平', '很高兴见到你，$N。我们一同还有许多事要完成，而我的朋友，你还有太多要学！我们是守护者，正因如此，守护艾泽拉斯便是我们字面上的职责。从偶尔抢劫路人的无赖，到对我们族类构成更大威胁的怪物，响应召唤的人正是我们。正如我方才所言，今天我便有这般一桩差事交给你。若你能办成，便已完全准备好继续深入你的修行了。附近有个人名叫埃弗里·烁齿，我想她或许需要我的帮助。去拜访她，看看她有何需求。', '在铁炉峰找到埃弗里·烁齿。', '', '在铁炉峰找到埃弗里·烁齿。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200118, 'zhCN', '防御优先', '嗨，朋友！你来得正是时候帮忙，太好了！我需要一件防身武器，若你能帮我弄到一件，我定有重赏。附近的穴居人……我一直在观察他们。他们有一把特别的剑，正合我意。若你能给我弄一把成色极佳的来，那就再好不过了！', '击杀石颚穴居人，直到为埃弗里·烁齿找到一件合适的武器。', '', '回去找埃弗里·烁齿。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200119, 'zhCN', '助友一臂', '如今我能在世上自保了，感觉好安全！谢谢你！我在某次闯荡某座矿洞时捡到一面盾牌——我想是有人掉在那儿的。我把它交给了你的训练师，现在他会把它给你的！', '带着成功的消息回到训练师身边。', '', '带着成功的消息回到训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200120, 'zhCN', '控火师之道', '我见过你晃悠，$N。你对魔法草率鲁莽，对学业漫不经心。控火术是一门危险的技艺，一旦失控，你可能会把自己和周遭世界一同烧成灰烬。正因如此，我才决定收你为徒，传授你控火师之道。你的首个使命，是击败一只叛变的火元素——它是一群不法控火师召唤出来，遗弃在此地横行肆虐的。他们将它缚在一处营火之上，就在迪菲亚营寨附近的山丘间，若有无辜者窥探火焰，恐将受害。击败它，把它的心脏带回来给我。', '击败燎焰，取得他的心脏。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200131, 'zhCN', '以力量求和平', '很高兴见到你，$N。我们一同还有许多事要完成，而我的朋友，你还有太多要学！我们是守护者，正因如此，守护艾泽拉斯便是我们字面上的职责。从偶尔抢劫路人的无赖，到对我们族类构成更大威胁的怪物，响应召唤的人正是我们。正如我方才所言，今天我便有这般一桩差事交给你。若你能办成，便已完全准备好继续深入你的修行了。附近有个人名叫基尔沙兰·风行者，或许你已见过他？我想他或许需要我的帮助。去拜访他，看看他有何需求。', '在幽影谷找到基尔沙兰·风行者。', '', '在幽影谷找到基尔沙兰·风行者。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200132, 'zhCN', '防御优先', '你好，$N。看得出你是来帮忙的，太好了！我需要一件防身武器，若你能帮我弄到一件，我定有重赏。附近的小劣魔……我一直在观察它们。其中有一只持着一件特别的武器，正合我意。若你能给我弄一件成色极佳的来，那就再好不过了！', '击杀小劣魔，直到为基尔沙兰·风行者找到一件合适的武器。', '', '回去找基尔沙兰·风行者。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200133, 'zhCN', '助友一臂', '你把它带来，做得很好。如今，我也该回报于你。喏，这面盾牌是我在不远处的蜘蛛矿洞里找到的。愿它助你一臂之力。', '带着成功的消息回到训练师身边。', '', '带着成功的消息回到训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200134, 'zhCN', '以力量求和平', '为了胜利，$N。我们一同还有许多事要完成，而我的朋友，你还有太多要学！我们是守护者，正因如此，守护艾泽拉斯便是我们字面上的职责。从偶尔抢劫路人的无赖，到对我们族类构成更大威胁的怪物，响应召唤的人正是我们。正如我方才所言，今天我便有这般一桩差事交给你。若你能办成，便已完全准备好继续深入你的修行了。附近有位老工头，正需要一件新武器。他和附近的小鬼有笔旧账要算……去拜访他，看看他有何需求。', '在试炼谷找到工头塔兹利尔。', '', '在试炼谷找到工头塔兹利尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200135, 'zhCN', '防御优先', '祖格祖格，$N。看得出你是来帮忙的，太好了！我需要一件武器，若你能帮我弄到一件，我定有重赏。附近的邪恶仆从……我恨死它们了。它们在这试炼谷惹出那么多麻烦，我随便找个借口都能把她们消灭！……我倒想了个好主意。我偶尔会瞧见有小鬼拿着一把刀刃，我要那个。要你所能找到的最上乘的一把。哪怕为此要死多少生灵，也在所不惜。', '击杀邪恶仆从，直到为工头塔兹利尔找到一件武器。', '', '回去找工头塔兹利尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200136, 'zhCN', '助友一臂', '这武器？够好了。我要留着它，纪念那些为了弄到它而殒命的恶魔。', '带着成功的消息回到训练师身边。', '', '带着成功的消息回到训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200137, 'zhCN', '以力量求和平', '很高兴见到你，$N。我们一同还有许多事要完成，而我的朋友，你还有太多要学！我们是守护者，正因如此，守护艾泽拉斯便是我们字面上的职责。从偶尔抢劫路人的无赖，到对我们族类构成更大威胁的怪物，响应召唤的人正是我们。正如我方才所言，今天我便有这般一桩差事交给你。若你能办成，便已完全准备好继续深入你的修行了。附近有个人名叫鸦羽先知，或许你已见过她？我想她或许需要我的帮助。去拜访她，看看她有何需求。', '在纳拉其营地找到鸦羽先知。', '', '在纳拉其营地找到鸦羽先知。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200138, 'zhCN', '防御优先', '谢谢你前来相助，$N。得知在纳拉其营地有人如此照应我，我很欣慰。时局正变得……岌岌可危。如你所知，当地的野猪人可是相当危险的一伙。我想找一件武器，万一情势吃紧时好用来自卫。不过，并非随便什么武器都行——我想要的是野猪人自身携带的武器。或许他们见我拿着它，动手前便会三思。你能给我弄一件他们的武器吗？', '击杀刺背野猪人，直到取得它们的一件武器。', '', '回去找鸦羽先知。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200139, 'zhCN', '助友一臂', '好了，如今无论何种来犯，我都能自保了……或至少能吓退那些图谋不轨之人。我在莫高雷一带闯荡时捡到一面盾牌。我注意到你也在用盾，便把它交给了你的训练师。或许我找到的这面能派上些用场。你回去找他时，他应该已替你备好了。……而且，$N，谢谢你。', '带着成功的消息回到训练师身边。', '', '带着成功的消息回到训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200140, 'zhCN', '以力量求和平', '很高兴见到你，$N。我们一同还有许多事要完成，而我的朋友，你还有太多要学！我们是守护者，正因如此，守护艾泽拉斯便是我们字面上的职责。从偶尔抢劫路人的无赖，到对我们族类构成更大威胁的怪物，响应召唤的人正是我们。正如我方才所言，今天我便有这般一桩差事交给你。若你能办成，便已完全准备好继续深入你的修行了。附近有个人名叫卡德莫斯·烬焰，我想他或许需要我的帮助。去拜访他，看看他有何需求。', '在死亡之痕找到卡德莫斯·烬焰。', '', '在死亡之痕找到卡德莫斯·烬焰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200141, 'zhCN', '防御优先', '啊，$c。我就知道援助很快就会到来。今天我正需要些庇护，或者说，自我保护之法？我是一切火焰与烈火的大师。唉，可惜我的近战造诣实在欠缺。若情势所迫，我希望能保护自己，而不必径直将对手活活烧成灰。附近有血色十字军的成员。他们的武器于我大有用处。你能替我取一件你见到的上乘之作带回来吗？', '击杀血色皈依者，直到为卡德莫斯·烬焰找到一件合适的武器。', '', '回去找卡德莫斯·烬焰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200142, 'zhCN', '助友一臂', '这把剑……还是匕首……真是……完美！多谢你了！我在离此不远处的本地蜘蛛洞穴探险时找到一面盾牌，已交给了你的训练师。我已同他们说定，他们会把它给你的。我确信，它对你远比对我有用得多。', '带着成功的消息回到训练师身边。', '', '带着成功的消息回到训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200143, 'zhCN', '控火师之道', '哇……我感觉不大对劲，$N。转得我……我不该盯着那火看了那么久。我转着转着……我是说，我旋着……旋着……噢……一伙叛变的控火师转来转去，召唤出一只火元素！它被缚在冰封湖面上的营火中，若你不去阻止，它会伤害许多无辜之人！去找这只元素，它名叫燎焰。用你的火焰把它旋得团团转，取走它的心脏，带回来给我研究。', '击败燎焰，取得他的心脏。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200144, 'zhCN', '控火师之道', '烈火升腾，$N。身为控火师，你必须确保它不会腾起将你吞没，否则你便将葬身火海。我有一桩差事交给你，它应能助你驾驭心中那团狂暴的烈焰。一伙走投无路的控火师释放出一股他们所无法控制的力量，将它缚在燃烧之刃附近的营火之上。这只元素名叫燎焰，我会在你的地图上标出它的位置。杀了它，把它的心脏带给我。为了胜利！', '击败燎焰，取得他的心脏。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200145, 'zhCN', '控火师之道', '纵然我的心脏数年前便已停止跳动，胸中的火焰却依旧炽烈燃烧。你也感受到了吗，$N？有些人感受得太过强烈，任由它将自己彻底吞没。他们任凭烈焰烧得如此之旺，以至于失去对冲动的把控，做出令自己悔恨之事。一伙叛变的控火师燃烧得如此耀眼，竟从拉格纳罗斯的领域中召唤出一只元素。他们将它缚在山丘间的营火之上，我委派你去召唤并击杀它。带着它的心脏回来见我，我便会将他们所欠缺的克制力赏赐于你。', '击败燎焰，取得他的心脏。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200146, 'zhCN', '控火师之道', '*雅克拍灭胡须上的一小簇火苗* 哦，致敬，$N！很高兴见你沿着烈焰之路精进！我的父亲、控火师罗格雷恩，已前往黑石深渊，向黑铁矮人求学更多，将训练莫高雷下一代控火师的职责托付于我。可惜，我做得并不好。我手下的几名学员失去了理智，将一只强大的火元素缚在台地另一侧的营火之上。你务必阻止这存在将平原烧成灰烬！助我一臂之力，$N，我定保你免遭同样的下场。', '击败燎焰，取得他的心脏。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200160, 'zhCN', '熊之道', '欢迎，$C。我一直在寒脊山谷等候你的到来。你为求智慧而来寻我，既是如此，我自当倾囊相授。成为$C大师的第一步，便是精通熊之道。每精进一层，便有新的挑战接踵而至，但眼下，我们先专注于唤醒你内心狂野本能的真谛。熊是庞大而凶猛的生物。它们只知为了生存必须做什么，那便是杀戮。面对一只决意取你性命的熊，几乎无人能够逃脱。借由熊，我们获得野性、凶残与力量，毫不留情。向西边的冰霜巨魔取其性命，向我证明你已领悟此道，我便有赏于你。', '击杀 8 只霜鬃巨魔幼崽。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200161, 'zhCN', '熊之道', '欢迎，$C。我一直在奥达希尔等候你的到来。你为求智慧而来寻我，既是如此，我自当倾囊相授。成为$C大师的第一步，便是精通熊之道。每精进一层，便有新的挑战接踵而至，但眼下，我们先专注于唤醒你内心狂野本能的真谛。熊是庞大而凶猛的生物。它们只知为了生存必须做什么，那便是杀戮。面对一只决意取你性命的熊，几乎无人能够逃脱。借由熊，我们获得野性、凶残与力量，毫不留情。了结附近洞穴中树林蜘蛛的性命，向我证明你已领悟此道，我便有赏于你。', '击杀 8 只树林蜘蛛。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200162, 'zhCN', '熊之道', '祖格祖格，$C。我一直在试炼谷等候你的到来。你为求智慧而来寻我，既是如此，我自当倾囊相授。成为$C大师的第一步，便是精通熊之道。每精进一层，便有新的挑战接踵而至，但眼下，我们先专注于唤醒你内心狂野本能的真谛。熊是庞大而凶猛的生物。它们只知为了生存必须做什么，那便是杀戮。面对一只决意取你性命的熊，几乎无人能够逃脱。借由熊，我们获得野性、凶残与力量，毫不留情。了结此地以北邪魔追猎者的性命，向我证明你已领悟此道，我便有赏于你。', '击杀 4 只邪魔追猎者。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200163, 'zhCN', '熊之道', '欢迎，$C。我一直在红云台地等候你的到来。你为求智慧而来寻我，既是如此，我自当倾囊相授。成为$C大师的第一步，便是精通熊之道。每精进一层，便有新的挑战接踵而至，但眼下，我们先专注于唤醒你内心狂野本能的真谛。熊是庞大而凶猛的生物。它们只知为了生存必须做什么，那便是杀戮。面对一只决意取你性命的熊，几乎无人能够逃脱。借由熊，我们获得野性、凶残与力量，毫不留情。了结附近沟壑中野猪人的性命，向我证明你已领悟此道，我便有赏于你。', '击杀 8 只刺背野猪人。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200165, 'zhCN', '分秒不差', '啊，$N，我早在很久以前便预见了你的到来。如今，是时候教你何为时光法师了。去编织时空的本源织缕，去堪比神明……且让我莫要操之过急。因为你，$N，尚是时光魔法界的新人，在我允许你带着这般潜藏之力存身于这个世界之前……你必须先学会掌控自己。身为时光法师，你是时间魔法的主宰。这意味着你必须在最基础的层面上敬畏时间。恰巧，我把法杖落在了修道院某处。你有两分钟。替我找到它。', '在北郡修道院找到索莉多米的法杖。', '', '回去找索莉多米。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200166, 'zhCN', '分秒不差', '啊，$N，我早在很久以前便预见了你的到来。如今，是时候教你何为时光法师了。去编织时空的本源织缕，去堪比神明……且让我莫要操之过急。因为你，$N，尚是时光魔法界的新人，在我允许你带着这般潜藏之力存身于这个世界之前……你必须先学会掌控自己。身为时光法师，你是时间魔法的主宰。这意味着你必须在最基础的层面上敬畏时间。恰巧，我把法杖落在了这栋建筑里的某处。你有两分钟。替我找到它。', '在铁炉峰找到哈罗多尔姆的法杖。', '', '回去找哈罗多尔姆。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200167, 'zhCN', '分秒不差', '啊，$N，我早在很久以前便预见了你的到来。如今，是时候教你何为时光法师了。去编织时空的本源织缕，去堪比神明……且让我莫要操之过急。因为你，$N，尚是时光魔法界的新人，在我允许你带着这般潜藏之力存身于这个世界之前……你必须先学会掌控自己。身为时光法师，你是时间魔法的主宰。这意味着你必须在最基础的层面上敬畏时间。恰巧，我把法杖落在了这栋建筑里的某处。你有两分钟。替我找到它。', '在奥达希尔找到卡莱多鲁姆的法杖。', '', '回去找卡莱多鲁姆。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200168, 'zhCN', '分秒不差', '啊，$N，我早在很久以前便预见了你的到来。如今，是时候教你何为时光法师了。去编织时空的本源织缕，去堪比神明……且让我莫要操之过急。因为你，$N，尚是时光魔法界的新人，在我允许你带着这般潜藏之力存身于这个世界之前……你必须先学会掌控自己。身为时光法师，你是时间魔法的主宰。这意味着你必须在最基础的层面上敬畏时间。恰巧，我把法杖落在了隔壁某处。你有两分钟。替我找到它。', '在死亡之痕找到夸多尔米的法杖。', '', '回去找夸多尔米。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200199, 'zhCN', '暗影界之召', '啊，终于，我盼来了另一名如我一般的$R，去修习这般令人艳羡的技艺！……你很大胆。我感应到，你是来向我求学的。今天我确有一桩简单的差事交给你，年轻的$C。就在这间屋子里，有个体型矮小的侏儒已近生命尽头，名叫吉罗索尔·涡火花。尽管他一生充满冒险与成就，却对自己步步逼近的终点满心苦涩。他终将死去，暗影界会将他收走。但今天还不是他的死期。然而，我能感受到他渴望离开这个位面，却对身死之后等待自己的是什么浑然不知。你或许没料到这么一桩差事，但我仍要谦卑地请你去拜访他，与他聊上几句。', '在铁炉峰拜访吉罗索尔·涡火花。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(200255, 'zhCN', '狩猎开始', '我能感到一股邪恶的存在。你也能感觉到，对吧？这正是你于这最恰当时机来寻我的缘由。此处有一人，是个女巫，满腹邪念与恶意。愿圣光庇佑我们即将行之举。喏，拿着这火把。她就在铁炉峰，我已在地标上标出她的位置。用火把照她，揭穿她的真身。杀了她，毫不留情。待她伏诛，便回来见我。该死的女巫。', '揭穿女巫的真面目并将她击杀。', '', '回到你的训练师身边。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254000, 'zhCN', '一个小失误', '噢，见鬼！这下糟了……真的糟了……嘿，你！对，就是你！想接活儿？好，我正好有一桩。好了，埃弗里你冷静点，冷静点……$B$B我本来在造一台机器人，想让它聪明点！我本打算让它……抱歉，我口误了。我做了一台机器人，叫「智能自动安防守卫」，简称尼莉莎。怎么，你以为我会到处叫它伊阿斯格？没门！尼莉莎是我的骄傲与喜悦，嘿，她将重塑我们对技术的认知！嘿，她的谋略说不定比你我都要高明！有尼莉莎守护你的家园，哪怕是一队配合默契的冒险者也无法撼动分毫！$B$B至少……本该如此……$B$B尼莉莎叛变了。她走了，谁知道去了哪儿，但以她所具备的一切能力……唉，这真的不妙。我是说，我多少赋予了她控制机器人的能力，还有……听着，这不该发生的，行吗？瞧，她袭击了附近那帮霜鬃巨魔，似乎没把活儿干完，但也许她落下了些什么。', '在霜鬃营地搜寻线索。', '', '回到位于丹莫罗寒脊山谷的埃弗里·烁齿处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254001, 'zhCN', '我们找到她了！', '好了，我知道了！她离得其实并不远，就在寒脊山谷的南端。你最好趁她离开前赶过去，还有……你或许得毁掉她，但尽量别过度损坏她的内部构件。我只是想搞清楚发生了什么，做点调整，一切就会好起来的，我发誓！$B$B但她现在仍是威胁，所以快动身去把她关停！我……剩下的以后再想办法。', '在布鲁诺尔村西南方向搜寻尼莉莎。', '', '回到位于丹莫罗寒脊山谷的埃弗里·烁齿处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254002, 'zhCN', '斥候的人情', '我也不知道尼莉莎是否真的在针对霜鬃巨魔，但眼下我也没有别的线索，不如去找到那名流放者，看看她是否知道些我们所不知的事。$B$B好吧，若我是只被流放的巨魔，会躲到哪儿去？嗯，大概是不会去主要营地的任何地方吧。噢，这根本没缩小范围，不是吗？等等，我想起来了，我从一个斥候那儿听来过，或许他看得更多！那斥候从隧道上去，你先前说不定还从他身边经过。去找他，问问他知道些什么！$B$B我要前往塞尔萨玛，看看那儿的矮人有没有瞧见什么。你办完事后到那儿与我会合，告诉我从那巨魔口中套出了什么，好吗？哦，呃，你顺手清掉隧道里的一些穴居人，或许那矮人会更乐意攀谈。也好让我能真的通过……', '击杀 4 名石颚突袭者，并在隧道另一端与山地卫兵塔格努尔会合。', '', '与山地卫兵塔格努尔交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254003, 'zhCN', '老米辛斯', '我瞧见一只巨魔在布鲁诺尔和卡拉诺斯之间的山丘上游荡，看样子是在躲着其他巨魔。它往那雪人住的洞穴附近去了——我们管那雪人叫冰须。为啥叫这名？嗯，它待在那儿有些日子了，胡须里结着冰。$B$B总之，你那流放巨魔这会儿多半已经死了，想我当年，冰须可干掉过不少好矮人。换作我可不会靠近它，但你要是真非要找到那巨魔，就留神提防、离它远点。明白了吗？我可不想你的死沉甸甸压在我良心上。', '找到那名被流放的霜鬃巨魔。', '', '找到那名被流放的霜鬃巨魔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254004, 'zhCN', '兄弟的背叛', '你想聊聊老米辛斯所见之事？一个金属之躯正对我的族类、或许也对你的族类发起战争？是啊是啊，老米辛斯见过许多事，但你或许也是金属之躯。你希望它停下，因它对你族类是威胁，尽管它攻击的是我的族类？$B$B你的远见或许胜过老米辛斯的族类。你放下了旧日仇怨，那么老米辛斯也会如此。反正老米辛斯的族类已不再是老米辛斯的了，被逐出，对，正如你们所言「流放」？为何如此？又为何你的金属之躯不听号令？缘由与老米辛斯不听从时相同，又或许恰恰相反。$B$B若你想要答案，便去做一件老米辛斯力所不及之事。老米辛斯藏身此处，是因为雪人把我们族类挡在外面。雪人比我们族类更易躲开，你明白了吧。老米辛斯能藏、能避、能游荡，但琼孔兄弟在她被逐出时拿走了老米辛斯的图腾，你明白了吧。她既非他族类，便不再是老米辛斯的家人。琼孔兄弟是个懦夫，躲在洞穴极深极深之处。把图腾带回来，我们便来谈谈那金属之躯、历史，还有诸多事情，可好？', '从霜鬃要塞的琼孔手中取回流放者米辛斯的图腾。', '', '回到流放者米辛斯处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254008, 'zhCN', '寻找解药', '嗯。你把安宁花和……不，那不太对。$B$B你是新兵，对吧？或许你能帮上点忙。就当是你试炼的一部分吧。打架从来不是我的强项。几年前我也经历过这些试炼，一只蝎子差点要了我的命。我之所以活下来，全靠用当地的仙人掌和一朵罕有的花调制出药膏。$B$B虽说那并没多大用处。你以为我灰溜溜回来当个逃兵，会有人为我喝彩吗？我是个失败了的弱者，是个打不完仗的懦夫。$B$B但我终究还是回到了这里，并非打算重蹈覆辙，而是因为我在人生中找到了自己的路，正试图为困扰我们许久的某种东西寻得解药。所以，若你在试炼中比我做得更好，我正想找另一朵我曾找到过的那种花。这次不是为了疗伤药膏，而是另有用处。我的试炼中，我是在西北方、一棵树的底下发现它的。', '找到那株奇异的花。', '', '回到位于杜隆塔尔试炼谷的萨卡里处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254009, 'zhCN', '危险的样本', '多谢你了。实情是，这花是我唯一的线索。我已采集了不少仙人掌，周围随处可见，我都不必远离大路，但我所观察到的功效必然在那花里。这比绝大多数人发现的都多，可我的资源有限，而我们甚至不知这花源自何处。$B$B我所需要弄明白的，是恶魔之血的特性。我已取了不少自己的血当作样本，但我需要来自源头之物。山谷北端的洞穴里有恶魔，不是吗？替我找来其中一只的血，不是随便什么血，要你能找到的最强那只。$B$B这虽比不上远古兽人饮下的那般，但或许至少是个开端。', '从一只强大的恶魔身上采集恶魔之血。', '', '回到位于杜隆塔尔试炼谷的萨卡里处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254010, 'zhCN', '半人马的知识', '这还不够……是个开端，没错。但这桩任务还需要更多。首先，我得弄明白这花的特性。我在部落里还没遇到谁知晓它，它们似乎并不常生长。但还有另一族群或许通晓自然之物。$B$B半人马在杜隆塔尔栖居多年，虽说我们总不能径直去问他们知道些什么。不过，他们或许留有此花的某些记载。去他们的营地看看你能学到什么。你办完时我会在奥格瑞玛。$B$B一路小心。你已是比我更强更勇的战士，但力量与勇气常伴愚蠢而来，纵然许多兽人极不情愿承认。', '在半人马营地中搜寻有关此花特性的线索。', '', '在半人马营地中搜寻有关此花特性的线索。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254011, 'zhCN', '亮晶晶！', '你认出这幅画是种你听说会威胁杜隆塔尔的生物——一只鹰身女妖。也许几块亮闪闪的金属碎屑，足以安抚其中一只，让它愿意与你交谈。', '收集金属碎片。', '', '将金属带给剃刀岭以西的一只鹰身女妖。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254012, 'zhCN', '女王的敕令', '姐妹们图谋叛乱，是的是的是的，耳朵听着，听见那邪恶叛逆之言！她们妄求权力、自由，妄想要当女王，是的是的是的！这称号是我光明正大杀出来的，姐妹们不过是嫉妒，是的是的是的，她们就是嫉妒的叛徒！$B$B让姐妹们见识谁才是真正的女王，是的是的是的，不必全部，许多便够！平息叛乱，我便告诉你阿维安娜之玫瑰的故事！', '为埃蕾缇娜女王击杀鹰身女妖。', '', '回到埃蕾缇娜女王处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254013, 'zhCN', '阿维安娜之玫瑰', '有情报了，是的是的是的！虽不能让皮肤变绿，但阿维安娜之玫瑰稀有，极稀有，历来只此一朵，再无第二，有时还更少！鹰身女妖从未解除诅咒，也从未对阿维安娜之玫瑰施用魔法。可你手里已有一朵了，是的是的是的！$B$B你带来了亮晶晶，平定了叛乱，我帮你，是的是的是的！魔法还需别种材料——明亮闪亮的石头，黄色，闪闪发光，极极极亮，在南边某处。去找来，用那花，解除诅咒！', '将你得知的情报带给奥格瑞玛的萨卡里。', '', '将你学到的情报带给奥格瑞玛的萨卡里。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254038, 'zhCN', '开始挖掘', '你看起来不像是本地人。这地方正变得喧闹。太多眼睛，太多疑问。我不喜重复自己，也不信任窃听范围内半数的人。在匪徒堡垒附近与我会面，我好将细节交代清楚。', '在匪徒堡垒附近的集结点与瑟琳娜·薇尔探员会面。', '', '向位于艾尔文森林匪徒堡垒附近的瑟琳娜·薇尔探员汇报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254041, 'zhCN', '向将军汇报', '马库斯·约翰逊将军会想知道你在此地发现了什么。将这份报告带给他，你一进暴风城应该就能找到他。', '将这份情报带给马库斯·乔纳森将军。', '', '向位于暴风城英雄谷的马库斯·乔纳森将军汇报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254042, 'zhCN', '通缉：囤积者蕾诺尔', '通缉：囤积者蕾诺尔$B$B奉人民民兵队之令，囤积者蕾诺尔现被判定为对西部荒野稳定的威胁。$B$B此人策划了多起针对开往民兵前哨的补给车队的袭击。报告证实，她正囤积赃物，并将其分发给在该地区活动的迪菲亚特工。$B$B她机敏迅捷，且极少在同一地点现身两次。切勿低估她。', '击杀囤积者蕾诺尔，回到哨兵岭的守卫者加瑞尔处。', '', '向位于西部荒野哨兵岭的守卫者加瑞尔汇报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254043, 'zhCN', '夺回', '我们在这儿兵力吃紧。口粮见底，士气更糟，每过一夜便又少一只箱子。迪菲亚锲而不舍，趁我们死守所剩无几的阵地时把我们逐个击破。$B$B有消息说，他们将赃物藏在了附近某处。而且不只是零碎。是真补给——食物、绷带、工具，甚至可能有武器。我们有理由相信，他们把东西藏在了西边那座老塔里。$B$B若你能潜入并取回任何有用之物，便可能扭转此地的局势。民兵队已在尽其所能，但我们仍需要一切能争取的优势。', '守卫者加瑞尔要你收集西部荒野补给，然后回到哨兵岭的她身边。', '', '向位于西部荒野哨兵岭的守卫者加瑞尔汇报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254051, 'zhCN', '拯救鳄鱼', '我守着河边一个窝好几天了。有只鳄鱼终于产卵了，就一枚完美的蛋。漂亮得很。斑点壳，摸着温温热。我本想把它挪到安全的地方，给它能真正孵化的机会。接着那些肮脏的穴居人出现了。他们咕哝着、踩着灌木闯进来，其中一只抓起蛋就像抓块石头，尖叫着跑掉了。他们根本不知自己抓着什么。若我们不快点夺回，他们要么吃了它，要么砸了它，要么在泥里把它煮了。你比我快，也不怕弄脏自己。把那枚蛋带回来。我欠你一个人情。', '辛特·维芙要你从北面岛上那群穴居人「偷猎者」手中取回鳄鱼蛋。', '', '向洛克莫丹的辛特·维芙汇报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254053, 'zhCN', '谦卑之责', '若你愿听一个简单请求，我这把老骨头已不复当年之力。对圣光的信仰……本就不是为我们这般之人而设。而这副身躯，在职责召唤时也并非总能应命。$B$B墓园中的坟茔荒废太久无人打理。那些可怜的魂灵，这世上或许已无人记得他们，但他们同样值得一份尊严。$B$B若你抽得出空，也去照料一下巴尔尼尔农场里阿尔萨斯坐骑的坟墓吧。他主人的罪孽深重，可那匹马是忠诚的……而且，在巫妖王的阴影笼罩大地之前，它便已死去。$B$B若它能活得久些，或许这故事会走向不同的结局。', '擦拭阿拉斯托神父墓园中的 6 块墓碑，以及巴尔尼尔农场无敌的坟墓。', '', '回到提瑞斯法林地的阿拉斯托神父处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254054, 'zhCN', '巴尔尼尔一家的安息', '巴尔尼尔一家曾在全艾泽拉斯培育出最上乘的骏马，连王室都青睐有加。即便有这般主顾，他们也从不因此自傲，是善良谦逊之人，我相信他们的马也承袭了他们，这便是他们受青睐的缘由。$B$B……但那都已是过往。如今农场已成废墟，只有不得安息的亡者栖身其间。我确信巴尔尼尔一家自身必在其中，可虽我执掌圣光，如今却令我痛苦——我再也信不过自己在战斗中的力量了。$B$B若你心存善意，能否代我让那些可怜的魂灵安息。总共有三位：瓦拉、约伦，以及他们的儿子贾林。', '让巴尔尼尔一家——约伦·巴尔尼尔、瓦拉·巴尔尼尔与贾林·巴尔尼尔——的亡魂得以安息。', '', '回到提瑞斯法林地的阿拉斯托神父处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254055, 'zhCN', '黑暗猎犬的款待', '你看上去还是有点紧张，别担心，他不会咬人的。除非我让他咬，那另当别论。$B$B好吧，来，你不如做点什么来赢得他的信任？他特别喜欢那些暮色蝙蝠，其实我花了好一阵子才训练他不至于在它们从营地旁边经过时直接扑上去。$B$B我一直在东边看到一只大的，本打算去给他猎来，但既然你在这儿，你不如去把它找到，给他来上一口？', '找到一份款待，交给埃德温的猎犬。', '', '返回埃德温·寒迹处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254056, 'zhCN', '酝酿的混乱', '驻扎在这片荒野，我们时刻遭受着血色十字军的攻击。到目前为止我们挡住了他们的进攻，好让药剂师们能继续他们的工作，而且基本上他们已经不再派人来送死了。$B$B但最近，某个自命不凡的中尉被派驻去掌管他们在毒网谷的营地，他一直在组织对咱们的协同进攻。我不确定我们还能撑多久，所以我希望看到杉德斯中尉死掉。$B$B没有了他，我们只能希望他们会乱成一团，暂时放咱们一马。药剂师拉尔登一直在追问我们是不是已经取下了那位中尉的首级，所以你办完事后把它带去给他，好让他别再来烦我们。', '在毒网谷击杀杉德斯中尉，并将他的首级带给药剂师拉尔登。', '', '将杉德斯中尉的死讯告知药剂师拉尔登。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254057, 'zhCN', '这就是正义', '好了。大功告成。有了这个，血色十字军直到为时已晚才会发现他们已经输了。$B$B现在最后一步是把它送到他们手上而不引起怀疑。这正是那颗中尉脑袋的用处。$B$B我调配了一种药剂，能让你看起来和他一模一样。它应该能让你顺利进入修道院，不会太费事。只要尽量别离任何人太近，并且一直走动。这种事并非万无一失，但只要你不做蠢事，就没问题。$B$B而且想都别想去找人打架。修道院的守卫可不像那营地里的那些。他们一挥之下就能把你的五脏六腑撒在草地上。如果他们发现你不是他们的中尉，他们会毫不犹豫地证明这一点。', '使用拉尔登的变形药剂潜入血色修道院的庭院，并感染他们的补给。', '', '返回药剂师拉尔登处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254059, 'zhCN', '战生竞技场：「低颚」', '你！你可不是光来看热闹的吧？你就是那种喜欢痛痛快快打一架的人，我在你眼里看得出来。    你干嘛不试试在擂台上走一轮？赢了有财富和荣耀，输了也是个痛快的死法。我们这儿还排着另一个新来的，你要是赢了，我就给你找些更有经验的对手。', '击败第一位挑战者：「低颚」', '', '与文斯的助手古格索克交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254060, 'zhCN', '战生竞技场：「死嚎」', '别得意忘形，低颚在擂台上毫无经验，他只是个热身。    下一个上场的是一只从尘风部族远道而来的鹰身女妖。别装得好像这有多奇怪似的，只要愿意打，谁来我都收，擂台外有什么恩怨我可不管。我没听懂她的真名，不过也无所谓，她说话带着那种可怕的尖啸，所以她在擂台上的名字就是「死嚎」。', '击败第二位挑战者：「死嚎」', '', '与文斯的助手古格索克交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254061, 'zhCN', '战生竞技场：「碾压者」', '关于你的消息传得很快，$C。观众们已经管你叫「神秘陌生人」了，有些人还说你可能一路走到最后。你不只是让粉丝们惊讶，你让他们成了你的信徒。    但这就是了。最后一轮。    你最后的对手是个行走的灾难区。「碾压者」。食人魔，庞大、凶残，而且彻底失控。他打起来不讲规矩，他也从不留手。你击败了他，这擂台就是你的了。    强势入场。以冠军之姿离场。', '击败第三位挑战者：「碾压者」', '', '与文斯的助手古格索克交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254062, 'zhCN', '战生竞技场：「影血」', '押在你身上的赌注越来越多，之前只有另一个斗士扛住了碾压者的重锤。那是一位来自黑暗之矛部族的暗影猎手，她在竞技场里打出了名号，是现在擂台上最顽强的现役斗士。    我们叫她「影血」。她有种不死的癖好，也许袖子里藏着什么花招，但那得由你来琢磨。真正的冠军已经多年未战，所以击败她，你就是我们这儿最厉害的了。', '击败第四位挑战者：「影血」', '', '与文斯的助手古格索克交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254063, 'zhCN', '战生竞技场：最后一战', '看来押你赢的人要好好赚一笔了。你击败了我们这儿最厉害的，所以现在只剩一件事了。    踏进擂台，你就会加冕为兽人狂热最新的冠军！', '加冕为兽人狂热的冠军。', '', '与文斯的助手古格索克交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254064, 'zhCN', '自由的本质', '你看，反正你也要在这一带转悠，不如帮我个忙。我是个科学家，不是战士，你明白的。可惜这两个身份交织的频率，比我愿意承认的还要高。$B$B我们被遗忘者摆脱了天灾军团的束缚，但许多人仍在为它效力。有些腐烂得更厉害，比如磨坊周围那些大多如此，但也有些更难解释。我们的黑暗女王曾是一名女妖，可我在这片地区却看到仍被天灾军团委身的女妖。$B$B也许这纯粹是意志的问题。即便如此，必定有办法去推动至少一些还保留着部分自我的亡灵，斩断与巫妖王的联系，对吧？这正是我理论的出发点。唉，这瓶调配药剂已经是我能安全做到的地步了。$B$B也许你可以试试？它应当能引发一阵暂时的力量迸发，如果我的论点正确，或许能给他们一个夺回控制权的机会。实际上，单靠它收效甚微，但若有像你这样的人先削弱束缚他们的力量，我料想它会有效得多。', '在3个僵尸、3具骷髅、3个女妖和受折磨的马里克身上测试罗德·毒击的调配药剂。', '', '返回罗德·毒击处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254067, 'zhCN', '米内薇娅的遗产', '这么说你也对她感兴趣了，是吗？    她在那次袭击后不久就失踪了，有人说她死了，有人说她只是退隐到艾泽拉斯某个安静的角落去了——如果真有那种地方的话。    我必须弄清楚！她救过我的命，我当初就是为她才想来这里学习的……我欠她太多，可我连她究竟发生了什么都不知道。我把塔里每一本书都读遍了，可内容全都一个样。    不过你看起来像是冒险者的料。也许你能找到我漏掉的东西？拜托了，只要你打听到什么，一定要告诉我！', '在三角塔和湖畔镇搜寻大法师米内薇娅法杖的线索。', '', '在湖畔镇旅店与酒保丹尼尔斯交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254068, 'zhCN', '米内薇娅的过往', '原来派你来的就是她，是吧？我早该想到的。真希望几年前我就把真相告诉她了，可我从来不知道什么时候才是对的时机。答应我，这事你先替我保密，好吗？她下次来访时由我亲口告诉她比较好。    大法师米内薇娅是我的母亲，我知道她以伟大大法师之名远近闻名，但在我小时候，她离家出走了，直到那次袭击我才又听到她的消息，而即便那时也没多少时间说话。我恨了她一阵子，不过我想，她救了阿莱克斯，那是她在弥补，你明白吗？很难真的去怨恨一个救了我女儿性命的人。    再说，我后来确实弄清了原因，她有过一段黑暗的过去。尽管她脱离了那段过往，我觉得她始终没能真正信任自己。大概觉得没有她在身边，我会更安全吧……    你可以去伊尔加拉之塔周围探探，我想她当年那个圈子的人还在那儿，所以你也许能找到些什么。', '调查伊尔加拉之塔，寻找大法师米内薇娅失踪的线索。', '', '离开伊尔加拉之塔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254069, 'zhCN', '米内薇娅的结局', '……米内薇娅？    这名字我可是好多年没听到了。既然你来到这里，看来你对她已经有了相当不错的了解。    在摩根斯成为伊尔加拉之法师之前，统治这座塔的是一位名为米内薇娅的黑暗魔法学者。多年前她曾与塞欧克瑞图斯法师在达拉然一同研习，尽管她曾是我们的敌人，他却始终带着敬重提起她。那是多年前的事了，他终于设法将阿佐拉的智慧带给了她，于是我们最大的敌人背离了伊尔加拉的道路。    无论她曾做过什么，我们追寻的只是启迪，而非复仇，我们所有人对此结果都极为欣慰。塞欧克瑞图斯尤甚。    不过，塞欧克瑞图斯也曾说起，那段过往如何始终纠缠着她的新生活。我不知道她最终去了哪里，但我只愿她最终能就那段过往，与自己和解。', '调查湖畔镇的坟墓。', '', '向亚历山德里娅·罗恩汇报你的调查结果。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254070, 'zhCN', '失落的秘密', '我是秘典之书，我能帮助你揭开这个世界的真相，直到你领会它的本质。我也是你通往许多人眼中「禁忌」之知识的向导。    啊，但可惜，近来我的使命变得有些模糊了。一个贪求我知识的被诅咒的兽人，性子急得过了头，竟撕去了我的一页，何等野蛮！她已彻底配不上我慷慨的馈赠！    她如今在石守望堡附近的一座塔顶钻研它，其余那些蠢货我毫不关心，但我希望她因傲慢而被诛杀，而最重要的是——找回我失落的页面。    我相信你该是文明得多的那种人吧？', '寻回秘典之书的失落书页。', '', '将书页归还秘典之书。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254071, 'zhCN', '育龙巢', '嗯，反正我也得等贾斯珀彻底醒过来，不如趁这工夫做点别的。    我一直在努力多了解这一带的黑龙，以及兽人似乎是怎样把它们变成盟友的。    他们在树林深处有个育龙巢，从蛋里孵养新的幼龙，但那里守卫森严。如果你真能闯过去，我最能从中获得好情报的，就是他们手里最上乘的那枚蛋。', '取得一枚纯净的黑龙蛋。', '', '返回红法师塔的梅莉娅·克拉斯特洛处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254084, 'zhCN', '斗士的补给', '照这些斗士受伤的速度，我的治疗草药就要用光了。    我知道另一种药剂能让他们恢复得一样好，不过取得它相当危险，而我可不是战士。    如果你正好要去外头，能不能把材料带回来？我需要蝎子毒液、迅猛龙血和野猪獠牙。别担心，毒液只要处理得当就没害处。', '护士辛嘉要你收集4瓶蝎子毒液、4瓶迅猛龙血和4个野猪獠牙。', '', '返回杜隆塔尔战生竞技场的辛嘉处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254086, 'zhCN', '审讯', '至少没什么坏处，而且也许能帮我们早点问出答案，所以你想试的话我也不会拦你。\\n\\n只是别离笼子太近，它可能会试着撕开你的喉咙。', '夜巡队的奥斯温·德雷克需要帮忙审讯被俘的狼人。', '', '返回夜巡队的奥斯温·德雷克处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254087, 'zhCN', '被黑暗带走', '我现在想起来了，听说有个叫朱莉·艾德尔的住在夜色镇的旅店里。如今得盯紧每一个人，永远不知道一个平民什么时候会变成更不寻常的东西。\\n\\n我们三个需要留在这里，人手本来就不够。不过，我看这样也问不出什么进展，如果你到了夜色镇，也许可以亲自去寻她，看看她能不能帮上忙。', '在赤鸦酒馆找到朱莉·艾德尔。', '', '在赤鸦酒馆找到朱莉·艾德尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254088, 'zhCN', '艾德尔农庄', '我道歉。我没料到会听到他的消息，不过我没事。如果他还记得我的名字，或许还有一线希望。\\n\\n我们的农庄前些时候遭到了狼人袭击，我们想逃，可他们更快。于是我丈夫……他……他让我快跑，然后就打了起来。我们俩都不是战士，可我不知道该怎么办，所以听了他的话。我一路跑到这儿……从那以后就再没见过他。\\n\\n我没尝试回去过。那儿现在已没什么值得我留恋的了，而且我听说，即便狼人走了，如今那地方也被强盗占据了。\\n\\n不过，也许那里还留着些他能认出的东西，些许他旧日生活的痕迹。那或许是你最好的机会。', '在艾德尔农庄寻找阿尔维斯·艾德尔昔日生活的痕迹。', '', '将书带回赤鸦酒馆的朱莉·艾德尔处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254089, 'zhCN', '艾德尔农庄', '你走之前，我还得提一句，他以前常来这家酒馆喝蜂蜜饮料。他向来不爱喝烈酒，总说那让他写不下去。也许你带点给他也会有帮助。\\n\\n……我为什么不一起去？\\n\\n不，你说得对。我害怕看到他这副模样。我甚至不知道我最爱的那个男人还剩多少在他体内，但他认出我的可能性，总比认出他那本写了半截的小说和一杯爱喝的饮料要大。\\n\\n如果你拿到饮料，我就带上书去那里与你汇合。无论如何，我都必须面对他。', '将那本写了一半的书和一瓶蜂蜜饮料带给被俘的狼人。', '', '与夜巡队的朱莉·艾德尔交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254091, 'zhCN', '愿我们能重逢', '<朱莉深吸了一口气。>\\n\\n好了，无论这里发生什么，我都准备好了。', '与被俘的狼人阿尔维斯·艾德尔交谈。', '', '将阿尔维斯的话语带给奥德里克·维恩队长。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254095, 'zhCN', '奥术的洞察', '我不认得这种矿物。这让我不安。一牵扯到金子，人们总会多嘴。可这个？这个让所有人都噤了声。    阿佐拉之塔的法师们也许能告诉我们更多。他们经手的可不是在商路上能寻到的东西。    把碎片带给他们。说话小心些，我可不想在弄清我们手里是什么之前，就让消息传开。', '将矿物碎片送到阿佐拉之塔，寻求关于其特性与潜在用途的魔法洞察。', '', '将矿物碎片交给艾尔文森林阿佐拉之塔的一位法师。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254098, 'zhCN', '混合试剂', '既然两份样本都到手了，我需要把它们妥善调配，为此我们得找当恩·布赖特斯塔。    她负责我们那些不稳定的成分，手也比我稳得多。    把蜘蛛腿和那只装满的瓶子带进塔里交给她。别洒了任何东西，也别让她怂恿你去试任何东西。她这人……好奇心重。', '将样本捆交给当恩·布赖特斯塔。', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254106, 'zhCN', '为矿物附魔', '所以在贾斯珀洛德矿洞发现的储量，即便经长时间暴露也确定不足以派上任何用场，而且看上去是安全的。    但既然迪菲亚在开采它，其中必有蹊跷。把矿物碎片带给阿佐拉之塔里的基塔·费温德，看看她能否为我们附魔，以观察矿物对魔法是否会产生任何反应。', '将矿物碎片带给基塔·费温德。', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254107, 'zhCN', '出乎意料的结果', '处理这个时要非常、非常小心。矿物在接触魔法时显得极不稳定。    我们需要测试它的全部潜力。    到阿佐拉之塔外面去，在当地的野兽身上测试它。', '测试附魔过的矿物碎片。', '', '向艾尔文森林闪金镇的瑟琳娜·薇尔探员汇报你的发现。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(254108, 'zhCN', '最后的挖掘', '你在外头调查矿物用途的时候，我根据早先我们寻回的那些焦黑文件，拼出了狮王之傲旅店里可能是迪菲亚卧底的人。    根据那些文件，应该是旅店里某个干活的人，一个与他们有长久渊源的人。    我们只需盘问店里的几个人，看看谁会露馅。', '在狮王之傲旅店中找出迪菲亚的卧底。', '', '向艾尔文森林闪金镇的瑟琳娜·薇尔探员汇报。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255057, 'zhCN', '民兵训练', '你看上去能自保，对付一两个恶棍不在话下。    $B$B既然你来了，不如拿我们的新兵试试你的身手？哨兵岭之外并不安全，在动身前往迪菲亚地盘之前，你应当确保自己技艺精熟……更别提这批新兵也确实需要练手。$B$B我可不想再把更多傻瓜送去送死，让我看看你的本事。', '与民兵新兵切磋你的技艺。', '', '返回哨兵岭的奥伦斯队长处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255067, 'zhCN', '直至亡灵将我们分离', '如今的婚戒真是乏善可陈，你说是吧？\\n\\n我本想让人按我的喜好打造一枚——当然，要优雅而不失华贵……可我没那个时间，除非……\\n\\n也许你能代我向克拉莉斯下单？我对你的判断……还算放心。我眼下正忙着照料我的那些「候选对象」呢。\\n\\n你可以从一些……我旧日的追求者那里取得金属……他们用不着了。', '在乌鸦岭墓地之下收集婚戒。', '', '与克拉莉斯·纳尔特里交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255068, 'zhCN', '一份未完成的订单', '如果我了解埃莉诺——可惜我确实了解——她绝不会将就，非得要我手头能弄到的最大钻石不可。\\n\\n换作平时，我会从暴风城订一批货，但你要是见过埃莉诺，就知道她最没耐心等。\\n\\n整个暮色森林里，唯一值得切磨的石头，都埋在食人魔栖身的洞穴里。\\n\\n如果你真铁了心要为那个该死的女人冒生命危险，就从那些洞穴里给我带些钻石回来。我会把它妥妥地镶嵌好。', '在维尔戈食人魔丘收集宝石。', '', '返回克拉莉斯·纳尔特里处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255069, 'zhCN', '爱自死亡中诞生', '戒指我已经镶嵌好了，真是美极了！我还从未打造过比这更纯净的珠宝。\\n\\n那金属无缝的光泽，还有这颗配得上贵族的璀璨宝石！\\n\\n只可惜它迟早要被埋进乌鸦岭……', '将交付物带给埃莉诺·泽米尔。', '', '将交付物带给埃莉诺·泽米尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255070, 'zhCN', '耕犁对抗污秽', '在这片被诅咒的田地里，还勉强维系着生命的，只有我可怜的南瓜了……连它们也在我眼前枯萎……要是我能用魔法解决所有麻烦就好了……\\n\\n魔法……对！嘿——别那样看着我，我知道这听起来像什么。但我说的可不是那些黑暗玩意儿。不过这片林子里，我所知道的其他魔法，都掌握在艾德尔农庄那帮偷摸的附魔师手里。\\n\\n你说咱们是不是该让他们派上更好的用场？', '为瑞顿·阿尔萨姆收集附魔之尘。', '', '返回夜色镇的瑞顿·阿尔萨姆处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255071, 'zhCN', '我们中间的陌生人', '最近一直有报告说，有个长相相当古怪的家伙在镇子边缘鬼鬼祟祟地转悠……\\n\\n我在这儿脱不开身……你介意替我去看看吗？', '找到在镇子边缘徘徊的陌生人。', '', '找到在镇子边缘徘徊的陌生人。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255072, 'zhCN', '傻瓜与污秽者', '勇敢地面对凡夫俗子不敢直视之物，是我立下的誓言。哎呀，就在不久前我还闯进了逆风小径！那地方阴森……非常阴森，在几次……战略性撤退之后——\\n\\n我来到了这暮色森林！\\n\\n然而，我却不知何处能寻得刺激！……你能否助我寻得新的冒险？', '为愚蠢的奎尔在暮色森林周围侦察地点。', '', '返回愚蠢的奎尔处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255073, 'zhCN', '窸窣的同居者', '你给我的感觉，是那种懂得如何对付……惹麻烦的生物的人。真走运。看来我们或许有共同的才能。\\n\\n唉，我发现自己需要一个小忙。我本想亲自动手，可我……正忙着别的事。\\n\\n我家屋后的蜘蛛闹得让人受不了。真是了不起的标本——那有力的腿……那毒液。任其浪费未免可惜。\\n\\n可它们扰了我的清静。替我把它们静音吧，亲爱的，好吗？', '在暮色森林击杀黑寡妇幼蛛。', '', '返回埃莉诺·泽米尔处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255074, 'zhCN', '补给与安全', '我们四面都被狼群包围。虽说没不死族或狼人那么危险，却也足以把可怜的旅人撕成碎片。\\n\\n再加上粮食短缺，没有阳光就长不出多少东西，而西部荒野近来因为迪菲亚的问题也拿不出余粮。狼肉当然不是最佳方案，但总比饿死强，而且还能让你一箭双雕。\\n\\n把你收集到的东西交给守夜人道茨，他会确保把它送到夜巡队其他人手里。', '从黑色掠食者幼兽、黑色掠食者獒犬和黑色掠食者身上收集肉。', '', '将肉交给守夜人道茨。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255078, 'zhCN', '见机行事', '啊，今天俺骨头里都感觉到啦，伙计！精灵让俺脚打拍子，心也咚咚跳！$B$B可俺那可怜的妹妹……打日出起就闷在阴凉地里。不笑，不摇，连调子都不哼。这不对劲。$B$B咱需要的是音乐！$B$B俺寻思着……附近那些半人马营寨？他们一天到晚都有那些召雷的法师在念咒跺脚。他们准搁着一两件乐器。', '拉吉里想和妹妹共舞，但纳吉里提不起兴致。也许音乐能让她动起来。从科尔卡尔驯兽师和科尔卡尔风暴使手中收集一支半人马风笛。', '', '返回十字路口的拉吉里处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255079, 'zhCN', '找到节奏', '啊……看来笛子还不足以打动她的性灵。可惜了，伙计。它吹得甜，可她的心依旧沉重。$B$B可咱不放弃！不，不，咱只需要更强劲些的东西。更响些……一面鼓！对，就是它！$B$B鲁娜，那皮革匠，只要有合适的料子，就能替咱缝一面出来……你愿意为我那可怜的老妹妹做这件事吗？', '也许笛子不是对的乐器。收集5张乱齿土狼皮、1张贫瘠之地长颈鹿皮革和3枚银币。然后交给乌娜制作一面鼓。', '', '将材料连同3枚银币作为报酬带给贫瘠之地的鲁娜。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255080, 'zhCN', '随节拍起舞', '这面鼓或许是整个卡利姆多最上乘的，可要是没有鼓棒或槌子来敲……$B$B你离开前，去路对面那间营屋看看，鼓手说不定搁着根多余的棒子。', '牛头人营屋里的舞会已持续了一阵，热闹非凡。问问鼓手布伦博夫是否有多余的鼓棒可以相让。取得鼓棒，连同鼓一起交给塔兹里。', '', '返回十字路口的塔兹里处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255081, 'zhCN', '解读经文', '啊！来得可真巧！$B$B我正急需一位能干的助手！对，对……你再合适不过了。$B$B燃烧之刃的教徒就在北面那座山上安了身，我要破译他们的经文！$B$B我才不管你是怎么弄到手的，把他们的文字带给我，那样我——我们——就能将他们的力量收为己用！', '听闻燃烧之刃教派的势力，马丁请你从燃烧之刃信徒和燃烧之刃打手手中取回一些他们的恶魔经文，以便他研究，或许能学到些他们的力量。', '', '返回十字路口的马丁·莱斯特菲尔德处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255082, 'zhCN', '铲除竞争对手', '你知道啥对生意不好吗？别的地精也在做生意！$B$B尤其是我正想用的那块好端端的淤泥场！$B$B反正风险投资公司跟部落关系也不咋地。跟谁都处不来。真不懂他们到处树敌是怎么赚到钱的。$B$B你干啥不把他们干掉，我拿下淤泥场，你们镇子周围少些敌对势力，大伙都高兴！', '沃尔齐克·齿爆要你去击杀北面淤泥场地的风险投资公司势力。', '', '返回十字路口的沃尔齐克·齿爆处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255083, 'zhCN', '歼灭竞争对手', '风险投资公司的麻烦就在于，他们到处都是！$B$B现在连我的矿里都有他们！好好的矿，满是极珍贵的宝石，他们倒好，自己动手拿！$B$B你上次收拾那些损失可有一手，去那矿里，照上次那样再来一遍！', '沃尔齐克·齿爆要你去击杀北面巨石矿脉矿洞的风险投资公司势力。', '', '返回十字路口的沃尔齐克·齿爆处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255111, 'zhCN', '另寻盟友', '如果暴风城不愿再派援手，那也行，我们还能另寻去处。    红法师塔的法师们一直置身冲突之外，但前些时候巨龙袭击时，他们的一位大法师守护了湖畔镇。圣光知道，我们现在正用得上米内薇娅……    唉，她在那之后不久就失踪了，可一旦湖畔镇失守，下一个倒霉的就是他们，所以或许另一些人会对我们抱有同情。我想你愿意跑一趟去和他们谈谈吧？我觉得他们可不会怎么欢迎我。', '代表伊迪莉娅·所罗门女爵，前往红法师塔与魔网追踪者赫斯特洛会面。', '', '在红法师塔与魔网追踪者赫斯特洛交谈。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255112, 'zhCN', '旧日的错误', '不过，我想这请求是为了整个湖畔镇，不止为她一人……    我们大多数人都不专擅战斗。如果兽人真打上来了，我们会从多里安和赛拉斯的传送门逃走，并在身后关上它。阿莱克斯最有可能伸出援手，可她只是个新手。    <赫斯特洛叹了口气。>    我觉得米内薇娅给镇上的人造成了一种对我们的偏见。如果士兵把装备运上来，我们——维里丹——可以为全部附魔，而我自己的追踪术能察觉兽人是否在进行什么特别危险的仪式。这是我们所能给出的最大诚意了。', '带着赫斯特洛的回复，返回伊迪莉娅·所罗门女爵处。', '', '返回湖畔镇的伊迪莉娅·所罗门女爵处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255113, 'zhCN', '适合豺狼人的食物', '如今狩猎太危险了，而且从西部荒野运来的粮食也断了。我们湖畔镇一向常吃鱼，可湖里的鱼不够光靠它过活。    没有食材我就没法给家里人做饭，不过我倒有个主意，你或许能帮上忙。当地的豺狼人越来越嚣张了，我分不清他们是和兽人结盟，还是单纯无所谓。不管怎样，他们猎获颇丰。我打赌他们甚至还有多余的分出来，如果你懂我意思的话。', '在赤脊山周围的豺狼人营地，为卢卡·廷德尔收集豺狼人食物补给。', '', '返回湖畔镇的卢卡·廷德尔处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255114, 'zhCN', '圣光的赐福', '愿圣光祝福你，善良的旅人！    如果你正踏入荒野，或许你能以圣光的名义帮个小忙？    我们湖畔镇曾经有一件古物，提瑞内尔的圣杯。那是件绝美的东西，我的描述难以尽述其美。它前些时候被影藏豺狼人部族夺走了，而我们无力将其取回。    但如果你在旅途中偶然遇见它，我恳求你将它带回我的礼拜堂。', '为诺里斯神父寻回提瑞内尔的圣杯。', '', '返回湖畔镇的诺里斯神父处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255116, 'zhCN', '收复阿尔瑟磨坊', '由于少有物资运入，我们几乎所有能用得上的补给都告紧缺。其中许多没有立竿见影的解决办法，但湖畔镇一直以来都有座不错的锯木厂，直到石守望陷落。它离黑石氏族近得危险，不过他们其实也没占据那里。    有报告说阿尔瑟磨坊爬满了蜘蛛。你觉得你能把它们清理干净吗？', '击杀阿尔瑟磨坊周围的大狼蛛，帮助湖畔镇居民收复该地区。', '', '返回湖畔镇的伊迪莉娅·所罗门女爵处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(255117, 'zhCN', '完好可用的木板', '眼下我们还有余木，但码头修缮加上桥梁，我看我们的存货撑不了多久。    我听说有人议论要收复阿尔瑟磨坊，可那对现在的我没多大帮助。要我说，那主意本身就疯了，它离兽人的据点太近了。    不过，当时它是匆忙撤离的。我打赌那儿随处都扔着不少好木板。你要是带些给我，我出的金币很可观，比你在暴风城卖掉划算得多。', '为工头奥斯洛从阿尔瑟磨坊收集木板。', '', '返回湖畔镇的工头奥斯洛处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(500004, 'zhCN', '圆环的仪式', '我的门徒们从雷霆崖出发的途中，风怒鹰身女妖从北面的悬崖俯冲而下。$B$B她们被任何雕刻或彩绘之物吸引，撕开行囊，夺走了本为我们下一场仪式准备的神圣图腾。门徒们保住了性命，可那些鹰身女妖如今把图腾当作爪上与羽间的装饰炫耀。没有它们，仪式便无法开始。$B$B去北面找到风怒，$N，夺回她们偷走的东西。把图腾带回给我，好让风再次传递我们的声音。', '收集8个仪式图腾，带给石父圆环的莫尔·萨洛克·风蹄。', '', '返回石父圆环的莫尔·萨洛克·风蹄处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(500005, 'zhCN', '为寒凿营地采伐木材', '是他们派你来的？如果你是又一个那些混账合同经理，就掉头沿原路走回去。我正被糟糕的订单和更糟的文书工作淹到脖子。$B$B刚从铁炉堡又来了一道加急订单。大单。突然的。他们没有给我们增派人手，反而把整个伐木队都换掉了。没时间训练，没时间计划，就一句话：搞定。$B$B我进度落后了，而我讨厌落后。如果你使得动斧头，又不介意寒冷，我正需要帮手。我们要霜松原木，十二根。你在附近的林子里就能找到。$B$B这可不是慈善活儿。我会确保让你觉得划算。', '在寒凿营地附近砍倒丹莫罗的树木，带回12根霜松原木。', '', '返回丹莫罗寒凿营地的布伦娜·铁缝处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(500006, 'zhCN', '不破之冰皮', '看到营地上方那道山脊了吗？最后那位猎人就是在那儿没的。我们只找到了血迹。再无别的。$B$B他们叫它冰皮。冰豹。庞大、无声，而且聪明得躲过了我们的陷阱。它出击迅猛，雪地里只留下一抹鲜红，随后便再度消失。$B$B已有太多人追它而死。这不再关乎骄傲或消遣。只要它还在那些山丘游荡，我们就没法在那儿干活。而我也不会再派自己人消失在寒冷里。$B$B如果你愿意冒这个险，就去吧。但务必一击命中。冰皮不会给你第二次机会。', '你受命追踪并击杀冰皮——那头在营地上方寒凿岭游荡的精英霜刃豹。', '', '返回丹莫罗寒凿营地的老卡甘·厚缝处。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580292, 'zhCN', '史诗难度：哈卡', '在祖尔格拉布的史诗难度下击败哈卡。', '在祖尔格拉布的史诗难度下击败哈卡。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580293, 'zhCN', '升天难度：哈卡', '在祖尔格拉布的升天难度下击败哈卡。', '在祖尔格拉布的升天难度下击败哈卡。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580294, 'zhCN', '升天难度：奥妮克希亚（经典旧世）', '为格鲁尔的巢穴做好准备。', '为格鲁尔的巢穴做好准备。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650141, 'zhCN', '战士的信函', '有人托我把这个交给你留意，$N。它看上去是一块古老的石板，刻着原始的蛮族符文，随着原始的狂怒搏动。石块本身散发着野性的力量，而且它似乎出自阿曼达之手，那位在幽影谷传授蛮族之道的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访阿曼达。', '', '在幽影谷寻访阿曼达。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650142, 'zhCN', '血法师信函', '有人托我把这个交给你留意，$N。它看上去是一卷深红卷轴，沾染着疑似血迹的污痕。羊皮纸随着黑暗魔法能量有节奏地搏动，而且它似乎出自阿拉马杜斯之手，那位在幽影谷修习这些禁忌之艺的血法师。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访阿拉马杜斯。', '', '在幽影谷寻访阿拉马杜斯。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650143, 'zhCN', '时光信函', '有人托我把这个交给你留意，$N。它看上去是一份时光手稿，似乎同时存在于多个时刻之中。文字在我眼前变换，闪现出过去与未来的片段，而且它似乎出自卡莱多鲁姆之手，那位在幽影谷传授时光魔法的青铜龙。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访卡莱多鲁姆。', '', '在幽影谷寻访卡莱多鲁姆。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650144, 'zhCN', '低语宝典', '有人托我把这个交给你留意，$N。它看上去是一页低语羊皮纸，覆盖着唯有不被直接注视时才会变换的符号。奇怪的声音自其中回响，而且它似乎出自赛琳娜·谢达娜之手，那位在幽影谷与禁忌力量沟通的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访赛琳娜·谢达娜。', '', '在幽影谷寻访赛琳娜·谢达娜。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650145, 'zhCN', '恶魔契约', '有人托我把这个交给你留意，$N。它看上去是一份恶魔契约，缠绕着绿色的邪能火焰。羊皮纸烙着灼瞎眼睛的恶魔文字，而且它似乎出自受邪能触碰的埃莉瑞之手，那位在幽影谷教导他人束缚恶魔力量的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访受邪能触碰的弗洛齐。', '', '在幽影谷寻访受邪能触碰的弗洛齐。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650146, 'zhCN', '神圣守护', '有人托我把这个交给你留意，$N。它看上去是一道神圣守护，铭刻着庄严的守护誓约。羊皮纸散发着不可破的防御光环，而且它似乎出自奈德里斯·暗袭之手，那位将自己奉献于守护他人的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访奈德里斯·暗袭。', '', '在幽影谷寻访奈德里斯·暗袭。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650147, 'zhCN', '黑暗骑士精神', '有人托我把这个交给你留意，$N。它看上去是一份黑暗宣言，盖着索罗斯的封印，缠绕着冰冷的暗影火焰。文书述说着以黑暗之力侍奉光明，而且它似乎出自阿赫拉瓦拉之手，那位在幽影谷行走于这条危险道路的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访阿赫拉瓦拉。', '', '在幽影谷寻访阿赫拉瓦拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650148, 'zhCN', '亡缚秘典', '有人托我把这个交给你留意，$N。它看上去是一本以骨束缚的秘典，令周围的空气都为之清冷。我能听到逝者微弱的低语自书页间散发，而且它似乎出自奥金尼的巴雷拉姆之手，那位在幽影谷修习死灵法术的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访奥金尼的巴雷拉姆。', '', '在幽影谷寻访奥金尼的巴雷拉姆。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650149, 'zhCN', '元素的召唤', '有人托我把这个交给你留意，$N。它看上去是一卷元素卷轴，噼啪作响着原始能量。微缩的风暴、烈焰与大地震颤在其表面盘旋，而且它似乎出自普里姆拉之手，那位在幽影谷统御元素的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访普里姆拉。', '', '在幽影谷寻访普里姆拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650150, 'zhCN', '典狱官的呼唤', '有人托我把这个交给你留意，$N。它看上去是一页饱经自然风霜的羊皮纸，仍带着深邃荒野的痕迹——松针、苔藓，以及古老森林的气息。它似乎出自海德里尔·羽翔之手，那位守护幽影谷荒野的游侠。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访海德里尔·羽翔。', '', '在幽影谷寻访海德里尔·羽翔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650151, 'zhCN', '灵魂收割', '有人托我把这个交给你留意，$N。它看上去是一封阴森的信，以黑皮革装订，仿佛在吸走周遭的光。秋尽的余味萦绕在书页间，而且它似乎出自影魔坎尼之手，那位在幽影谷游走于生死之间的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访影魔坎尼。', '', '在幽影谷寻访影魔坎尼。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650152, 'zhCN', '铭刻石板', '有人托我把这个交给你留意，$N。它看上去是一块铭刻石板，刻着随原始力量搏动的发光符文。那些符号似乎比文明本身还要古老，而且它似乎出自雷瑟雷·达尔特罗尔之手，那位居住在幽影谷的符文大师。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访雷瑟雷·达尔特罗尔。', '', '在幽影谷寻访雷瑟雷·达尔特罗尔。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650153, 'zhCN', '天界指引', '有人托我把这个交给你留意，$N。它看上去是一份天界星图，收纳着以真实星光闪烁的星象图。羊皮纸触之温暖，尽管它带着空灵的寒意，而且它似乎出自女猎手娜莉娅之手，那位在幽影谷研习星辰的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访女猎手娜莉娅。', '', '在幽影谷寻访女猎手娜莉娅。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650154, 'zhCN', '雷电的呼唤', '有人托我把这个交给你留意，$N。它看上去是一份风暴手稿，噼啪作响着电能。雷声自书页间低沉地轰鸣，而且它似乎出自库''鲁之手，那位在幽影谷号令暴风骤雨的唤雷者。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访库''鲁。', '', '在幽影谷寻访库''鲁。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650155, 'zhCN', '太阳祈福', '有人托我把这个交给你留意，$N。它看上去是一部金色经文，散发着黎明温暖的光。蒙福的羊皮纸闪耀着治疗能量，而且它似乎出自艾克索达人·特卢萨拉之手，那位为幽影谷带来光明的太阳牧师。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访艾克索达人·特卢萨拉。', '', '在幽影谷寻访艾克索达人·特卢萨拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650156, 'zhCN', '神圣誓约', '有人托我把这个交给你留意，$N。它看上去是一份神圣誓约，写在散发圣光的蒙福羊皮纸上。文书令近旁的人心充满勇气，而且它似乎出自艾莉奥拉之手，那位在幽影谷担任圣殿骑士的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访艾莉奥拉。', '', '在幽影谷寻访艾莉奥拉。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650157, 'zhCN', '机械结构图', '有人托我把这个交给你留意，$N。它看上去是填满精密蓝图的机械结构图。我能听到书页间传出的发条装置微弱滴答声，而且它似乎出自乔罗·迅焰之手，那位在幽影谷劳作的工匠。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访乔罗·迅焰。', '', '在幽影谷寻访乔罗·迅焰。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650158, 'zhCN', '剧毒配方', '有人托我把这个交给你留意，$N。它看上去是一部皮革汇编，散发着奇异毒素的恶臭，绿色的蒸气不时从书页间渗出。它似乎出自科''拉尔·牙变之手，那位在幽影谷研习毒液与解药之术的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访科''拉尔·牙变。', '', '在幽影谷寻访科''拉尔·牙变。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(650159, 'zhCN', '审判官的指令', '有人托我把这个交给你留意，$N。它看上去是一道蒙福的指令，以正义之火燃烧。其神圣文字旨在将恐惧植入堕落者的心，而且它似乎出自哈伦多尔·屠暗者之手，那位在幽影谷追猎腐败的人。在你继续此地的职责之前，我劝你毫不犹豫地读一读它。', '在幽影谷寻访哈伦多尔·屠暗者。', '', '在幽影谷寻访哈伦多尔·屠暗者。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(999913, 'zhCN', '失踪的报告', '你可知道，当我缺了这么多报告时，整理文件有多难？$B$B我明白，归档文书这种枯燥的差事有些人不放在心上，可这并不意味着它不重要。$B$B我缺了一份我们巡逻员的野外报告，他走的是从哨兵岭到艾尔文森林边境那条路线。替我找到他，把他的报告带回来，既然他自己懒得动手。', '找到失踪巡逻员的报告。', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(999914, 'zhCN', '半详报告', '检视尸体时，你找到了巡逻员那份写了一半的报告。$B$B这应当被送回哨兵岭——档案员会想知道发生了什么。', '将半详报告交还档案员塞尔诺。', '', '', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(999933, 'zhCN', '沾满唾液的报告', '这羊皮纸令人作呕——满是唾液与血肉。这些文件的作者碎裂地躺在你四周，已无法辨认。$B$B档案员塞尔诺会想看看这份报告，她会认出这是谁。', '将沾满唾液的报告交给档案员塞尔诺。', '', '', NULL);
